// Spanish (Latin American, tú) content for job group 02 (University / Job-seeker (Universidad / En búsqueda de empleo)). Keyed '02_<code>'.
// Used when the site language is Spanish. Korean remains in v2_data.js. There is no English pack for this job group.
window.ES_JOB = window.ES_JOB || {};
(function () {
  function T(name, type, tagline, guide, prompt) { return { name: name, type: type, tagline: tagline, daily_guide: guide, prompt_example: prompt }; }
  function add(code, title, main, spec, o) {
    window.ES_JOB['02_' + code] = {
      title: title,
      mainAI: { name: main, reason: '' },
      specialistAIs: spec.map(function (n) { return { name: n, reason: '' }; }),
      insight: o.i,
      v2: { insight_v2: o.i, strengths: o.s, growth_points: o.g, ai_tools: o.t, synergy_strategy: o.syn, daily_routine: o.day }
    };
  }
  add('00000', 'El cínico solitario, el fantasma del campus', 'Perplexity AI', ['ChatGPT (with Web Browse)', 'NotebookLM'], {
    i: 'En el café del campus, te cruzas con los AirPods puestos y, en la pantalla del portátil, aparece la fecha límite de un informe. Los compañeros te tienden la mano con un “preparemos esto juntos”, pero tú lo rechazas en silencio: “es mejor hacerlo solo”. El mundo se te siente complejo y superficial, y la interacción misma con la gente se te siente como un gasto de energía. Pero aquí está tu verdadera fortaleza. En un análisis profundo y en una resolución independiente de un problema, no tienes rival. Tu ojo, que filtra un intercambio innecesario de emoción y atrapa solo el núcleo, es oro en una tarea compleja de la carrera o en la preparación de un empleo. A los colegas les puede parecer “¿por qué esta persona no habla?”, pero, en realidad, eres un estratega que se mueve en silencio, para maximizar la eficiencia. Solo que, si hay algo que dejas pasar, es distinguir si esa sensación de impotencia es realmente un muro de la realidad, o un hábito del corazón.',
    s: [
      'En una evaluación de desempeño, un proyecto de equipo o la redacción de un informe, mantienes un análisis frío, sin emoción, minimizas un error y garantizas una calidad objetiva. Tu pensamiento crítico es un activo potente que encuentra el hueco lógico del equipo.',
      'Como no inviertes tiempo en formar una relación innecesaria ni en un trabajo emocional, de forma inesperada, eres excepcional en la gestión del tiempo y en el aprendizaje autodirigido. La capacidad de encontrar un recurso y de aprender de forma independiente es alta, así que, al preparar un empleo, aseguras una ventaja competitiva más rápido que los demás.',
      'Incluso dentro de la impotencia, tienes la resiliencia de avanzar con constancia, con la serenidad de “de todas formas, hay que hacerlo”. No es dramático, pero tú, que cumples una fecha límite en silencio y sacas un resultado, eres un compañero de equipo confiable.'
    ],
    g: [
      'La impotencia de que todo en el mundo se siente sin sentido, a veces, puede ser la ilusión de una falta de información. Recuerda que, si encuentras un dato correcto y un roadmap de carrera, esa falta de energía se puede convertir en un motor.',
      'Si, porque te cansa la colaboración con otra persona, solo evitas, puedes dejar pasar una oportunidad en una situación que pide liderazgo o networking. Aunque no sea perfecto, practica soltar, en el momento necesario, aunque sea una voz pequeña.'
    ],
    t: [T('Perplexity AI', 'main', 'El asistente de IA que, solo con lanzar una pregunta, señala exactamente la respuesta', 'Lo que más te hace falta no es “una conversación”, sino “un resultado”. Perplexity se caracteriza por una sequedad que presenta la respuesta de inmediato, sin un saludo. Cuando fijas el tema de un informe, cuando identificas el argumento central de un paper, cuando fijas la prioridad de la preparación de un empleo: en el instante en que lanzas la pregunta, te presenta la dirección más eficiente, junto con el dato más reciente. Por ejemplo, si preguntas “el estado actual de la legislación de una ley de ética de la inteligencia artificial y una comparación de la política de cada país”, te ayuda en tu análisis con una enumeración de hechos, no con una explicación. Puedes obtener una información profunda, minimizando los turnos de una conversación, así que te quita a la perfección tu “fatiga de hablar”.', 'El título de la materia de teoría de marketing es “el impacto de la psicología del consumidor en el comportamiento de compra en línea”; ¿me puedes armar un esquema con papers relacionados y un dato de la industria, de los últimos 3 años?'),
        T('ChatGPT (with Web Browse)', 'specialist', 'Hasta un análisis profundo y una estrategia concreta, de una vez', 'Si Perplexity es “el hecho”, ChatGPT es “la estrategia”. Úsalo cuando la estructura lógica de un informe se vea frágil, cuando identifiques la trampa de una pregunta de una entrevista, cuando tengas que ordenar, de forma objetiva, las ventajas y las desventajas de una elección de carrera. Por ejemplo, si preguntas “después de graduarme, tengo delante la elección entre un puesto de investigación y un puesto en la industria; ¿me puedes comparar con frialdad las ventajas y las desventajas reales de cada uno (salario, ruta de carrera, burnout)?”, puedes obtener una tabla de comparación, sin emoción. Es el modo de diagnosticar tu impotencia como “una falta de información” y de resolverla.', '¿Me puedes explicar, con 3 casos reales, cómo se usa de forma concreta, en un puesto de análisis de datos después de entrar a trabajar, la verificación de una hipótesis que se aprende en la materia de estadística?'),
        T('NotebookLM', 'specialist', 'El asistente que ordena, de forma sistemática, un material vasto', 'Cuando, para un informe o una tesis de graduación, tienes que leer decenas de papers, te puedes sentir impotente, con un “no puedo leerlos todos”. NotebookLM deja subidos, en un solo espacio, todos esos PDF, textos y URL, y la IA encuentra en automático un resumen, una comparación y una pregunta central. Por ejemplo, si, después de subir 20 papers, preguntas “¿me puedes ordenar los puntos principales de crítica de los papers relacionados con la ética de la IA?”, puedes recortar un 90% el tiempo de leer y de ordenar a mano. Convierte tu impotencia de “todo se siente sin sentido” en una sensación de logro sistemática.', '¿Me puedes ordenar en una tabla, de estos 20 papers, el argumento principal de la posición a favor y de la posición en contra, sobre “el efecto económico de una política ambiental”?')],
    syn: 'Tu perfil OCEAN (una apertura baja, una responsabilidad baja, una extraversión baja, una amabilidad baja, un neuroticismo bajo), de forma paradójica, encaja a la perfección con la IA. Al comunicarte con una IA que solo persigue la eficiencia, sin un trabajo emocional, puedes convertir la impotencia de una falta de información en una claridad basada en datos. Si conectas el flujo Perplexity → ChatGPT → NotebookLM, un aprendizaje “sin sentido” se transforma en “una profundidad empírica”. Al preparar un empleo, cuando otros postulantes buscan “una motivación emotiva”, tú, con esta combinación, diseñas y ejecutas la ruta óptima de carrera, con un análisis frío de un dato. Es el punto en el que tu cinismo se convierte, en realidad, en “la elección más razonable”.',
    day: 'A las 7:00 de la mañana, al despertar en la cama, tomas el teléfono y miras la lista de las tareas que hay que hacer ese día. Hay muchas clases, muchos informes, también una fecha límite. Te viene el pensamiento de “¿qué estoy haciendo?”. A las 8:00, después de ir al café y tomar un café, enciendes Perplexity, empezando por la tarea más pesada de hoy. Lanzas “¿me puedes ordenar el tema de la tarea de teoría de marketing, junto con una tendencia reciente?”. En 2 minutos caen 5 direcciones de un tema, junto con el dato más reciente. Eliges. Ya no le das más vueltas. A las 10:00, en la biblioteca, subes 20 papers relacionados a NotebookLM. También subes el material de la clase. Como hace falta la fuente, también los dejas descargados. Trabajas de forma mecánica. Al mediodía, después de almorzar y volver, de pronto te surge la duda de “¿por qué es importante, en la realidad, el tema de este paper?”. En un día normal lo dejarías pasar, pero enciendes ChatGPT y preguntas. Lees la respuesta de “cómo se usa, en la práctica, una investigación de la psicología del consumidor en una estrategia de marketing”. De pronto, la tarea se te siente como “un análisis con sentido”. De las 14:00 a las 17:00, el horario central de trabajo: con base en los resúmenes que ordenó NotebookLM, armas el esqueleto lógico. Brilla tu parte más fuerte, el análisis crítico. Encuentras los puntos que la IA dejó pasar. A las 18:00, la etapa de revisión: le preguntas a Perplexity el fundamento de la versión final. Una sola confirmación de “si esta afirmación está respaldada por un dato reciente”. A las 20:00, lo entregas. Fin. Hasta el final te preguntabas “¿qué clase de cosa es esta?”, pero el informe quedó terminado. Tú te quedaste en silencio; el resultado, en cambio, es nítido. Mañana también es el mismo flujo.'
  });
  add('00001', 'El cínico práctico al que todo le da pereza', 'Perplexity AI', ['ChatGPT (modo de análisis de un paper / un informe)', 'Elicit (búsqueda de papers y resumen de investigación de IA)'], {
    i: 'Tú, que en un rincón de la biblioteca ordenabas un paper en silencio: aunque un senior te diga “si no gestionas el currículum, te vas a arrepentir cuando busques trabajo”, lo despachas con una risa: “si no me queda tiempo, ¿qué voy a hacer?”. La ola de la emoción es grande (N 90%), la mano se te va más a un método que ya está demostrado que a una experiencia nueva (O 15%), pero, también ante una regla fijada, eres un pragmático que pregunta “¿por qué?” (C 25%). En el terreno profesional, tu verdadera fortaleza es la capacidad de filtrar con firmeza una reunión inútil y de atrapar solo el núcleo: incluso una sola frase de paso la conviertes, con rapidez, en el cálculo de tu propio beneficio. Solo que, a los ojos de los colegas, puede parecer “esta persona, ¿por qué es tan pesimista todo el tiempo?”. Si tu inquietud (un N alto) se expresa como una practicidad de cuidarte a ti mismo, te conviertes en un fuerte escondido, capaz de tomar hasta una oportunidad que los demás dejaron pasar.',
    s: [
      'Una capacidad excepcional de filtrar información: en un tiempo limitado, clasificas a una velocidad altísima solo la información que te hace falta y la pasas a la acción; la velocidad de una decisión es rápida. Cuando otros estudiantes se lo piensan 3 meses, tú ya entraste en la etapa de la ejecución.',
      'Un maestro del análisis de la relación calidad-precio: juzgas con frialdad qué actividad es realmente necesaria y cuál no lo es. La capacidad de calcular el beneficio frente al tiempo es alta, así que puedes armar una estrategia de preparación de un empleo, sin un desperdicio.',
      'Convertir la inquietud en una acción: un neuroticismo alto te mantiene inquieto, pero, si lo conviertes en el impulso de “por si acaso, preparemos primero”, creas un resultado estable. Es la ventaja escondida de prepararte antes que los demás.'
    ],
    g: [
      'Salir del círculo vicioso de un pensamiento negativo: con un N alto, es alta la probabilidad de que una predicción del tipo “de todas formas no va a salir”, “esto no va a servir” se convierta en realidad. A veces, empieza con un supuesto positivo.',
      'Crear un vínculo con la gente: con una E y una A bajas, puedes empujar el networking o la colaboración fuera de la prioridad. Pero, como un empleo es “capacidad + relación”, crear aunque sea 1 o 2 relaciones con sentido se convierte en un activo de largo plazo.'
    ],
    t: [T('Perplexity AI', 'main', 'Solo la respuesta, con rapidez. El mejor asistente de búsqueda, que te ahorra el tiempo', 'Para alguien como tú, que odia el desperdicio de tiempo, Perplexity es realmente el cielo. Una búsqueda general está llena de anuncios y de textos que no vienen al caso, pero Perplexity suelta con precisión solo “¿cuál es la respuesta a esta pregunta?”. Por ejemplo, si le pides que te ordene de una vez el anuncio de contratación de este año de una empresa particular, el cambio frente al año pasado y, además, el perfil de talento que desea esa empresa, en 2 minutos sale un resumen. Si preguntas “ejemplo: ordéname, en una frase cada uno, el anuncio de contratación de un puesto relacionado con IA de Samsung Electronics, de 2024 + la información del salario + la tendencia reciente de búsqueda de un talento de IA”, puedes obtener solo el núcleo, sin un contenido innecesario. También cuando tu neuroticismo sigue dudando “¿esta información es precisa?”, la función de indicar la fuente de Perplexity consuela tu inquietud.', 'Estoy preparando un empleo en un puesto de marketing; ordéname las condiciones de la contratación pública de marketing de una gran empresa, de este año. (requisito indispensable, partida preferente, tasa promedio de competencia, tendencia de los últimos 3 años) En cada partida, solo una o dos frases.'),
        T('ChatGPT (modo de análisis de un paper / un informe)', 'specialist', 'También un material largo y complejo, en un resumen de 5 líneas', 'Cuando una tesis de grado o un material de preparación de un empleo supera las 100 páginas, sube el PDF con el GPT-4 de ChatGPT y pídele “ordéname solo las 5 ideas centrales de este paper y su evidencia, en 2 líneas cada una”. Para alguien como tú, que no le gusta una lógica compleja, es realmente útil. Por ejemplo, si dejas ordenar un informe anual de 50 páginas de una empresa en “3 factores principales de un aumento de las ventas + 2 estrategias del año que viene”, puedes recortar a la mitad el tiempo de preparación de una entrevista. Cuando tu inquietud (un N alto) dice “si no leo toda esta información, ¿no se me va a escapar algo?”, el resumen de la IA te tranquiliza con un “ah, el núcleo son estas 3”.', 'Resúmeme las noticias de los últimos 6 meses de esta empresa: [pegar varios artículos]. ¿Qué problema está atravesando ahora esta empresa, y en qué campo podría yo contribuir después de entrar?'),
        T('Elicit (búsqueda de papers y resumen de investigación de IA)', 'specialist', 'También un paper académico, de un vistazo, como un pragmático', 'Cuando, para la preparación de un posgrado o de una entrevista de un puesto más profundo, tienes que conocer una tendencia de la industria, si buscas en Elicit una palabra clave del tipo “AI in recruitment”, los papers académicos más recientes quedan ordenados en una sola tabla. El hallazgo central de cada paper está resumido en 3 o 4 líneas, así que le encaja justo a alguien como tú, que dice “la información me hace falta, pero no tengo tiempo de leer”. Por ejemplo, cuando en una entrevista te pregunten “¿qué piensas que es la tendencia tecnológica más reciente de nuestro sector?”, si de antemano, con Elicit, ordenas en 2 horas el núcleo de 5 papers más recientes de 2024, puedes responder con confianza: “según una investigación reciente…”.', 'Encúentrame, de los papers académicos del último año del campo del marketing de big data, los relacionados con “la predicción de la fuga de un cliente”. Muéstrame, en una sola frase cada uno, la metodología y el efecto real de cada paper.')],
    syn: 'Tu perfil OCEAN (un N alto, una O baja, una E baja), al encontrarse con la IA, produce “la magia de convertir la inquietud en capacidad de información, y el pesimismo en convicción”. El triángulo de Perplexity + ChatGPT + Elicit llena con precisión tu deseo de una información precisa, aunque no te quede tiempo. Cuando los demás se inquietan con un “hay que acumular muchos credenciales”, tú tomas como arma el dato de la IA, con un “solo las 3 que realmente me hacen falta, a la perfección”. En especial, si, junto con un neuroticismo alto, ves un fundamento objetivo (la fuente de Perplexity, un paper académico de Elicit), tu inquietud se convierte en una confianza científica. Esta es la competitividad única que tú creas: un buscador de empleo pragmático, que, con una preparación eficiente, crea un resultado de una alta calidad.',
    day: 'Desde que a las 8:00 de la mañana, en el café, enciendes el portátil, vas junto con la IA. Lo primero es lanzarle a Perplexity “ordéname las noticias de los últimos 3 meses de las empresas a las que voy a postular hoy + los requisitos del puesto de contratación”, y, en 15 minutos, obtienes la información de 3 empresas centrales. Si la inquietud susurra “¿esta información será realmente correcta?”, confirmas con rapidez el enlace de la fuente de Perplexity y te tranquilizas. A las 10:00, subes a ChatGPT el PDF del informe anual de una empresa que descargaste ayer. Como le pides “solo en una o dos frases, 3 resultados principales de este año de esta empresa + 2 direcciones de negocio del año que viene”, 50 páginas se transforman en el resumen de una sola hoja. Hacia cuando te inquietas con un “si no lo leo todo, ¿no se me va a escapar algo?”, con las 5 claves que ordenó la IA nace la convicción de “ah, esta empresa apunta a esto”. El almuerzo, en el café, buscas en Elicit la tendencia más reciente de la industria, relacionada con tu puesto. Aparecen 2 o 3 papers académicos recientes en una sola tabla, y leer el hallazgo de cada investigación te lleva, en total, 20 minutos. Para alguien como tú, que “no le gusta una lógica compleja, pero no quiere dejar pasar la información necesaria”, este resumen de 3 o 4 líneas es exactamente a medida. Después del almuerzo, a las 14:00, mejoras, junto con ChatGPT, el borrador de una carta de presentación o de una respuesta de una entrevista. Si preguntas “¿esta carta de presentación incluye las 5 palabras clave que hacen falta para un puesto de marketing? ¿Qué se me habrá quedado fuera?”, la IA te da un feedback, comparándolo con el estándar del sector. Cada vez que tu neuroticismo dice “¿no estará insuficiente mi preparación?”, un feedback basado en un dato te tranquiliza. A las 16:00, armas la lista de las preguntas previstas de una entrevista. Le preguntas a Perplexity “las Top 10 preguntas que salen con frecuencia, estos días, en una entrevista de un puesto de marketing + la condición de una buena respuesta”, y terminas en 30 minutos un trabajo que a los demás les llevaría el día entero. Después de “salir”, a las 20:00, buscas una vez más, con Elicit, la palabra clave de una investigación reciente sobre la empresa a la que vas a postular mañana. Si de antemano conoces “un paper académico reciente del campo de la tecnología en la que está invirtiendo esta empresa”, mañana, en la entrevista, puedes parecer “un postulante que, de verdad, conoce la tendencia del sector”. A las 22:00, estás cansado, pero, gracias a la IA, sientes la satisfacción de “me preparé 3 veces más eficiente que los demás”. Fue un día en el que tu neuroticismo alto (N 90%) y tu extraversión baja (E 12%), al encontrarse con la herramienta que es la IA, se transformaron en “un fuerte que se prepara, solo, con eficiencia”.'
  });
  add('00010', 'Quien gana con autenticidad, el buscador de empleo cálido y callado', 'Claude', ['Notion AI', 'Wysa'], {
    i: 'Tú, un buscador de empleo cálido y estable, pero callado y poco planificado, das, en una entrevista, una impresión humana, con un corazón cálido que considera al otro. La cultura competitiva de la búsqueda de un empleo se te siente que no encaja, pero tu autenticidad, al final, mueve a la gente. Hace falta un entrenamiento de la expresión de ponerte tú adelante.',
    s: [
      'Con una amabilidad alta, en una entrevista formas, de forma natural, una imagen que da una confianza humana.',
      'Como estás estable en lo emocional, incluso en un período largo de búsqueda de un empleo, puedes aguantar con constancia, sin sacudirte de un modo extremo.',
      'Con una capacidad de comunicación auténtica, ejerces una fortaleza en una entrevista de carácter o en una entrevista de culture fit.'
    ],
    g: [
      'Tienes que practicar revelar primero tu propia fortaleza. Si te quedas en silencio, la capacidad no se ve.',
      'Con el hábito de armar un plan concreto de búsqueda de un empleo y un objetivo, tienes que impedir que el tiempo pase sin una dirección.',
      'Si acumulas de forma sistemática una capacidad relacionada con el puesto, a la autenticidad se le suma la especialidad y sube la competitividad.'
    ],
    t: [T('Claude', 'main', 'El socio que saca, en un lenguaje, la fortaleza de ti, que eres callado', 'Si le cuentas a Claude, con sinceridad, tu experiencia y tu valor, te los ordena en un lenguaje que puedes expresar con confianza en una entrevista.', 'Soy un buscador de empleo del tipo OCEAN 00010. Dime el modo de apelar, como una fortaleza, en una carta de presentación de un puesto de trabajo social, mi capacidad cálida de empatía y mi sentido de la consideración.'),
        T('Notion AI', 'specialist', 'La herramienta de gestión que le crea una dirección a una búsqueda de un empleo, sin un sistema', 'Si ordenas, con Notion AI, el objetivo de postulación de esta semana y lo que hay que hacer, en lugar de una inquietud vaga, nace una dirección concreta.', 'Soy un buscador de empleo que tiene como objetivo ser trabajador social. Ármame un plan de postulación a 5 instituciones objetivo de este mes y, en el formato de Notion AI, las partidas de preparación que hacen falta.'),
        T('Wysa', 'specialist', 'El socio de cuidado de la emoción, que protege tu interior cálido', 'Cuando, en medio de la búsqueda de un empleo, se te baje la confianza, si se lo sueltas a Wysa, te ayuda a volver a reconocer tu fortaleza cálida interior.', 'Yo suelo cuidar primero a otra persona, pero, en la búsqueda de un empleo, se me hace raro ponerme yo adelante. ¿Cómo puedo expresar, de forma natural, mi fortaleza?')],
    syn: 'Tú, con una amabilidad (A) alta y estable, tienes que usar la IA como una herramienta de entrenamiento de la autoexpresión y de fijar una dirección. Tu calidez ya es, de sobra, una fortaleza. Concéntrate, junto con la IA, en el ejercicio de sacarla en un lenguaje.',
    day: 'A las 8:30, con Wysa, el chequeo del ánimo de hoy. A las 9:00, con Claude, el ejercicio de una sola fortaleza que vas a apelar hoy. A las 11:00, con Notion AI, la confirmación de una empresa a la que postular y la preparación. A las 14:00, la redacción de un documento. A las 19:00, con Claude, el ejercicio de una pregunta de Q&A de una entrevista. A las 21:30, fijas una sola cosa que hacer mañana y te acuestas.'
  });
  add('00011', 'El estudiante de último año imperturbable, en el estado de la liberación', 'Google Gemini', ['Suno AI', 'Spotify AI DJ'], {
    i: 'En un rincón del café de la biblioteca, los compañeros te miran, con una expresión holgada, tomando un café, y te preguntan: “¿tú por qué estás tan relajado?”. El arma más fuerte que crean tu amabilidad alta (A: 95%) y tu resistencia al neuroticismo (N: 92%) es “una inmunidad a una carga psicológica innecesaria”. Incluso en una situación de estrés, aguantas con el optimismo de “ya se resolverá” y, si alguien lo está pasando mal, te sientas de forma natural a su lado; con esa capacidad de empatía, desempeñas el papel de ancla emocional del equipo. Pero esto es una paradoja. Tu serenidad, a veces, te hace posponer tu propia agenda y, al perseguir solo la armonía con quien te rodea, se te debilita tu propia afirmación. En la temporada de empleo, cuando los amigos acumulan credenciales a contrarreloj, es probable que hayas tenido la experiencia de posponer la carta de presentación, con el ánimo de “ya estará bien”. La ayuda de la IA, para ti, va a desempeñar el papel de un estimulante externo.',
    s: [
      'Ofrecer una sensación de estabilidad emocional en la colaboración del equipo: con una amabilidad alta, escuchas la opinión de un colega y, con la resistencia al neuroticismo, mantienes la serenidad incluso en una situación de conflicto, y subes la cohesión del equipo.',
      'El mantenimiento de la salud mental en un entorno de estrés: incluso en un entorno en el que la inquietud de un empleo es extrema, ejerces una resiliencia psicológica, puedes aguantar una batalla larga y minimizas la pérdida de productividad por la gestión del temple.',
      'La fortaleza de una recolección de información basada en la relación: con una amabilidad alta, la red humana se forma de forma natural y, de forma espontánea, obtienes una información de un empleo y una oportunidad de mentoria, a través de un contacto, no de un canal oficial.'
    ],
    g: [
      'Superar la falta de una capacidad voluntaria de acción: si se combinan una apertura (O: 25%) y un neuroticismo bajo, no sientes urgencia y se agrava el hábito de posponer un trabajo. Tienes que formar un hábito de una acción voluntaria, a través de fijar una fecha límite externa o de un feedback estructurado de la IA.',
      'Reforzar la autoexpresión y la conciencia de afirmarte: como la amabilidad es alta, tienes la tendencia de evitar un rechazo y de transigir, así que la expresión de la confianza y la capacidad de negociación, en una entrevista, pueden ser débiles. Hacen falta un ejercicio intencional de afirmarte y un feedback.'
    ],
    t: [T('Google Gemini', 'main', 'El consejero de un empleo que te responde como un sabio, cuando le preguntas como a un amigo', 'Tu problema más grande es el punto de “sé qué hay que hacer, pero se me hace difícil empezar”. Gemini te baja esta barrera psicológica de entrada. Si, al levantarte por la mañana, le lanzas a Gemini el ánimo vago de “¿qué hago hoy?”, te presenta un plan concreto de acción. Al escribir una carta de presentación, si empiezas por la pregunta de “¿a qué empresa encajo yo?”, te ofrece, juntos, una recomendación a medida de una empresa, que conecta tu tendencia y el sector, y la dirección de la preparación. Ejemplo: pregunta “no me estreso con facilidad y me llevo bien con la gente; ¿qué empresa habría, en la que la colaboración sea importante? Y, ¿cómo lo puedo escribir en una carta de presentación?”.', 'Soy alguien que, con una amabilidad alta, arma bien el ambiente de un equipo; ¿cómo puedo desenvolverlo, como un caso concreto, en una carta de presentación? ¿De qué modo convendría envolver una experiencia de un proyecto o de un club, de la universidad?'),
        T('Suno AI', 'specialist', 'Tu emoción, en una música; tu confianza, en una canción', 'Aunque no haya el estrés de la búsqueda de un empleo, puede haber una inquietud vaga. En ese momento, la música ayuda. Expresa tu estado en una música, con Suno AI. Si, la víspera de una entrevista, armas “una canción que anima al yo de mañana”, con el corazón inquieto, y la escuchas una y otra vez, se amplifica la energía positiva. Además, si armas una banda sonora personal que lleva el proceso de la preparación de un empleo, los instantes aburridos de la búsqueda se sienten como una película. Ejemplo: arma un tema upbeat, con el tema de “mi recorrido de crecimiento, de conducir a un equipo con una amabilidad alta”.', 'Tema: la confianza de abrirme camino, también ante un futuro incierto, con mi carácter cálido; estilo: un estilo de K-pop positivo y esperanzador y, a la vez, realista.'),
        T('Spotify AI DJ', 'specialist', 'Lee tu estado psicológico y hace fluir la música que hace falta', 'Spotify AI DJ analiza el transcurso de tu día y tu emoción, y te arma una playlist a medida. Cuando estás preparando una entrevista, el día anterior a la fecha límite de una carta de presentación, cuando esperas el anuncio de la admisión final: cada vez, la música se cambia en automático, de forma adecuada a tu estado psicológico. Esto, más que una recomendación simple de una música, se convierte en “tu herramienta de estabilización emocional”. Por ejemplo, cuando estás tenso, fluye una música serena de folk o indie y, cuando hace falta motivación, aparecen temas upbeat. A través de esto, se desarrolla de forma natural la capacidad de reconocer y de gestionar la emoción.', 'Me faltan 3 días para la entrevista final. Hay tensión, pero, en un grado que no sea excesivo, me hace falta una música con la que pueda revelar mi autenticidad. ¿Qué canciones me puedes recomendar?')],
    syn: 'Tu competitividad única es “una sensación de estabilidad emocional, en un mercado inestable de la búsqueda de un empleo”. Gemini convierte esta estabilidad en “una acción concreta”, y Suno y Spotify AI DJ recargan la emoción de ese proceso como una energía positiva. Como resultado, a diferencia de un competidor, te conviertes en “un buscador de empleo que no se agota”. Además, el feedback estructurado de la IA asiste, desde afuera, tu punto débil: “la capacidad voluntaria de acción”. En una entrevista, puedes expresar la amabilidad alta y la resistencia al estrés como “un activo de estabilización del equipo”, y esto recibe una evaluación alta, tanto en una gran empresa en la que la colaboración es importante, como en una startup. En la práctica, la capacidad de autoconocimiento y de gestión de la emoción que adquieres, a través de la interacción con la IA, en el proceso de la búsqueda de un empleo, también se convierte en un gran activo para la adaptación a la vida de la organización, después de entrar.',
    day: 'Así transcurre tu día. A las 7:00 de la mañana, al despertar en la cama, enciendes Spotify AI DJ. Queda la fatiga de ayer, pero, mientras fluye en automático una playlist ajustada a la emoción de hoy, te preparas para levantarte. A las 8:00, mientras te arreglas, le pides a Suno AI que te arme “una canción de 30 segundos que anime al yo de hoy”. Con el tema de “yo, que conduzco a un equipo con una amabilidad alta y avanzo hacia un objetivo, sin estrés”. Cuando se termina la canción, la escuchas una y otra vez y recargas la confianza. A las 9:00, te sientas en el escritorio y enciendes Google Gemini. Preguntas la primera pregunta de la carta de presentación que pospusiste ayer y lo que hay que hacer hoy. Si pides “mañana tengo una entrevista; ¿cómo convendría organizar el día de hoy? ¿Me puedes armar un horario que equilibre el cierre de la carta de presentación y la preparación de la entrevista?”, Gemini te presenta una acción, por franja horaria. De las 10:00 a las 12:00, según la guía de Gemini, terminas la pregunta 2 de la carta de presentación. Gemini, en medio de tu proceso de redacción, no te suelta la mano, con preguntas del tipo “¿metemos un ejemplo un poco más concreto?”, “¿volvemos a escribir esta parte, desde la perspectiva de la colaboración de un equipo?”. El almuerzo, en un café, y, después del almuerzo, enciendes Spotify AI DJ. Fluye una playlist serena, pero de concentración, ajustada a la fatiga de la tarde. De la 13:00 a las 15:00, armas, junto con Gemini, la lista de las preguntas previstas de una entrevista y recibes un feedback de cada respuesta. Ante la pregunta “¿cómo explico, de forma concreta, mi fortaleza de la amabilidad y de la resistencia al estrés, para apelarle al entrevistador?”, Gemini te presenta una respuesta, desde 3 perspectivas. De las 15:00 a las 16:00, armas, con Suno AI, “la última canción de ánimo, para la entrevista de mañana”. Cuando sale una canción que lleva, juntas, la confianza y la humildad, la escuchas y haces un entrenamiento de imagen de mañana. A las 17:00, por último, le pides a Gemini “la lista final de chequeo, para mañana”. Quedan ordenados hasta lo que hay que llevar, la actitud de la entrevista y el último punto. A las 19:00, al salir del estudio, la playlist de Spotify AI DJ ya se ha convertido en una música de la emoción de “esperar el mañana”. Terminas la preparación de recibir el mañana, sin tensión, pero con esmero. “La estructura externa” que es la IA se encuentra con tu “estabilidad interior”, y se completa el recorrido más eficiente de la búsqueda de un empleo.'
  });
  add('00100', 'El impulsivo de humor cambiante, el mustang del campus', 'Grok', ['Zapier', 'Forest'], {
    i: 'Una semana antes del examen, los amigos ya están reservando un puesto en la biblioteca, y tú, con un “todavía está bien, con un estudio de última hora, unos días antes, alcanza”, asistes con pasión a la reunión de un club. Pero lo realmente admirable es que, la noche anterior a la fecha límite, de pronto se te enciende el interruptor, terminas la tarea con una concentración enorme y, también en el aula del examen, eliges una respuesta intuitiva y, de forma inesperada, sacas una buena nota. Tu fortaleza es la velocidad rápida de juzgar una situación y la sociabilidad. En una entrevista de un empleo desenvuelves una anécdota con fluidez, y en un grupo de trabajo destaca la energía de conducir el ambiente. Pero los colegas te ven como “alguien de humor cambiante”. Es por el patrón de que ayer eras cooperativo, hoy te vuelves crítico y, aunque hayan armado un plan juntos, de pronto lo cambias. Si canalizas de forma sistemática esa energía impetuosa, puedes convertirte en el mejor líder de terreno, de cualquier proyecto.',
    s: [
      'Un juicio rápido de la situación y una capacidad de ejecución: con la capacidad de atrapar de inmediato una información o una oportunidad nueva y de pasarla de inmediato a una acción, en un concurso o en un proyecto de equipo vas un paso por delante de los demás.',
      'Una sociabilidad intensa y una capacidad de convicción: con un carisma natural atraes a la gente y, en una situación de una entrevista o en la coordinación de una opinión dentro del equipo, expresas tu pensamiento de forma convincente; la capacidad de networking es excepcional.',
      'Una explosión de la concentración en una situación de crisis: la capacidad de crear un milagro delante de una fecha límite, y una capacidad excepcional de respuesta en el terreno, de resolver un problema, en una situación súbita, con una idea improvisada.'
    ],
    g: [
      'Una falta de planificación y de sistematización: aunque saques una buena idea, en el proceso de la ejecución puedes dejar pasar un detalle, o tienes la tendencia de no terminar un proyecto que empezaste, así que puede bajar la confiabilidad.',
      'La ausencia de consistencia, por una fluctuación emocional: si la actitud cambia según el humor, los compañeros del equipo te pueden sentir imprevisible y se puede hacer difícil una relación de colaboración. En especial, cuando recibes estrés, aparece una actitud defensiva.'
    ],
    t: [T('Grok', 'main', 'El consejero sincero que confirma, sin freno, un hecho del mundo', 'Grok es la IA que neutraliza de forma directa tu característica de “humor cambiante”. Cuando el juicio se te sacude según el humor, si le preguntas a Grok, puedes obtener de inmediato un hecho objetivo, sin la emoción. Por ejemplo, en medio de la preparación de un empleo, si le lanzas a Grok una pregunta emotiva del tipo “la reseña de la entrevista de esta empresa se ve bien; ¿tengo que postular?”, te compara y analiza un dato concreto, como el salario real de la empresa, el equilibrio entre el trabajo y la vida, la velocidad de un ascenso de un recién llegado. En especial, cuando piensas “como hoy no estoy de humor, esta tarea no la hago”, el feedback directo de Grok te puede despertar el sentido de la realidad.', 'Ahora mismo estoy de mal humor y estoy pensando en no hacer esta tarea; ¿me puedes analizar de forma objetiva qué pasa con mi calificación si no la termino antes de la fecha límite? Mi nota actual es A-, esta tarea pondera un 30% y, si saco 0 puntos, ¿qué pasa?'),
        T('Zapier', 'specialist', 'El constructor de un sistema que, con la automatización, fuerza “lo que hay que hacer”', 'Tienes ideas de sobra, pero la tendencia de que la ejecución se te vaya diluyendo. Zapier resuelve ese problema de forma estructural. Por ejemplo, si registras en Google Calendar un evento de “fecha límite de una tarea”, puedes configurar que te llegue una alerta en automático, por un mensaje de Discord o de Slack. O puedes hacer que, si introduces una tarea en Notion, se envíe en automático un recordatorio de Gmail. Por tu característica de humor cambiante, no basta con el propósito de “esta vez sí la termino”, así que le das un carácter forzoso, con una automatización mecánica. También en un proyecto de equipo, puedes complementar tu falta de consistencia, armando, con Zapier, un sistema de compartir en automático una lista de chequeo.', 'Cuando se añade una tarea nueva a una base de datos de Notion, configura una automatización de Zapier para que me llegue una alerta al teléfono, cada día a las 8:00, y una alerta más, un día antes de la fecha límite. ¿Cuál es el método de configuración?'),
        T('Forest', 'specialist', 'El socio de la concentración que hace crecer tu dispersión como un bosque', 'Forest es una app que fuerza la concentración, con un elemento de un juego. Para alguien como tú, de humor cambiante y, a la vez, sociable, es perfecto. Cuando estudias, si enciendes la app Forest, crece un árbol virtual, y, en el instante en que sales de la pantalla, el árbol se muere. Si, junto con los amigos, hacen un “desafío de Forest”, se estimula el espíritu de competencia y se alarga el tiempo de concentración. Por ejemplo, si, en la biblioteca, enciendes Forest con el objetivo de estudiar 3 horas seguidas y lo empiezan a la vez 5 amigos, nace el sentido de la responsabilidad de “si salgo yo primero, les hago un perjuicio al equipo”, y puedes canalizar tu ímpetu en una dirección positiva. En la práctica, también está el gusto de compartir, en una captura, el árbol que creció, y de compartir con los compañeros del equipo la sensación de logro.', 'En la app Forest, ármame un objetivo de “sprint de terminar una tarea: 4 horas”, configúralo por etapas (1 hora → 10 minutos de descanso → 1 hora → 10 minutos de descanso) y crea una rutina de empezarlo, cada mañana a la misma hora, junto con 4 compañeros del equipo.')],
    syn: 'Tu perfil OCEAN (una extraversión alta del 82% + una responsabilidad baja del 35%) crea, en el campo de un universitario en busca de un empleo, la fortaleza única de “un catch rápido y un networking fuerte”. Si objetivas la emoción con Grok, automatizas un plan con Zapier y gamificas la concentración con Forest, a ti, un extrovertido de ideas abundantes, se te suma también la etiqueta de “un ejecutor confiable”. Como resultado, en una sala de entrevistas puedes obtener, a la vez, no solo la apelación de “una experiencia y una idea”, sino también la confianza de “alguien que cumple una promesa”: una competitividad distinta de la de otro buscador de empleo.',
    day: 'A las 7:00 de la mañana, antes de salir de la cama, enciendes Grok, preguntas “¿cuáles son las Top 3 que tengo que terminar hoy?” y empiezas el día con una prioridad, no con la emoción. A las 8:00, en la entrada de la biblioteca, confirmas si llegó la alerta de la lista de las tareas de hoy que configuraste con Zapier y, cuando llega el mensaje de un amigo de “¿hacemos Forest juntos?”, aceptas de inmediato. Desde las 9:00, durante una hora y media, enciendes Forest junto con 3 amigos y te concentras en terminar “la tarea de visualización de un dato”. En el almuerzo, de buen humor, le preguntas a Grok “esta postulación a una pasantía, ¿está bien hacerla ahora?”; recibes un análisis objetivo del timing y tomas una decisión. A las 14:00, después de una reunión de un proyecto de equipo, la tarea que te asignaron se registra en automático, con Zapier, a la vez en tu calendario y en el Notion del equipo, y reduces un error. A las 16:00, cuando, en medio de un desafío de Forest, se te dispersa la concentración, le preguntas a Grok “¿me puedes analizar de forma objetiva por qué me dispersé ahora?” y recobras el ánimo. A las 18:00, antes de irte, compartes con los compañeros del equipo la captura del bosque de Forest que terminaste hoy, y prometen el desafío de mañana.'
  });
  add('00101', 'Quien recorre una comunidad con energía, el buscador de empleo sensible a un resultado', 'ChatGPT', ['Wysa', 'Claude'], {
    i: 'Tú, un buscador de empleo extrovertido y sensible, reúnes información con vivacidad y te relacionas con la gente y, a la vez, reaccionas de un modo extremadamente sensible a un resultado. Participas con vivacidad en una comunidad o en un grupo de estudio de la búsqueda de un empleo, pero, cuando llega la noticia de un rechazo, recibes un golpe grande. El núcleo es orientar de forma estratégica esa energía vivaz.',
    s: [
      'Con una extraversión alta, en una comunidad de la búsqueda de un empleo, en un evento de una empresa, en un networking, reúnes información con vivacidad y creas una oportunidad.',
      'Con un instinto sensible, tienes la capacidad de captar con rapidez la reacción y el ambiente de un entrevistador, y de responder.',
      'Con la capacidad de expresarte de forma activa, dejas una presencia en una entrevista.'
    ],
    g: [
      'Reconoce la tendencia de reaccionar en exceso a un resultado de un rechazo, y deja armada una rutina de recuperación de la emoción.',
      'Hace falta un rato de sumarle profundidad a la preparación de una carta de presentación y de una entrevista. Complementa un networking vivaz con la profundidad de la preparación.',
      'Si estrecha la empresa y el puesto objetivo y los atacas con concentración, la energía dispersa saca un resultado más grande.'
    ],
    t: [T('ChatGPT', 'main', 'El socio que convierte, con rapidez, una información en una estrategia', 'Prueba conectar, con rapidez, con ChatGPT, como una estrategia de una carta de presentación, la información que obtuviste en un grupo de estudio o en un networking de la búsqueda de un empleo.', 'Soy del tipo OCEAN 00101. Hoy voy a una sesión informativa de LG CNS; prepárame de antemano 3 preguntas con las que pueda dejar una impresión.'),
        T('Wysa', 'specialist', 'La red de seguridad emocional que te recupera con rapidez, después de un rechazo', 'Cuando llega una noticia de un rechazo o un estrés, si le sueltas la emoción a Wysa, te estabilizas con rapidez y puedes encontrar la energía de volver a salir.', 'Hoy volví a quedar fuera en el documento. Como sigue pasando así, se me está yendo la confianza. ¿Cómo puedo volver a tomar el corazón?'),
        T('Claude', 'specialist', 'El socio de revisión que complementa la profundidad y la lógica de una carta de presentación', 'Si le envías a Claude una carta de presentación que escribiste con rapidez y dejas revisar el flujo lógico y la capacidad de convicción, el grado de terminación sube mucho.', 'Este es el borrador de la carta de presentación de Samsung que escribí con rapidez. Encuentra la parte en la que el flujo lógico es débil y la parte que se puede escribir de forma más concreta, y mejórala.')],
    syn: 'Tú, con una extraversión (E) alta y sensible, tienes que usar la IA como un acelerador de una ejecución rápida y como una red de seguridad emocional. Si estrategizas con rapidez con ChatGPT y proteges la emoción con Wysa, tu energía vivaz se convierte en una búsqueda de un empleo sostenible.',
    day: 'A las 8:00, con Wysa, el chequeo de la emoción de hoy. A las 9:00, con ChatGPT, la estrategización de la búsqueda de un empleo de hoy. A las 11:00, la redacción y la entrega de una carta de presentación. A las 14:00, la participación en un evento de una empresa o en un grupo de estudio. A las 17:00, con Claude, la revisión final de una carta de presentación. A las 21:00, con Wysa, el cierre del día.'
  });
  add('00110', 'El vividor del campus al que más le gusta la gente', 'Google Gemini', ['Calendly', 'Otter.ai'], {
    i: 'En un viaje de un club, cuando tres juniors te preguntan “senior, ¿nos invitas a comer?”, aunque estabas escribiendo una carta de presentación, abres la cartera sin dudar. Este es tu retrato. Con una extraversión alta (85%) y una amabilidad (92%), en cualquier rincón del campus te conectas de forma natural con la gente y obtienes su confianza. Pero hay el dilema que crean una responsabilidad baja (32%) y una apertura (25%). El plan se te atrasa con frecuencia, y a menudo la charla pasa por delante de una carta de presentación. Los colegas te recuerdan como “alguien cálido, pero un poco disperso”. Tu optimismo de aguantar, incluso al borde de un acantilado de la búsqueda de un empleo, con humor, es un encanto, pero ahora es el turno de convertir esa afinidad en una red estratégica y en un autocuidado sistemático. Tu carácter de llevarte bien con la gente ya es un activo; lo que ahora hace falta es estructurarlo.',
    s: [
      'Una capacidad excepcional de construir una relación interpersonal: con una extraversión y una amabilidad altas, formas de forma natural una relación de confianza con un profesor, un senior, un junior y un colega, y esto es un activo intangible que se conecta de forma directa con una oportunidad de mentoria, de recolección de información y de colaboración.',
      'Una resiliencia y una estabilidad emocional en una situación de estrés: recibes con optimismo la incertidumbre y un rechazo del proceso de la búsqueda de un empleo, consuelas a quien te rodea y ejerces un liderazgo emocional que crea la sensación de estabilidad psicológica del equipo.',
      'Una capacidad ágil de respuesta a una situación: aunque no haya un plan, te adaptas con rapidez en el terreno, percibes la necesidad de la gente y te puedes mover de forma improvisada, así que no dejas pasar una oportunidad inesperada o un instante de networking.'
    ],
    g: [
      'Una debilidad del autocuidado y de la gestión del tiempo: tienes la tendencia de posponer una tarea importante o la preparación de un empleo, así que puedes caer en el círculo vicioso de repetir una situación apurada, justo antes de una fecha límite, y de no ejercer bien tu potencial.',
      'Una falta de un aprendizaje profundo y del desarrollo de una especialidad: como la curiosidad por un campo nuevo (apertura del 25%) es baja, te falta la capacidad de ahondar a fondo en un solo tema, y esto se convierte en un punto débil cuando apelas la especialidad en una entrevista.'
    ],
    t: [T('Google Gemini', 'main', 'El PDA de lo cotidiano que apunta con precisión tu dispersión', 'Para alguien de una tendencia dispersa como tú, Gemini es una presencia como un amigo que, a tu lado, te pregunta de forma natural “oye, ¿ahora qué tienes que hacer?”. Si cada mañana preguntas “¿me fijas solo 3 cosas que hay que hacer hoy, sí o sí?”, Gemini analiza tu agenda, una fecha límite y la prioridad, y te presenta 3 claras. Por ejemplo, de forma concreta: “terminar la carta de presentación de 3 empresas, asistir a la reunión del equipo de desarrollo, confirmar 1 hora antes una cita de networking de una comida”. En el almuerzo, una vez más, pregunta “¿hasta ahora qué hiciste? ¿Qué queda?” y te sostiene para que no te salgas de la órbita. Si esto se repite, nace el hábito de, incluso dentro de la dispersión, concentrarte solo en el núcleo.', 'Mi agenda: el lunes, una entrevista; el jueves, la fecha límite de una carta de presentación; el viernes, una reunión de un club. Hoy es miércoles; ¿me puedes fijar, por prioridad, las 3 cosas que hay que hacer sí o sí? Ahora mismo el ánimo está un poco caído.'),
        T('Calendly', 'specialist', 'El gestor de la agenda que sistematiza una cita dispersa', 'Se te da bien olvidar una cita, y te resulta engorroso cuadrar un horario con la gente. Si configuras Calendly, un senior, un profesor, un entrevistador pueden reservar con libertad un horario, a través de tu enlace. Por ejemplo, si les pasas “si quieres un coffee chat, reserva el horario que te quede bien, en este enlace”, la otra parte fija el horario y se sincroniza en automático con tu calendario. Como también llega una alerta automática 30 minutos antes de la cita, incluso alguien como tú, de un sentido del tiempo holgado, lo sigue con facilidad. Además, obtienes hasta el efecto de que el networking, en el que se revela tu afinidad, se sistematiza en automático.', 'Después de configurar el enlace de Calendly: “¿la semana que viene, cuándo podemos hacer un coffee chat de 30 minutos? ¿Me eliges el horario, aquí?”'),
        T('Otter.ai', 'specialist', 'La nota de voz que hace que no tengas que dejar registrada una conversación a mano', 'Cuando conversas con la gente, te concentras bien, pero se te da peor recordar y ordenar la información. Si, después de una entrevista, preguntas “¿qué consejo me dieron?”, se te nubla con un “eh… eso…”. Otter.ai convierte en automático, en un texto, la grabación de voz de tu teléfono. Si grabas una cita de una comida de networking o una conversación de mentoria (después del consentimiento de la otra parte), después puedes buscarlo y ordenarlo en un texto. Por ejemplo, si preguntas “¿me muestras solo la parte en la que, en el feedback de la entrevista de la semana pasada, se mencionó ‘liderazgo’?”, la IA lo encuentra. Es poder usar tu memoria como un disco duro externo.', 'Justo después de una entrevista: “Otter, convierte en un texto la grabación de ahora mismo y resúmeme solo la parte de una palabra clave como ‘cultura de la empresa’ o ‘equipo’.”')],
    syn: 'Tu superfortaleza es “la construcción de la confianza con la gente” y, si a esto se le suman la sistematización de Gemini, la gestión de Calendly y el registro de Otter.ai, te conviertes en “alguien confiable y sistemático”. En especial, en el proceso de la búsqueda de un empleo, las personas extrovertidas como tú hacen mucho networking, pero no aprovechan bien ese resultado. Esta combinación de IA desempeña el papel de tubería que convierte tu afinidad en una oportunidad de un empleo. Por ejemplo, si usas estas herramientas durante un mes, en automático te conviertes en “alguien que se reúne de forma periódica con 20 mentores”, “alguien que reúne de forma sistemática el feedback de una entrevista”, y eso significa que obtienes una red y un grado de preparación, cualitativamente superiores a los de un buscador de empleo de la misma edad.',
    day: 'Te levantas a las 8:30, en un café (porque estuviste con los amigos hasta las 22:00). Mientras tomas un americano en el café, le preguntas a Gemini “las 3 que hay que hacer hoy, sí o sí, y, ¿hasta qué hora cada una?”. Gemini responde “① hasta las 10:00, 2 preguntas de la carta de presentación de la empresa A, ② antes de las 12:00, terminar la corrección del currículum, ③ a las 14:00, un coffee chat con un senior”. Dejas esto como fondo del teléfono y enciendes Otter.ai. De las 10:00 a las 11:50, escribes la carta de presentación con concentración (porque ya te divertiste y ya no te queda tiempo). A las 12:00, corriges con rapidez el currículum y, desde las 12:30, mientras almuerzas, le confirmas a Gemini “¿todavía estoy bien?”. A las 13:30, vas al coffee chat con un senior que reservaste con el enlace de Calendly. Como la cita ya apareció en automático en el calendario, estás tranquilo. En el coffee chat, cuando el senior dice “te voy a decir cinco consejos de una entrevista”, Otter.ai lo registra en automático. Tú solo tienes que escuchar, a gusto. A las 15:30, al salir del café, le ordenas a Otter “conviértelo en un texto y resúmeme la parte de la palabra clave ‘tecnología’”. A las 16:00, vuelves a casa y vuelves a pulir la carta de presentación. A las 18:00, le preguntas a Gemini otra partida de preparación de una entrevista, y, desde las 19:00, mientras hablas con los amigos, recuerdas en el corazón los buenos consejos, de entre lo que contaron (Otter no lo enciendes cuando se mezcla una información personal). A las 22:00, compartes el enlace de Calendly en una historia de Instagram y subes un texto: “¿quién tiene un horario, la semana que viene, para un coffee chat?”. Tu calidez sigue igual, pero, ahora, va cargada sobre un sistema.'
  });
  add('00111', 'El rey imperturbable del optimismo, el perezoso del campus', 'Google Gemini', ['Perplexity AI', 'ChatGPT'], {
    i: 'Tú, el único que, en la sala de lectura de la biblioteca, lleva una sonrisa holgada. Eres alguien con la osadía de, incluso la víspera de ir a una sala de entrevistas, estar viendo la película «No soy gran cosa», con un “ah, ya saldrá”. Tu arma más grande es “no inquietarte”. Porque naciste con el estado mental que más desean los buscadores de empleo de esta era. Los compañeros te llaman “el sanador del temple” y, si te sientas a su lado, nace una sensación de estabilidad, de no se sabe bien de dónde. Con una amabilidad alta (A: 95%) y una extraversión (E: 88%), en cualquier parte armas una red con facilidad, y la gente te confía de forma natural. Solo que, como la tendencia al neuroticismo es alta (N: 92%), no es que no haya inquietud: solo no la muestras hacia afuera; en el interior hay sensibilidad. Y, como la responsabilidad es baja (C: 20%) y la extraversión es alta, se repite la situación de, a las 22:00 de la noche anterior a una fecha límite, murmurar “ah, el plazo de entrega del documento era hasta hoy”. Más que que alguien te ordene, simplemente, la agenda, te hace falta con urgencia un asistente de IA que te dé un toquecito en la cadera.',
    s: [
      'La capacidad de empatía es excepcional (A: 95%), así que, en un proyecto de equipo o en una entrevista, lees el corazón de la otra parte y construyes de inmediato una relación de confianza. La capacidad de crear, de forma natural, “la conexión con la gente”, lo más importante en un empleo, es, en sí, tu credencial.',
      'Con una extraversión alta (E: 88%), es posible una acción inicial con confianza, y creas una primera impresión distinta, en un networking, en una presentación, en una entrevista. Incluso entre los buscadores de empleo, alguien tan a gusto como tú es raro, así que los entrevistadores disfrutan la conversación misma contigo.',
      'Con una tendencia alta al neuroticismo (N: 92%), detectas bien un cambio minucioso de la emoción y una señal sutil de una situación, y lo puedes aprovechar para mejorar una relación interpersonal o para una autorreflexión. Aunque tú mismo no lo percibas, observas el entorno con más sensibilidad de lo que piensas.'
    ],
    g: [
      'Como la responsabilidad es baja (C: 20%) y la extraversión es alta, te es fácil irte detrás del ambiente, sin armar un plan. Tienes la tendencia de posponer una y otra vez “un trabajo que hay que hacer, solo, con esmero”, como la redacción de un documento, una carta de presentación, un portafolio, así que son indispensables una alerta concreta de una fecha límite y un chequeo del estado de avance.',
      'Por un neuroticismo alto (N: 92%), la inquietud interior se puede amplificar más que la real. Por fuera dices “está bien”, pero te es fácil nacer el hábito de repetir el mismo pensamiento toda la noche, o de imaginar lo peor. Hacen falta un dato objetivo y un feedback positivo.'
    ],
    t: [T('Google Gemini', 'main', 'Una IA a tu medida, como un amigo: pregúntale, simplemente', 'Gemini funciona como “tu amigo a gusto”. Si, sin una carga del corazón, lanzas una pregunta del tipo “¿esta empresa estará bien?”, “¿mi carta de presentación está muy floja?”, “parece que me rechazaron en todos los empleos; ¿qué tengo que hacer?”, te devuelve un consejo cálido y, a la vez, práctico. Por tu tendencia alta al neuroticismo, te inquietas, pero las cosas que se te hacen difíciles de decirle a otra persona, a Gemini se las puedes sacar con facilidad. En especial, cuando, de camino por la mañana, te viene la inquietud de “hoy tengo una entrevista; ¿lo voy a hacer bien?”, si preguntas a gusto “Gemini, ¿viste mi carta de presentación? ¿No está bien?”, Gemini te vuelve a recordar una fortaleza concreta. Ejemplo: “¿me puedes ordenar 3 casos, de entre los proyectos que hice, en los que el trabajo en equipo salió bien, y armarlos como una historia de una entrevista?”', 'Mi carrera es psicología, tengo 2 experiencias de una pasantía y 3 clubes; ¿me puedes analizar a qué tipo de empresa suelen entrar, estos días, en el mercado de un empleo, las personas de un perfil como el mío, y cuál es la razón por la que, en ese proceso, reciben una buena evaluación?'),
        T('Perplexity AI', 'specialist', 'La barra mágica de búsqueda que te quita la pereza de investigar', 'Como tu responsabilidad es baja, tienes la tendencia de posponer incluso una investigación básica, del tipo “esta empresa, ¿qué hace?”. Perplexity resuelve este problema a la perfección. La víspera de una entrevista, cuando no sabes nada de la empresa, si preguntas “¿me resumes las noticias recientes de la empresa OOO, el negocio principal y qué tipo de talento desea, en el puesto que está contratando?”, en 5 minutos te ordena toda la información. Como tú solo tienes que leer esa información, la preparación se completa, sin la carga de la responsabilidad. Ejemplo: “¿me comparas 3 anuncios de un puesto de análisis de datos y me armas, en una tabla, la capacidad que exigen en común y el punto de diferenciación de cada empresa?”', 'Compara los anuncios de contratación de un “desarrollador recién llegado” de estas tres empresas —SKT, LG, Samsung—, ordéname qué stack técnico y qué experiencia considera importante cada una, y recomiéndame la prioridad de lo que tengo que aprender ahora.'),
        T('ChatGPT', 'specialist', 'El último amigo de la redacción de una carta de presentación, quien te ofrece la emoción', 'Tú no puedes “armar un plan”, pero, en una situación de preguntarte “¿cómo expreso esto?”, cuando ya se reunió el material, ChatGPT es el mejor socio. En un trabajo de “expresar bien una experiencia que tú ya viviste” —el ejercicio de una pregunta de una entrevista, pulir una frase de una carta de presentación, armar la explicación de un portafolio—, brilla la creatividad de ChatGPT. Por ejemplo, cuando explicas el papel que tuviste en un proyecto de equipo, si preguntas “ChatGPT, como tengo buen carácter, cuidé bien al equipo. ¿Cómo lo expreso, en el lenguaje de un liderazgo que desea una empresa?”, una simple “capacidad de comunicación” renace como “un liderazgo de colaboración, basado en la confianza del equipo”. Ejemplo: “en una pasantía que hice, en cada reunión ordenaba la opinión de todos y la cerraba. ¿Cómo lo tengo que escribir, en una carta de presentación, para que tenga impacto?”', 'Mi MBTI es ENFP y, en un proyecto de equipo, siempre alegré el ambiente e hice que todos participaran. Pero me preocupa que esto se malinterprete como “un carácter sin un sentido de la responsabilidad”. ¿Cómo explico esta fortaleza, desde la posición de una empresa, para que suene positivo?')],
    syn: 'Tu perfil OCEAN (una O baja, una C baja, una E alta, una A alta, un N alto) es, en el mercado de la búsqueda de un empleo, “un fuerte inesperado”. Con una extraversión y una amabilidad altas, el networking de contactos se hace en automático; por la tendencia al neuroticismo, no dejas pasar un detalle; y la IA cubre el hueco de una responsabilidad baja. En especial, la combinación triangular de Gemini (un respaldo emocional) + Perplexity (la velocidad de la información) + ChatGPT (la capacidad de expresión) automatiza lo que tú tienes que hacer y, a la vez, te deja solo tu papel emotivo y creativo. Como resultado, incluso con “una concentración de las últimas 3 semanas”, terminas un documento suficiente de un empleo y, en una entrevista, sacas la admisión, con tu energía de una alta autenticidad. Si, a un buscador de empleo de un perfil similar, le lleva de promedio 6 o 7 meses hasta la admisión, tú, después de armar el sistema de IA, lo puedes recortar a 3 o 4 meses.',
    day: 'A las 8:00 de la mañana, al levantarte de la cama, le preguntas a Gemini “vamos a fijar las 3 tareas que hay que hacer hoy, sí o sí, pero solo las que se puedan terminar en menos de 30 minutos cada una”. Es el rito de presentarle a tu inquietud un objetivo concreto. A las 9:00, al llegar a la biblioteca, antes de empezar el día, buscas con Perplexity “un resumen de 2 minutos de la información de la empresa en la que hoy tengo una entrevista”. Mientras te sientes preparado, el neuroticismo se convierte en confianza. A las 10:00, tienes que escribir una carta de presentación y, cada vez que no te convence si una frase está bien, le preguntas a ChatGPT “esta frase está bien, pero, ¿para expresarla con más fuerza?”. Al conversar con la IA, una vez cada 30 minutos, se te baja la barrera de entrada de la redacción de un documento. A las 12:30, mientras almuerzas, conversas a gusto con quien está a tu lado. Gracias a una extraversión y una amabilidad altas, este rato se convierte, de forma natural, en un networking. A las 13:30, al volver a la tarde, le pides a ChatGPT “las preguntas previstas de la entrevista de mañana” y, mientras lees las propuestas de respuesta que quedaron listas, te calmas el corazón. Tu tendencia al neuroticismo se convierte en “una preparación previa rigurosa”. A las 15:00, gracias a que Gemini te avisó por la mañana el plazo de un documento, hacia esta hora lo terminas y haces la revisión final. Sin el arrepentimiento, a las 22:00 de la noche anterior a la fecha límite, de “ah, era hasta hoy”. A las 17:00, antes de irte, alineas una vez más, con Gemini, lo que hay que hacer mañana. Cubre, con concreción, la inquietud que nace de lo poco claro. Por la noche, te animas a ti mismo y, junto con el respaldo de las IAs, te preparas para mañana. En esta rutina, tu “ya se resolverá de algún modo” deja de ser una huida y se convierte en un optimismo con fundamento.'
  });
  add('01000', 'El estudiante modelo recluso e inflexible', 'Perplexity AI', ['Elicit', 'DeepL'], {
    i: 'En la sala de lectura de la biblioteca, es fácil encontrarte. Porque las libretas, sobre el escritorio, están alineadas sin un adorno de más y, hasta un solo bolígrafo, está colocado en el ángulo exacto. Los colegas te llaman “el estudiante sobresaliente callado”, pero, en realidad, eres más complejo. Por la tendencia de no transigir nunca, en un método de estudio o en un modo de trabajo, los choques de opinión son frecuentes, pero, a cambio, en la calidad de una tarea o de un proyecto, nadie te puede alcanzar. Con un instinto sensible, atrapas también el error más pequeño, dentro de tu propia investigación o de una tarea, y el criterio que fijaste una vez no lo bajas nunca. También en la preparación de un empleo, cumples con rigor tu propia rutina y, más que el consejo de otra persona, confías en un dato objetivo y en un paper. Por eso, tu carta de presentación o tu portafolio son refinados a más no poder, pero, a veces, también recibes la evaluación de “tan perfecto que no tiene personalidad”. Las herramientas de IA las aprovechas del mismo modo. Quieres solo una información precisa, sin una charla, y prefieres una herramienta que encuentre la respuesta correcta, de inmediato.',
    s: [
      'Una precisión y una minuciosidad extremas: con la capacidad de verificación de no dejar pasar ni un error trivial, en una tarea o en un informe, el grado de terminación del material que entregas es de primer nivel. Esta fortaleza crea una ventaja decisiva en la gestión académica, en la redacción de un paper y en un puesto de un criterio de calidad alto.',
      'Una capacidad de aprendizaje autodirigido: la templanza de no dejarte sacudir por la opinión de otro y de ejecutar, de forma consistente, tu propia metodología de aprendizaje es excepcional, así que, en un proyecto de largo plazo o en una investigación, la concentración no se te dispersa. En especial, brilla cuando, después de entrar a un posgrado, hace falta una investigación independiente.',
      'Una toma de decisiones basada en datos: con la tendencia de confiar, más que en un consejo abstracto, en una estadística concreta, en un paper, en un material de un caso, al preparar un empleo o al decidir una ruta de carrera, puedes armar una estrategia basada en una información objetiva y demostrada. Esto, como resultado, se convierte en una preparación más eficiente.'
    ],
    g: [
      'Mejorar la capacidad de colaboración: por una actitud de absolutizar tu propio modo, en un proyecto de equipo te cuesta aceptar otra opinión. Si cultivas la flexibilidad de que, hacia el mismo objetivo, pueden existir rutas diversas, la evaluación del liderazgo y del trabajo en equipo va a mejorar mucho.',
      'La gestión de la emoción y el afrontamiento del estrés: por una tendencia sensible y un criterio alto, incluso ante un factor pequeño de interrupción sientes con facilidad una molestia, y, delante de un resultado que no es perfecto, experimentas un estrés excesivo. Elevar la resiliencia emocional, a través de la meditación, de un descanso sistemático o de una consulta psicológica, es la llave del éxito de largo plazo.'
    ],
    t: [T('Perplexity AI', 'main', 'El asistente preciso, centrado en un hecho, sin un adorno de más', 'Es la herramienta que te hace ejercer al máximo tu perfeccionismo y tu precisión. Perplexity ofrece la información más reciente, con base en una búsqueda de la web, y, al indicar la fuente, la transparencia es excepcional, así que tú puedes confiar. Por ejemplo, es muy eficiente cuando, en medio de la redacción de un paper, tienes que conocer la tendencia más reciente de investigación de un campo particular, o cuando, al preparar un empleo, confirmas una noticia reciente o una tendencia tecnológica de una empresa particular. A través de esta herramienta, puedes filtrar solo una información confiable y volver a verificarla, de forma adecuada a tu propio criterio. Ejemplo: “ordéname, junto con la fuente, la tendencia más reciente del mercado de empleo de la industria de la IA del país, de 2024, y la habilidad que exigen las empresas principales de contratación”.', 'Ordéname, junto con la fuente, el análisis comparativo del presupuesto de investigación y desarrollo de IA, de 2024, de Microsoft, Google y Meta, y el campo tecnológico principal de cada una. En formato de una tabla.'),
        T('Elicit', 'specialist', 'La herramienta de investigación que automatiza el análisis masivo de un paper académico', 'Cuando escribes una tarea o un informe basado en un paper, es la herramienta más potente. Está hecha a la medida, a la perfección, para satisfacer tu criterio académico alto y tu deseo de precisión. Elicit analiza, a la vez, decenas de papers, extrae el contenido central y te hace identificar con rapidez el punto de consenso y el punto de debate de los académicos, sobre un tema particular. Por ejemplo, si el tema del informe de fin de semestre es “el problema ético de la inteligencia artificial”, puedes analizar de una vez 50 papers relacionados y extraer los fundamentos más confiables. Esto satisface con precisión tu “deseo de verificación”. Ejemplo: “compárame y analízame la tendencia de investigación, de los últimos 5 años, sobre la explicabilidad (Explainability) del deep learning, y las metodologías principales”.', 'Analízame los papers que tratan la exactitud, la ventaja y el punto de limitación de la aplicación del machine learning, en la bioinformática (Bioinformatics), y ordéname, en una tabla, la conclusión central de cada paper.'),
        T('DeepL', 'specialist', 'La herramienta de traducción académica precisa, que conserva el matiz', 'Cuando tienes que leer un paper en inglés o un material del extranjero, es la herramienta que más protege tu perfeccionismo. A diferencia de un traductor general, DeepL entiende con precisión el contexto y un término académico, y ofrece una traducción natural y refinada. En especial, para alguien como tú, de un criterio lingüístico alto, la imprecisión de Google Translate es un gran estrés, y DeepL lo alivia mucho. Por ejemplo, es muy útil cuando lees un paper de un congreso académico internacional, o cuando tienes que entender con precisión el anuncio de contratación de una empresa del extranjero. Ejemplo: “tradúceme al coreano el siguiente resumen en inglés, manteniendo con precisión el término académico: [pegar el resumen del paper]”.', 'Tradúceme al coreano la sección de Methods de este paper académico. En un término técnico, sigue la transcripción en hangul de uso internacional: [texto del paper].')],
    syn: 'Tu perfeccionismo y tu modo de pensar, centrado en un dato, al encontrarse con una herramienta de IA, alcanzan “la maximización de la precisión”. El proceso de trabajo tuyo —reunir una información verificada con Perplexity, sumarle una profundidad académica con Elicit y asegurar, además, la precisión lingüística con DeepL— es, en lo cualitativo, de otra dimensión que el de un colega. En especial, en la redacción de un paper, en la entrega de un informe, en la preparación de un portafolio de un empleo, puedes mostrar “una excelencia verificable”. Esto, más que, simplemente, “una buena nota”, hace que te reconozcan como “un investigador confiable” o como “alguien de una capacidad de trabajo, de un criterio alto”. Como resultado, la probabilidad de que tu opción de carrera se convierta, en un campo en el que la precisión es lo primero —un puesto de investigación, un análisis de datos, una gestión de la calidad—, en la de un postulante competitivo, sube mucho.',
    day: 'A las 8:00 de la mañana, te sientas en el escritorio y, lo primero, enciendes Perplexity. Porque ya se te incorporó el hábito de confirmar, con rapidez, si hay una estadística o un caso más reciente, de la tarea que hay que entregar hoy. En 15 minutos, ordenas en un bloc las 3 informaciones que hacen falta, junto con la fuente. Cuando, a las 9:00, empiezas el trabajo formal de la tarea, revisas el feedback de la tarea que entregaste la semana pasada y vuelves a examinar si tu modo de trabajo estuvo bien. Hacia las 10:00, cuando llegas a la parte en la que hay que leer un paper, abres Elicit y lanzas, en un modo de análisis por lote, los papers relacionados. En un lado de la pantalla está abierta tu nota y, mientras sale el resultado de Elicit, tú ya estás escribiendo la siguiente sección. En el almuerzo, más que en el comedor, comes en el café de la biblioteca, traduces con DeepL 3 resúmenes de un paper del extranjero y chequeas la exactitud. Desde las 14:00 es tu horario de oro. En un entorno callado, sin una interrupción, haces el trabajo de integrar, en tu tarea, las informaciones que ofreció Perplexity. Cada cita y cada estadística se registran con precisión, junto con la fuente, y cada frase se pule hasta satisfacer tu criterio alto. Hacia las 17:00, vuelves a leer, una vez más, la tarea terminada y encuentras un error. En esta última etapa de verificación, captas los errores pequeños que nadie más encontraría. Después de “salir” (o después de las 19:00), si tienes que preparar una reunión de equipo o una presentación de mañana, reconfirmas, con Perplexity, la tendencia más reciente relacionada y haces el chequeo final de si, en tu material de presentación, falta alguna información. A las 22:00, ordenas de forma sistemática la agenda del día siguiente y apagas las herramientas de IA. Cierras el día, con la convicción de que tu rutina, consistente y precisa, va a continuar también mañana.'
  });
  add('01001', 'El francotirador del campus que, en silencio, se queda con lo sustancial', 'Perplexity AI', ['Elicit', 'ChatGPT (GPT-4)'], {
    i: 'El día de la presentación de un proyecto de equipo, tú solo estabas sentado en silencio, y, en el material que entregaste, ¿se dejaron 50 comentarios que señalaban un error? Eso eres tú. El tipo que se calla, pero habla con un resultado. Tu fortaleza es que la precisión y la consistencia están casi en un nivel sobrehumano. Cuando lees un paper, la parte que otros estudiantes recorren por encima, tú la verificas hasta el original, la fuente de una cita y una estadística. En una entrevista de la búsqueda de un empleo, ante la pregunta “¿cuál es tu punto débil?”, tú respondes, como un hecho, “tengo que disfrutar más la comunicación”, pero, en realidad, tu verdadero punto débil no es la inquietud: es que no puedes gastar el tiempo en una conversación innecesaria. Los colegas te ven como “una persona fría”, pero, en realidad, solo eres una persona muy razonable. Como el nivel del resultado que tú creas es alto, ahora solo te falta aprender a “mostrarlo”, un poco más atractivo.',
    s: [
      'Una capacidad precisa de recolección y de verificación de un material. En la revisión de un paper, en un análisis de un dato, en la revisión de una estadística, casi no dejas pasar un error. Tu minuciosidad es el activo central que sube la confiabilidad del equipo.',
      'Un mindset que se mantiene de forma consistente, sin un vaivén de la emoción. Como el temple es fuerte, también ante un rechazo y una incertidumbre del proceso de la preparación de un empleo, respondes de forma mecánica. Esta es el arma más fuerte, en una batalla larga.',
      'Una capacidad de gestión del tiempo, por la búsqueda de la eficiencia. Como no tienes pensado desperdiciar el tiempo, tanto el rato de estudio como el de ordenar un material tienen un grado de concentración tan alto que se puede contar con los dedos. En el mismo período, puedes ir a una profundidad 3 veces mayor que la de otro estudiante.'
    ],
    g: [
      'Reconocer la necesidad de un networking y de formar una relación interpersonal. El 60% de la información y de una oportunidad viene de un contacto. También tu material perfecto, sin una recomendación y una conexión, no brilla. Aunque sea con 5 personas del sector, crea un contacto periódico.',
      'Reforzar la capacidad de una presentación y de un storytelling. También es importante la capacidad de transmitir lo excelente que es tu resultado de un análisis. Aunque no sea perfecto, la habilidad de atrapar a la audiencia, con empatía y con curiosidad, es, en el terreno profesional, la encrucijada de un ascenso.'
    ],
    t: [T('Perplexity AI', 'main', 'El canon de una búsqueda de información limpia, centrada en un hecho, sin un anuncio', 'Cada día, a las 6:00 de la madrugada, te levantas y buscas en Perplexity una palabra clave de un paper. A diferencia de una búsqueda de Google, no hay un texto inútil de un blog ni un anuncio, y un material académico y una noticia reciente aparecen con prioridad. Por ejemplo, si buscas “una investigación más reciente, de 2024, de una métrica de evaluación de un modelo de machine learning”, sale un resumen del contenido central, junto con el enlace de un paper relacionado. Como tú, después de leer este resumen, solo tienes que leer con precisión 3 papers, el tiempo se recorta a la mitad. Es especialmente potente en una investigación de un material de admisión a un posgrado, o en un análisis de la industria, antes de un empleo.', 'Ordéname, con el criterio de un material académico de 2024, la métrica más reciente de evaluación y el punto de limitación de un modelo de reconocimiento de una imagen, basado en machine learning. En especial, ¿incluyes un caso de aplicación del campo de una imagen médica?'),
        T('Elicit', 'specialist', 'El análisis automático de un paper, el campeón de un trabajo repetitivo de investigación', '¿La preparación de la admisión a un posgrado, en la que tienes que leer 100 papers? Elicit te recorta un 80% tu investigación bibliográfica. Si introduces una palabra clave, reúne en automático los papers relacionados y te ordena, en una tabla, “la metodología-el resultado-la limitación” de cada paper. Solo con mirar esta tabla, tú puedes juzgar qué paper leer y cuál saltarte. Ejemplo: después de buscar “procesamiento del lenguaje natural en coreano, basado en GPT”, si aparecen 50 papers, con la tabla comparativa que ofrece Elicit puedes seleccionar solo 5 papers centrales.', 'Encúentrame un paper del país, relacionado con una vía de mejora de la alfabetización de IA de un universitario coreano. Filtra solo una investigación empírica de los últimos 3 años y, en la tabla, incluye solo el tamaño de la muestra y la conclusión principal.'),
        T('ChatGPT (GPT-4)', 'specialist', 'El socio crítico de una verificación lógica profunda y de la redacción de un paper', 'Subes a ChatGPT el paper que terminaste y le preguntas “¿me encuentras el hueco lógico de este paper?”. ChatGPT señala una relación causal que dejaste pasar, un fundamento insuficiente, un error de la interpretación de una estadística. La parte que, al leerlo solo, no viste, se revela con el análisis objetivo de la IA. Por ejemplo, si, ante tu afirmación de “si el tamaño de la muestra es pequeño, la confiabilidad es baja”, ChatGPT objeta “pero la investigación A que citaste obtuvo un resultado significativo, también con una muestra todavía más pequeña”, puedes corregir de inmediato esta contradicción.', '¿Me lees la parte de la metodología de este paper que escribí? Chequéame si el criterio de selección de la muestra es claro, si las variables de control son suficientes, si el análisis estadístico es adecuado, y señala de forma concreta el punto que hay que mejorar.')],
    syn: 'Eres, de entre los universitarios (y de posgrado), la persona más sensible a “la confiabilidad de una información”. Si combinas las tres IAs —Perplexity (centrada en un hecho), Elicit (el orden automático de un paper), ChatGPT (una verificación lógica)—, completas “un sistema perfecto de verificación de un material” que otros estudiantes piensan que es imposible. En especial, en la preparación de un posgrado, en la que hay mucha redacción de un paper, o en un puesto centrado en un informe cuantitativo (un análisis de datos, una gestión de la calidad, un grupo de research), esta combinación te convierte en “alguien que no comete un error”. Como un resultado real, se convierte en 3 papers de una calificación A+, 2 presentaciones en un congreso y la admisión final de una entrevista de un empleo.',
    day: 'Tu día es una sucesión de la precisión. A las 6:00 de la mañana, antes de salir de la cama, enciendes Perplexity en el teléfono. Confirmas si, sobre el tema de “el impacto social de la tecnología blockchain” que empezaste ayer, se subieron 3 papers nuevos. En 5 minutos lees el contenido central y listas los 2 papers que vas a leer hoy. A las 8:00, al llegar a la biblioteca, enciendes de inmediato Elicit. Abres la tabla comparativa de “50 papers de blockchain” que guardaste la semana pasada y, hoy, seleccionas 5 papers que comparan y analizan “un algoritmo de consenso” y “la eficiencia energética”. Al mirar la columna de “metodología” de la tabla, de un vistazo identificas que 3 son con base en una simulación y 2 son una investigación de terreno. A las 10:00, terminaste de leer el primer paper. De inmediato introduces en ChatGPT la hipótesis, el resultado y la conclusión de ese paper, y preguntas “¿me evalúas si este paper es realmente confiable?”. Cuando ChatGPT señala “el tamaño de la muestra es suficiente, pero faltan 3 variables de control”, lo marcas con un bolígrafo rojo, en esa parte. El almuerzo no te lo comes sentado (lo consideras un desperdicio de tiempo): te tragas con rapidez un almuerzo empaquetado. De la 13:00 a las 17:00 es el horario de redacción de “el borrador de tu paper”. Con base en el dato más reciente que reuniste en Perplexity, escribes 3 párrafos. A las 17:00, no estás cansado. Porque tu cerebro está concentrado solo en “la búsqueda de la precisión”. A las 18:00, subes a ChatGPT el borrador del paper que escribiste. “Evalúame la estructura lógica de este paper y, si hay un salto, señálamelo”. Cuando recibes el feedback de ChatGPT, lo corriges de inmediato. A las 20:00, sales de la biblioteca. Incluso al volver a casa, sigues trabajando. Confirmas 3 alertas de una actualización automática de Elicit y, de los papers nuevos que se subieron, solo escaneas el título. Antes de dormirte, registras en tu Notion “5 papers leídos hoy, 8 páginas terminadas, 2 huecos encontrados”. Tú crees que la perfección empieza con el seguimiento.'
  });
  add('01010', 'El estudiante modelo perfeccionista, que lleva una muñeca de las preocupaciones del empleo', 'Claude', ['Grammarly', 'Forest'], {
    i: 'Tú, que, en el seminario de la carrera de la semana pasada, anotabas sin dejar pasar ni una sola broma que lanzó el profesor: precisamente esa diligencia es tu arma. Tú, que ejerces el mejor rendimiento, dentro de una regla y de un principio, eres, en el campus, el sinónimo de “alguien en quien se puede confiar”. La figura de, incluso con un 4,0 de promedio, reprocharte con un “qué lástima, no llegué a completar 0,5 puntos”, y la de, en un proyecto de equipo, no bastarte con terminar a la perfección tu propia parte, sino cuidar también el avance de los compañeros: precisamente eso es. Pero, delante de la incertidumbre que es un empleo, sueles pasarte la noche preocupado. La realidad de que no hay un criterio claro de puntuación, y de que la admisión y el rechazo van y vienen, te pone los nervios de punta. Los colegas te recuerdan como “alguien afectuoso y con un sentido de la responsabilidad”, pero, tú mismo, sientes que no eres suficiente. Parece que todavía no sabes que precisamente esa diligencia y esa sensación de confianza son el valor que más desean las empresas.',
    s: [
      'Una sistematización y una confiabilidad excepcionales: tu sentido de la responsabilidad de no pasarte nunca de una fecha límite prometida, y de completar a la perfección el trabajo que te encargaron, te hace reconocer, en el equipo, como el socio más confiable.',
      'Una preparación delicada y una minuciosidad: tú, que preparas a la perfección hasta cada letra de una carta de presentación, hasta cada pregunta prevista de una entrevista, no te sacudes, ni siquiera en una situación inesperada.',
      'Una conciencia ética alta y una confiabilidad: tú, que, cuando un compañero del equipo lo está pasando mal, lo cuidas de forma natural, y que no dudas en cumplir una norma, obtienes con rapidez la confianza de un colega de un trabajo.'
    ],
    g: [
      'Salir de la trampa de la perfección: el hábito de agotar la energía, apuntando a 100 puntos, incluso en una situación en la que 80 bastan. Si aprendes el límite entre “lo suficiente” y “lo perfecto”, la búsqueda de un empleo se vuelve todavía más eficiente.',
      'Hacerte amigo de la incertidumbre: en el mercado de un empleo no hay una respuesta clara. También es importante una preparación perfecta, pero, si no cultivas la capacidad de recibir un feedback y de ajustar con flexibilidad, dejas pasar la siguiente oportunidad.'
    ],
    t: [T('Claude', 'main', 'El mentor cálido que convierte tu diligencia en un lenguaje confiable', 'Cuando escribes una carta de presentación, tu duda más grande será “si mi experiencia es suficiente”. A Claude, suéltale primero la historia de tu diligencia. Está bien preguntar “las experiencias que tuve me parecen demasiado ordinarias; ¿cómo las puedo expresar con impacto?”, y también está bien pedirle que pule el tono de una carta de presentación ya terminada. Claude recibe con afecto tu inquietud y, a la vez, te da un feedback objetivo. En especial, cuando tiemblas, delante de una entrevista, te aconseja, desde la posición de un entrevistador real, ante la pregunta “cuando dé esta respuesta, ¿qué parte convendría enfatizar más?”. Ejemplo: “en la universidad, como directivo del consejo de estudiantes, conduje la orientación de los de primer año, pero me parece que, solo con esto, no alcanza para mostrar liderazgo. ¿Cómo lo expreso?”', 'Tengo la tendencia de perseguir la perfección, así que sigo corrigiendo la carta de presentación. ¿Me puedes ver si esta carta de presentación ya está en un nivel suficientemente bueno? Y, ¿me puedes volver a ajustar el tono, para que mi diligencia y mi sentido de la responsabilidad se le transmitan al entrevistador como una sensación de confianza?'),
        T('Grammarly', 'specialist', 'La herramienta delicada de corrección que pule a la perfección, hasta cada letra de una carta de presentación', 'Tú ya prestas atención a la ortografía y a la gramática, pero Grammarly atrapa también el tono de una frase, la claridad y una expresión repetida, que se te pueden escapar. Si, después de escribir una carta de presentación, la chequeas con Grammarly, puedes recibir no solo un error simple de un espacio, sino también un feedback del tipo “esta frase tiene un tono demasiado rígido”. Si también revisas con Grammarly un correo, o una carta de agradecimiento después de una entrevista, puedes dejar una impresión profesional. Ejemplo: si pegas en Grammarly la carta de presentación que escribiste, puedes procesar de una vez el análisis del tono, la puntuación de la claridad y el chequeo de un plagio.', '¿Me puedes confirmar si esta carta de presentación está escrita en un tono claro y profesional? En especial, chequéame si hay una frase demasiado rígida o una expresión que se repite.'),
        T('Forest', 'specialist', 'El temporizador Pomodoro que protege tu concentración, hacia la perfección', 'Cuando escribes una carta de presentación, tienes la tendencia de, con el pensamiento de “esta parte, la tengo que cambiar a una expresión mejor”, quedarte 30 minutos agarrado a una sola frase. Si enciendes Forest, puedes gestionar el trabajo en un ciclo de 25 minutos de concentración + 5 minutos de descanso y, si no sueltas el teléfono hasta que termine el temporizador, crece un árbol virtual. Esto convierte tu perfeccionismo en un feedback positivo de “alcanzar un objetivo”. Ejemplo: si por la mañana dejas fijados 4 ciclos de Forest (100 minutos) y fijas un objetivo concreto de “terminar el primer párrafo de la carta de presentación + la revisión de Claude”, se convierte en un entrenamiento de terminar el trabajo con eficiencia, dentro de una limitación de tiempo.', 'Hoy tengo que hacer estas 3 cosas: el cierre de un portafolio, la corrección de una carta de presentación y la preparación de una entrevista; ¿cuántos minutos tendría que dedicarle a cada una, con Forest?')],
    syn: 'Si se combinan tu responsabilidad alta (C: 95%) y tu apertura baja (O: 30%), nace la fortaleza de una preparación rigurosa y de un plan sistemático. Si usas juntos Claude, Grammarly y Forest, la preparación de una carta de presentación y de una entrevista deja de ser una “mucha repetición” simple y se convierte en “una repetición de una alta calidad”. En especial, se crea el círculo virtuoso de gobernar tu perfeccionismo con una limitación de tiempo (Forest) y de verificarlo con un feedback objetivo (Claude + Grammarly). Como resultado, no solo sube la tasa de admisión, sino que también obtienes la confianza de “lo hice suficientemente bien”. Tu fortaleza de sinergia es imprimirle al entrevistador la imagen de “un postulante confiable”.',
    day: 'Así es tu día típico de la búsqueda de un empleo. Te levantas a las 7:00 de la mañana y, durante 30 minutos, ordenas en Notion la lista de chequeo de lo que hay que hacer ese día. En ese momento, le preguntas a Claude “la parte de la carta de presentación que tengo que preparar hoy es esta; ¿en qué orden sería eficiente?”. Desde las 8:00, enciendes Forest y empiezas el primer ciclo de 25 minutos de concentración. El objetivo es “escribir el primer párrafo de la carta de presentación de la empresa A”. Tomas 5 minutos de descanso y, en el segundo ciclo, pegas en Claude el párrafo que escribiste y dejas revisar el tono y la confiabilidad. Si recibes el consejo de “esta parte, estaría bien que fuera más concreta”, en el tercer ciclo lo corriges. Hacia las 11:00, revisas con Grammarly el párrafo terminado. Desde las 12:00, en el almuerzo, hacia cuando te llega la inquietud de “¿el trabajo que hice estaba en un nivel suficiente?”, vuelves a leer el feedback de Claude que recibiste por la mañana y retomas la confianza. A las 13:00, vuelves a encender Forest y preparas la respuesta a una pregunta prevista de la entrevista de la empresa B. Del mismo modo, llevas 3 ciclos de 25 minutos y, en cada ciclo, revisas la respuesta con Claude. Hacia las 16:00, cuando te llega la fatiga, recorres las cartas de presentación y las respuestas de una entrevista que terminaste, y sientes una pequeña sensación de logro. Desde las 17:00, haces la revisión final con Grammarly y confirmas, leyendo letra por letra, si no hay un error. A las 19:00, al “salir” (o al terminar la búsqueda de un empleo), chequeas, con Forest, el grado de concentración de hoy y ordenas en Notion la parte terminada y la parte incompleta. Hacia las 22:00, antes de dormirte, cierras el día armando el plan de “mañana voy a terminar estas, en un nivel todavía mejor”.'
  });
  add('01011', 'Quien ayuda a los demás, pero se queda corto de confianza: el buscador de empleo sensible y callado', 'Claude', ['Wysa', 'Notion AI'], {
    i: 'Tú, un buscador de empleo introvertido, diligente y cálido, pero sensible, sueles, aunque te gusta ayudar a otro, quedarte corto de confianza en tu propia búsqueda de un empleo. La capacidad de empatía es excepcional, así que ejerces una fortaleza en un puesto centrado en la gente —una consulta, la educación, el trabajo social, RR. HH.—, pero no estás habituado a ponerte tú adelante.',
    s: [
      'Con una responsabilidad y una amabilidad altas, das la impresión de un postulante en el que se confía, en un equipo, y, en una entrevista, se siente la autenticidad.',
      'Con una capacidad delicada de empatía, puedes apelar una fortaleza diferenciada, en un puesto que trata con la gente.',
      'Con una preparación callada, pero profunda, en una entrevista creas una imagen formal y diligente.'
    ],
    g: [
      'Aunque se te haga raro ponerte adelante, hace falta el ejercicio de expresar con claridad tu propia fortaleza.',
      'Deja armada una rutina de recuperación de la emoción, para no herirte en exceso con un rechazo.',
      'Si refuerzas una estrategia de gestión del tiempo, entre el plan y la ejecución, sube la eficiencia de la búsqueda de un empleo.'
    ],
    t: [T('Claude', 'main', 'El socio que expresa, con confianza, una fortaleza interior', 'Si le cuentas a Claude, con sinceridad, tu experiencia y tu valor, te los ordena en un lenguaje que le puedes entregar, con confianza, a un entrevistador.', 'Soy del tipo OCEAN 01011. Quiero conectar una experiencia de un voluntariado educativo con una carta de presentación de un puesto de planeación de RR. HH. Dime cómo convendría armarlo como una historia.'),
        T('Wysa', 'specialist', 'El socio del temple, de la búsqueda de un empleo, que protege una emoción sensible', 'Cuando, en medio de la búsqueda de un empleo, se te sacude la confianza, o te hieres con un rechazo, si conversas con Wysa, te recuperas con rapidez y puedes volver a empezar.', 'Yo siempre ayudo a otra persona y, en cambio, en la búsqueda de un empleo, no tengo confianza en mí. Dime un modo de cultivar la confianza.'),
        T('Notion AI', 'specialist', 'Sistematiza, para que un esfuerzo diligente de la búsqueda de un empleo no se desperdicie', 'Si gestionas, con Notion AI, el estado de una postulación y la versión de una carta de presentación, el esfuerzo diligente se acumula de forma sistemática y el estado de avance se ve a simple vista.', 'Ármame una página de Notion, de la búsqueda de un empleo, que gestione la lista de las empresas a las que postulo, el estado de una pregunta de una carta de presentación y la agenda de una entrevista.')],
    syn: 'Tú, con una responsabilidad (C) y una amabilidad (A) altas, tienes que usar la IA en dos vías: un entrenamiento de la expresión de la confianza y un respaldo emocional. Si, junto con la IA, practicas sacar en un lenguaje tu calidez interior, en una entrevista brilla tu autenticidad particular.',
    day: 'A las 8:00, con Wysa, el chequeo del ánimo de hoy. A las 9:00, con Claude, el ejercicio de la expresión de una carta de presentación o de una respuesta de una entrevista. A las 12:00, con Notion AI, el orden del estado de una postulación. A las 14:00, la redacción y la entrega de un documento. A las 19:00, con Claude, el ejercicio de un Q&A de una entrevista. A las 21:30, con Wysa, el cierre del día.'
  });
  add('01100', 'Quien, una vez fijado el objetivo, empuja sin vacilar: el ejecutor diligente y sereno', 'Notion AI', ['ChatGPT', 'Claude'], {
    i: 'Tú, un buscador de empleo diligente, extrovertido, frío y estable, eres el tipo ejecutor que, una vez fijado el objetivo, lo empuja sin sacudirte. También en medio de la búsqueda de un empleo, no te sacudes en lo emocional y te acercas de forma sistemática. Solo que tienes la tendencia de preferir un modo ajustado a un marco, más que una carta de presentación creativa o una respuesta flexible de una entrevista.',
    s: [
      'Con una responsabilidad y una extraversión altas, ejecutas de forma sistemática una actividad de postulación y, en una entrevista, te expresas con confianza.',
      'Como estás estable en lo emocional, no te sacudes mucho ni siquiera ante un rechazo, y tienes la resiliencia de pasarte, con rapidez, a la siguiente oportunidad.',
      'Con un estilo de comunicación directo y claro, tienes la capacidad de entregar, con claridad, la intención, en una entrevista.'
    ],
    g: [
      'Hace falta un entrenamiento de crear una historia creativa y original de una carta de presentación. Más que una enumeración general de un currículum, una narrativa diferenciada es lo que crea una admisión.',
      'Con el ejercicio de conversar con flexibilidad, en una entrevista, y de reaccionar al contexto del entrevistador, suaviza la impresión de verte rígido.',
      'Si incluyes más, en una carta de presentación, una experiencia que enfatice la empatía y la colaboración dentro de un equipo, se ensancha el espectro de una entrevista.'
    ],
    t: [T('Notion AI', 'main', 'El sistema de gestión que maximiza una búsqueda sistemática de un empleo', 'Si gestionas, de un vistazo, con Notion AI, una empresa a la que postular, el estado de un documento y la agenda de una entrevista, tu ejecución diligente se acumula, sin un desperdicio.', 'Soy del tipo OCEAN 01100. Quiero postular, de forma estratégica, a 15 empresas. Ármame la proporción entre una gran empresa, una empresa mediana y una startup, y la estrategia de postulación, por puesto.'),
        T('ChatGPT', 'specialist', 'El socio de una idea que sube la creatividad de una carta de presentación', 'Si le cuentas a ChatGPT tu experiencia y le preguntas un modo más original de un storytelling, se completa una carta de presentación que se sale del marco.', 'El borrador de mi carta de presentación se siente demasiado como una enumeración de un currículum. Cámbiame el mismo contenido, para que tenga más historia y más impacto.'),
        T('Claude', 'specialist', 'El socio de revisión que pule la lógica de una carta de presentación y la expresión de la empatía', 'Envíale a Claude una carta de presentación terminada y mejora la parte en la que faltan el flujo lógico y un elemento de una empatía humana.', 'Esta es la pregunta 3 de la carta de presentación de Hyundai Motor que escribí. Es “una experiencia de resolver un conflicto dentro del equipo”, pero está demasiado rígida. Corrígemela, para que sea más humana y genere más empatía.')],
    syn: 'Tú, con una responsabilidad (C) y una extraversión (E) altas, y estable, te vuelves más potente cuando aprovechas la IA en la combinación de “mi ejecución sistemática + el complemento creativo de la IA”. Prueba convertirte en un equipo en el que tú conduces la ejecución y la IA le suma el color.',
    day: 'A las 8:00, con Notion AI, confirmas el objetivo de la búsqueda de un empleo de hoy. A las 9:00, con ChatGPT, refuerzas la creatividad de una carta de presentación. A las 11:00, la redacción y la entrega de un documento. A las 14:00, con Claude, la revisión final. A las 16:00, la postulación a una empresa adicional. A las 21:00, con Notion AI, el chequeo de las partidas terminadas de hoy.'
  });
  add('01101', 'Quien va en línea recta hacia un resultado, el ejecutor diligente y sensible', 'ChatGPT', ['Wysa', 'Notion AI'], {
    i: 'Tú, un buscador de empleo diligente y extrovertido, pero sensible y frío, eres el tipo que se prepara de forma sistemática y, a la vez, reacciona de un modo extremadamente sensible a un resultado. Tienes un impulso fuerte de ir en línea recta hacia un logro, pero un rechazo te hiere a fondo. Una estrategia sostenible de gestión de la emoción es la llave del éxito de la búsqueda de un empleo.',
    s: [
      'Con una responsabilidad y una extraversión altas, reúnes de forma activa la información de una empresa y ejecutas, de forma sistemática, una estrategia de postulación.',
      'Con un juicio rápido y una comunicación directa, en una entrevista das una respuesta con confianza y clara.',
      'Con una tendencia orientada a un objetivo, ejecutas bien una estrategia de atacar, con concentración, una empresa y un puesto ya fijados.'
    ],
    g: [
      'Si te vuelves excesivamente sensible a un resultado de un rechazo, baja la capacidad de sostener la búsqueda de un empleo. Crea el hábito de evaluar el proceso, más que el resultado.',
      'Un impulso rápido puede dañar el grado de terminación de una carta de presentación. Asegura, de forma consciente, un rato suficiente de revisión.',
      'Si refuerzas la preparación de una respuesta que enfatice la colaboración con otro o el trabajo en equipo, se ensancha el espectro de una entrevista.'
    ],
    t: [T('ChatGPT', 'main', 'El socio que respalda, de forma estratégica, una ejecución rápida de la búsqueda de un empleo', 'Estrategiza, con rapidez, una carta de presentación, con ChatGPT, y ejecuta de inmediato la acción de la búsqueda de un empleo que hay que hacer hoy. A tu impulso se le suma una dirección.', 'Soy del tipo OCEAN 01101. Ármame un guion para responder, con confianza, en una entrevista de un puesto de ventas de LG Electronics, a la pregunta de “una experiencia de alcanzar un objetivo”.'),
        T('Wysa', 'specialist', 'El socio de cuidado del temple, que gestiona una reacción emocional sensible', 'Cuando, después del aviso de un rechazo o de un error en una entrevista, te vuelves extremadamente sensible, si conversas con Wysa, la emoción se estabiliza con rapidez y puedes avanzar hacia la siguiente acción.', 'Pensé que en la entrevista lo había hecho bien, pero me rechazaron. Me siento injusto y también me da rabia, pero quiero ordenar la emoción, con rapidez, y preparar la siguiente empresa.'),
        T('Notion AI', 'specialist', 'Maximiza la diligencia, con una gestión sistemática de la búsqueda de un empleo', 'Si gestionas, con Notion AI, el estado de una postulación, la agenda de una entrevista y la versión de una carta de presentación, tu ejecución diligente se acumula de forma estratégica.', 'Ahora mismo estoy postulando a 10 empresas. Ármame un rastreador de Notion, de la búsqueda de un empleo, en el que se vean de un vistazo, por empresa, el estado de un documento, la agenda de una entrevista, un punto de preparación y el resultado.')],
    syn: 'Tú, con una responsabilidad (C) y una extraversión (E) altas, y sensible, tienes que usar la IA, a la vez, como un amortiguador de la emoción y como un acelerador de la ejecución. Si gestionas la emoción con Wysa y ejecutas con rapidez con ChatGPT, la sensibilidad se convierte, no en un obstáculo de la búsqueda de un empleo, sino en una precisión.',
    day: 'A las 8:00, con Wysa, el chequeo del estado emocional de hoy. A las 9:00, con ChatGPT, la estrategización de la carta de presentación de hoy. A las 11:00, la redacción y la entrega de un documento. A las 14:00, con Notion AI, el chequeo de la agenda. A las 17:00, la preparación de una entrevista. A las 21:00, con Wysa, el orden de la emoción, al cierre del día.'
  });
  add('01110', 'El senior bodhisattva de muchas preocupaciones, el papá o la mamá de la sala de la carrera', 'Claude', ['Otter.ai', 'Headspace'], {
    i: 'En cuanto se abre la puerta de la sala de la carrera, se te amontonan los juniors, y tú pospones tu propia tarea y les revisas el informe. A la pregunta “senior, ¿esta parte está bien?”, se lo explicas con amabilidad, pero, a las 23:00, de pronto, vuelves a buscar un material, por si tu consejo se habrá equivocado. Eres el sabio virtuoso del campus. Cumples la regla al pie de la letra, eres de principios y, con una consideración cálida, cuidas a quien te rodea. Pero, en ese proceso, eres demasiado estricto contigo mismo y tienes la tendencia de no revelar bien tu propio valor, en una sociedad de competencia. También en una sala de entrevistas te inquietas con un “¿seré suficiente?”, pero, en realidad, lo que los entrevistadores evalúan más alto es tu autenticidad, tu confiabilidad y una actitud de entrega, por la organización. Eres material de pilar de una organización.',
    s: [
      'Un miembro de una organización, de una alta confiabilidad: alguien que cumple sí o sí una promesa, sigue un principio al pie de la letra, y en quien más confían y se apoyan los compañeros del equipo. Tu diligencia se convierte en el núcleo de la cultura de la organización y en la base de formar una relación humana de largo plazo.',
      'Una capacidad de empatía y un espíritu de colaboración: tú, que entiendes a fondo la dificultad de un junior y no escatimas tu propio tiempo, creas una sensación de seguridad psicológica dentro del equipo. Esto hace posible una colaboración verdadera, en un proyecto complejo.',
      'Una gestión minuciosa de la calidad y una autorreflexión: tu perfeccionismo de volver a verificar, una y otra vez, tu propio consejo, y de buscar siempre un método mejor, reduce el error de un proyecto y crea un resultado de una alta confiabilidad.'
    ],
    g: [
      'La dificultad de fijar la prioridad de tu propia tarea: como te gusta ayudar a otro, tu propio crecimiento y el desarrollo de la carrera pueden quedar en un segundo plano. Tienes que cultivar la capacidad de fijar un límite claro y de asegurar tu propio tiempo, para llevar ventaja en la búsqueda de un empleo.',
      'Una verificación excesiva de ti mismo y una demora de una decisión: el hábito de reconfirmar una y otra vez, por si te equivocas, retrasa la velocidad de una decisión. Hace falta el valor de ejecutar con osadía, sobre un fundamento de un nivel razonable.'
    ],
    t: [T('Claude', 'main', 'La IA que convierte tu calidez en una fortaleza de un anuncio de contratación', 'Claude es el colega sólido que verifica con cortesía tu consejo y pule una frase de una carta de presentación. Por ejemplo, cuando dudas cómo escribir, en una carta de presentación, la experiencia de haber ayudado a un junior, si le pides “exprésame, como un liderazgo, la experiencia de haber guiado a un junior”, Claude traduce tu carácter, en una frase cálida y, a la vez, profesional, al lenguaje que desea una empresa. También cuando, la víspera de una entrevista, te llega la inquietud, puede reinterpretar tu experiencia y subirte la confianza.', 'Invierto mucho tiempo en cuidar a un senior o a un junior, así que mi nota se me puede bajar. ¿Me puedes proponer un modo de expresar, de forma positiva, este carácter mío, en una carta de presentación? En una frase que muestre el liderazgo y el trabajo en equipo y, a la vez, también revele la confianza en mí mismo.'),
        T('Otter.ai', 'specialist', 'El diario de voz y el orden automático, para una noche inquieta', 'A las 23:00, cuando te viene la inquietud, suéltale el pensamiento, en voz, a Otter.ai. Si grabas la inquietud de “¿el concepto que le expliqué hoy al junior habrá sido perfecto?”, Otter.ai lo convierte en automático en un texto y, a la mañana siguiente, lo puedes revisar de forma objetiva. En ese proceso, te das cuenta de que la mayor parte de la inquietud no tiene un fundamento, y solo queda el punto real de mejora. Además, si grabas y revisas una respuesta que preparaste, después de una entrevista, puedes subir la naturalidad de hablar.', '¿Me conviertes en un texto la voz de la autopresentación que grabé y me dices si hay una expresión rara o que se repite?'),
        T('Headspace', 'specialist', 'La app de meditación que alivia la inquietud de un empleo y una conciencia excesiva de autocrítica', 'Tú, hasta tarde en la noche, vuelves a buscar un material y te preocupas, y, desde que te levantas por la mañana, empieza la duda de “¿podré hacerlo?”. Haz, por la mañana y por la noche, una meditación de 5 a 10 minutos de alivio de la inquietud, de Headspace. En especial, en una temporada de estrés de un empleo, ayuda la meditación de “Self-Compassion”. Practicas cuidarte a ti mismo, del mismo modo en que tú siempre cuidas a otro. La víspera de una entrevista prevista, en el período del anuncio de un empleo, estabilizas el ánimo.', 'En medio de la preparación de un empleo, sigo inquietándome y me entra el ánimo de dudar de mí mismo. ¿Me puedes recomendar una rutina de meditación que pueda hacer, cada día, durante 3 semanas?')],
    syn: 'Tu O (28%) te hace aprender con rapidez, sin un preconcepto, una tendencia nueva de un empleo, y una C alta (92%) y una A (95%) te hacen ordenar esa información de forma sistemática y compartirla con los compañeros del equipo. Con una extraversión adecuada de la E (75%), en un proyecto de equipo desempeñas un papel callado, pero de influencia. Si pules una carta de presentación con Claude, reinterpreta tu “cuidado” como “un liderazgo”; si objetivas, con Otter.ai, la inquietud de la noche; y si, con Headspace, detienes la autocrítica, te conviertes en la combinación más fuerte del mercado de un empleo: “una diligencia confiable + una consideración cálida + una toma de decisiones razonable”. En especial, en un trabajo basado en un equipo o en un puesto de un liderazgo de un recién llegado, el portafolio que tú armas es distinto.',
    day: 'A las 7:00 de la mañana, antes de levantarte de la cama, empiezas el día con una meditación de 5 minutos de Headspace. Con la disposición de “hoy también, empecemos confiando en mi capacidad”. A las 8:30, al llegar al campus, mientras tomas un café, le ordenas a Claude lo que hay que hacer hoy. Si compartes la lista de “escribir la sección de autopromoción de la carta de presentación + por la tarde, guiar la preparación de una entrevista de un junior + la fecha límite de una tarea de un club”, Claude piensa, junto contigo, la prioridad. A las 10:00, cuando se te traba la redacción de la carta de presentación, conversas de forma concreta, con Claude, sobre “qué papel tuve yo, en un proyecto de equipo”. Claude reinterpreta tu experiencia, con las palabras clave de “liderazgo”, “sentido de la responsabilidad”, “colaboración”. A las 13:00, después del almuerzo, mientras respondes a la pregunta de un junior, si te viene la inquietud de “¿y si me habré equivocado?”, grabas esa inquietud, en voz, durante 5 minutos, en Otter.ai, y la guardas (un registro objetivo que vas a revisar después). A las 15:00, antes de ayudar a un junior en la preparación de una entrevista, vuelves a ordenar el corazón, con una meditación de estabilización de 2 minutos de Headspace. Porque, si tú mantienes la serenidad, también el junior se puede preparar de forma estable. A las 17:00, mientras llevas una tarea de un club, grabas tu pensamiento en voz y lo guardas en Otter.ai. A las 20:00, después de “salir”, lees, a continuación de la mañana, las inquietudes que grabaste anoche. Confirmas que “después de todo, salió bien” y anotas en una nota solo uno o dos puntos reales de mejora. A las 22:00, mientras te preparas para mañana, pules, junto con Claude, una frase más de la carta de presentación y cierras el día, con una meditación de 5 minutos de autocompasión, de Headspace. “Está bien aunque no sea perfecto. Me esforcé de sobra, y soy, de sobra, una buena persona.” Esta es tu cotidianidad.'
  });
  add('01111', 'Amor a los compañeros, amor al país: el hyeongnim que volvió a la universidad', 'ChatGPT', ['Canva Magic', 'NotebookLM'], {
    i: 'Un día antes de la fecha límite de un concurso, cuando los compañeros del equipo entran en pánico, tú ya terminaste las propuestas de planeación de tres concursos. La pregunta “¿eh? ¿lo volviste a hacer?” es tu cotidianidad. Tu verdadera fortaleza no es una capacidad individual, sino “una capacidad de ejecución de no rendirte nunca” y “una capacidad de contagio, de mover a la gente”. Al encontrarse una responsabilidad alta (C 95%) y una afinidad (A 95%), te conviertes en el centro de gravedad del equipo. Los colegas te ven como “el senior al que no se le encuentra una maldad”. Pero la obsesión hacia la perfección y la actitud de querer cuidarlo todo, a veces, también llaman un burnout. La razón por la que una empresa te cobicia no es una idea brillante, sino la confiabilidad de sacar una misión dada “con precisión, con rapidez, juntos”. Más que un innovador que cambia el mundo, un ejecutor que mueve el mundo: eso eres tú.',
    s: [
      'Una sensación de velocidad y una sistematización distintas, en la recolección de información de un concurso o de una actividad externa. Con la capacidad de gestión de un plazo y de ejecución de una lista de chequeo, conduces de forma estable un proyecto de equipo, y un temple que no se sacude, ni siquiera ante el estrés de una fecha límite.',
      'Con una responsabilidad alta, te apropias a la perfección de la norma de un concurso, del criterio de evaluación y del formato de entrega, y, con la capacidad de comunicación de compartírselo, con claridad, a los compañeros del equipo, cortas de raíz un descuido.',
      'Con una sociabilidad excepcional, formas una red con personas diversas, en el proceso de una colaboración mantienes la moral del equipo y, con la resiliencia de volver a desafiar, de forma positiva, también ante un rechazo, logras una cadena de admisiones.'
    ],
    g: [
      'Hace falta, al salir de la obsesión con el volumen de una actividad, concentrarte en “un crecimiento cualitativo”. Más que aumentar el número, la experiencia de terminar a fondo un solo proyecto envía, en el mercado de un empleo, una señal más fuerte.',
      'Tienes la tendencia de querer controlar a la perfección el estado de avance del equipo, así que puedes reprimir la creatividad y la iniciativa de otro. Hay margen de crecer, hacia un liderazgo que delega y confía.'
    ],
    t: [T('ChatGPT', 'main', 'El eje del orden de un material de un concurso y de la comunicación del equipo', 'Tu cotidianidad empieza por leer el anuncio de un concurso. El proceso de pegarle a ChatGPT, de un golpe, la norma y el material de un concurso, extraer el núcleo y armar un resumen para que los compañeros del equipo lo entiendan con facilidad, se repite 4 o 5 veces al día. En especial, cuando explicas, desenredándolo con claridad, un criterio complejo de evaluación o una condición técnica, ChatGPT es tu herramienta de “acelerar la comunicación”. Por ejemplo, si preguntas “¿me ordenas, en 3 líneas, el PDF del criterio de evaluación de este concurso, para que lo pueda entender un compañero de este nivel (un recién llegado)? Y, ¿cuál es la condición indispensable que, si la dejamos pasar, nos rechazan?”, ChatGPT te presenta el borrador en 5 segundos, y tú lo vuelves a pulir, en el lenguaje del equipo, y lo compartes. Como resultado, el equipo baja la barrera de entrada del concurso, y tú acumulas la confiabilidad como líder.', 'Lee las bases de este concurso (el texto) y, ¿me ordenas ① la condición indispensable de la cualificación, ② las 3 cosas más importantes en la evaluación, ③ 3 “puntos de diferenciación” distintos de una obra premiada del pasado? Para que nuestro equipo pueda juzgar, en 5 minutos, si este concurso nos encaja.'),
        T('Canva Magic', 'specialist', 'El material de entrega de un concurso, 2 veces más rápido y 3 veces más atractivo', 'Tú te llevas bien con la gente, pero sabes que te falta un instinto de diseño. Aquí, la función de una propuesta de IA de Canva Magic se convierte en el lanzador de rescate. Si introduces el contenido de una propuesta de planeación, te presenta en automático una plantilla, un color y una disposición de una imagen que encajan. Por ejemplo, si le das el briefing de “hay que armar un póster de un programa de apoyo a los jóvenes, esperanzador y, a la vez, confiable”, Canva Magic, en 3 segundos, te propone 5 direcciones de un diseño. Tú eliges, de entre ellas, la que encaja con el tono del equipo y, solo con un poco de corrección del texto, se completa un material profesional. A través de esto, tu equipo recorta el tiempo y sube la primera impresión.', 'El tema del concurso de nuestro equipo es “un desarrollo urbano sostenible”, y el objetivo es una generación ya establecida (de 40 a 60 años). Quiero armar un póster confiable y, a la vez, orientado al futuro; ¿me puedes presentar 3 direcciones de un diseño que me recomiendes, y una combinación de una imagen que se pueda usar?'),
        T('NotebookLM', 'specialist', 'Transforma el material de un concurso y la nota del equipo en una clase de voz', 'Cuando, en el proceso de la preparación de un concurso, el equipo está disperso, subes a NotebookLM el material que reuniste hasta ahora (un paper de referencia, una estadística, la propuesta de planeación del equipo) y le pides “¿me puedes armar, con base en estos materiales, un resumen de voz de 5 minutos, del trasfondo y del fundamento de nuestro proyecto?”. Entonces, la IA sintetiza todos los materiales y genera un informe de audio, continuo y convincente. Los compañeros del equipo, de camino al trabajo o al comer, escuchan este material de voz y se hacen una idea, con rapidez, del contexto del proyecto. En especial, en un concurso con mucha investigación bibliográfica o un análisis estadístico (académico, una propuesta de una política, I+D), tu equipo abruma a otro equipo, en la velocidad de la preparación.', '¿Me puedes armar, sintetizando los materiales que hay en esta carpeta (un documento de una estadística, la propuesta de planeación del equipo, 3 papers de referencia), una clase de audio de 3 minutos que explique, de forma convincente, “el reconocimiento de un problema → una vía de solución → el efecto previsto” de nuestro proyecto de un concurso?')],
    syn: 'La combinación de tu perfil OCEAN (una responsabilidad, una afinidad y un neuroticismo altos) y de ChatGPT, Canva Magic y NotebookLM crea “un jugador de velocidad de la industria de un concurso”. Tradicionalmente, la preparación de un concurso avanzaba en secuencia: “una idea > una planeación > una producción > una revisión”, pero tú, con una herramienta de IA, lo paralelizas. Al mismo tiempo que verificas una planeación con ChatGPT, armas el visual con Canva Magic y sincronizas al equipo con NotebookLM. Como resultado, tu equipo, en el mismo tiempo, postula al doble de concursos que un equipo competidor, y registra una tasa de admisión más alta. Por ejemplo, el resultado de, en un semestre, al postular a 10 concursos, obtener de promedio 3 o 4 premios, no es una coincidencia: es el resultado de “un sistema”. Esta experiencia se conecta de forma directa, después de entrar a un empleo, con “una capacidad de gestión de un proyecto” y “una capacidad de una decisión rápida”, y te asciende de “un recién llegado preparado” a “un líder en el que se confía”.',
    day: 'A las 8:00 de la mañana, en un café, mientras tomas un café, lo primero es confirmar 3 sitios de un concurso. Entraron 2 anuncios nuevos. Abres de inmediato una pestaña de ChatGPT, pegas el texto completo de la norma y introduces “la posibilidad de que nuestro equipo postule a este concurso y 3 condiciones centrales”. En 30 segundos sale la respuesta. Un equipo que necesita una mentoria recibe tu análisis y decide si seguir. A las 10:00, de las 4 propuestas de planeación de un concurso que solicitaste la semana pasada, queda una fecha límite. Recibes el borrador del equipo y lo subes a NotebookLM. Si introduces el prompt “¿esta propuesta encaja con el criterio de evaluación que identificamos (súbelo también) y, la parte que falta, me la señalas de forma concreta?”, la IA genera de inmediato un informe de verificación. Lo compartes con el equipo y quedan en recibir la versión corregida hasta las 13:00. En el almuerzo, comes solo y enciendes Canva Magic. Porque la entrega del póster de otro concurso queda en 3 días. Esta vez, el tema es “la creación de un empleo para un senior”, y el objetivo es una capa de mediana edad (de 40 a 60 años). Introduces “Canva Magic, ¿me recomiendas 3 direcciones de un póster, de una sensación confiable y, a la vez, cálida? El objetivo es una capa de mediana edad, y tiene que dar la sensación de un programa de apoyo del gobierno”. 3 segundos después, aparecen 5 direcciones de un diseño. Eliges 2 que encajan con el tono del equipo y subes la captura al chat del equipo. Dejas el mensaje “¿cuál de estas sensaciones les gusta? Voten hasta las 15:00, y yo, hasta las 20:00, subo la versión final”. A las 14:00, 5 personas de un equipo que necesita una verificación se reúnen en tu oficina (o en la sala de lectura). En lugar de mostrarles, tal cual, el informe de verificación que generó ChatGPT, lanzas una pregunta al estilo de Sócrates: “esta parte es la más importante; ¿por qué será?”. Los compañeros del equipo, al encontrar la respuesta por sí mismos, se sumergen todavía más a fondo en el proyecto. Este es tu liderazgo. A las 16:00, recibes la petición de una mentoria de otro equipo. Dicen que la propuesta de planeación de ese equipo se trabó. Dedicas 30 minutos y, junto con ChatGPT, vuelves a alinear su idea. Cuando tu equipo postula a 10, los otros equipos, con tu ayuda, llegan a postular a 3 o 4 cada uno. A las 18:00, sale el resultado de la votación del equipo. Decidieron ir por la dirección número 2, de las propuestas de Canva Magic. Abres de inmediato la ventana de edición detallada de Canva y le sumas un texto que refleja el mensaje central del equipo (3 puntos extraídos del resumen de voz de NotebookLM). A las 20:00, se suben al chat del equipo 3 versiones finales del póster. Dices “mañana por la mañana lo miro una vez más y, por la tarde, lo entrego”. No hace falta apurarse. Porque tú ya trabajaste adelantando el plazo. A las 21:00, incluso cuando descansas en casa, reproduces una y otra vez el resumen de voz de NotebookLM. Para grabarte a fondo, en la cabeza, el contexto del proyecto de un concurso que vas a llevar mañana. Este es tu método inconsciente de gestión del liderazgo. A las 23:00: 2 anuncios nuevos previstos para mañana, 4 concursos en curso, 3 equipos que necesitan una verificación. Tu cabeza ya está llena del plan de mañana. Al encontrarse la inquietud (un neuroticismo alto) y el sentido del deber (una responsabilidad alta), estás despierto, incluso mientras duermes. Este es el secreto con el que digieres “un volumen de actividad de locos”, pero, a la vez, es también la señal de un burnout con el que, algún día, te vas a encontrar. Piensas que mañana tendrías que tomarte un rato más de descanso, pero, a las 00:00, suena el teléfono. Otro equipo pide una ayuda de último momento. Tú te vuelves a levantar.'
  });
  add('10000', 'Quien se aferra a su propio modo, el buscador de empleo creativo, introvertido y sereno', 'Claude', ['Perplexity', 'Notion AI'], {
    i: 'Tú, creativo, introvertido, frío y estable, eres el tipo independiente que, también en medio de la búsqueda de un empleo, no pierde su propio ritmo. Tienes la tendencia de aferrarte al modo que tú juzgaste correcto, más que a un método de moda de la búsqueda de un empleo. Precisamente esa originalidad, en un puesto de investigación, de tecnología o de creación, se convierte, al contrario, en una fortaleza.',
    s: [
      'Con una creatividad alta y un juicio frío, sin dejarte sacudir por la emoción, ejecutas de forma sistemática tu propia estrategia de la búsqueda de un empleo.',
      'Con un pensamiento original que no sigue una moda, creas una historia con personalidad, distinta de una carta de presentación general.',
      'Con un temperamento estable, incluso en un período largo de la búsqueda de un empleo, puedes prepararte con constancia, sin un burnout.'
    ],
    g: [
      'Como la independencia es fuerte, puedes ser pasivo a la hora de recibir una ayuda o de compartir una información. Recibe un input estratégico, de la IA o de una comunidad.',
      'Si te apegas demasiado a tu propio modo, puedes dejar pasar una tendencia de contratación o un requisito de una empresa. Cultiva un poco más la flexibilidad.',
      'Hace falta el ejercicio de expresar, en una carta de presentación o en una entrevista, tu propio pensamiento, en un lenguaje que otra persona pueda entender con facilidad.'
    ],
    t: [T('Claude', 'main', 'El socio que traduce un pensamiento original a un lenguaje que cualquiera puede entender', 'Si le explicas a Claude tu idea y tu experiencia originales, te las ordena en un lenguaje claro que un entrevistador puede entender.', 'Soy del tipo OCEAN 10000. En una entrevista tengo que explicar una metodología de análisis de un dato que desarrollé, a mi propio modo original. Dime el modo de explicarla para que también un no especialista la pueda entender.'),
        T('Perplexity', 'specialist', 'La herramienta de exploración de un conocimiento que maximiza una investigación independiente', 'Si, con Perplexity, exploras a fondo, solo, un puesto y una industria, a tu perspectiva original se le suma una base sólida de conocimiento.', 'Analízame la tendencia reciente de inversión del ecosistema de una startup de IA y a los jugadores principales. Junto con un punto de diferenciación, para un empleo en este campo.'),
        T('Notion AI', 'specialist', 'La herramienta de gestión personal que construye un sistema independiente de la búsqueda de un empleo', 'Si construyes, con Notion AI, tu propio sistema de la búsqueda de un empleo, puedes llevarla de forma sistemática, también sin una ayuda externa.', 'Quiero armar, con Notion, mi propio sistema de gestión de la búsqueda de un empleo. Diséñamelo para que pueda gestionar, en un solo espacio, el puesto objetivo, el análisis de una empresa, la versión de una carta de presentación y el feedback de una entrevista.')],
    syn: 'Tú, con una creatividad (O) alta, independiente y estable, encajas mejor cuando aprovechas la IA de forma estratégica, dentro de tu propio sistema. Déjale a la IA la traducción de un pensamiento original, y concéntrate tú en fijar la dirección y en la ejecución.',
    day: 'A las 9:00, con Notion AI, confirmas el objetivo de la búsqueda de un empleo de hoy. A las 10:00, con Perplexity, una investigación independiente de una empresa y de un puesto. A las 13:00, con Claude, la puesta en un lenguaje de una carta de presentación o de una respuesta de una entrevista. A las 16:00, el trabajo de un portafolio. A las 20:00, la entrega de una postulación. A las 22:00, con Notion AI, el orden del avance de hoy.'
  });
  add('10001', 'Quien recarga energía pensando a fondo, solo: el buscador de empleo creativo y sensible', 'Claude', ['Perplexity', 'Wysa'], {
    i: 'Tú, un buscador de empleo creativo, sensible e introvertido, obtienes energía en el rato de pensar a fondo y de explorar, solo. La cultura de la competencia y de la comparación, de la búsqueda de un empleo, se te siente especialmente dura, pero precisamente esa sensibilidad se convierte, al contrario, en una carta de presentación refinada y en una preparación profunda de una entrevista. Tu perspectiva original particular es la fortaleza.',
    s: [
      'Con una creatividad alta y una capacidad profunda de pensamiento, creas una historia original de una carta de presentación, que los demás no escriben.',
      'Con una concentración de ahondar en silencio, solo, haces, más a fondo que nadie, el análisis de una empresa y la comprensión de un puesto.',
      'Con un instinto sensible, en una entrevista tienes la capacidad de captar con rapidez la intención de un entrevistador y de reaccionar de forma adecuada.'
    ],
    g: [
      'Cuando la inquietud se convierte en una duda de ti mismo, pide un feedback objetivo, a la IA o a un mentor, y mantén una autoevaluación realista.',
      'Si te preparas solo, nace un ángulo muerto de la información. Prueba participar, un poco a poco, en una comunidad o en un grupo de estudio de la búsqueda de un empleo.',
      'Si dejas armada una rutina de aliviar la tensión, en una entrevista, la profundidad interior se puede revelar, en la práctica, en una entrevista.'
    ],
    t: [T('Claude', 'main', 'El socio que convierte un pensamiento original en un lenguaje convincente', 'Si le cuentas a Claude, con libertad, tu pensamiento original, te lo traduce a un lenguaje que un entrevistador puede entender.', 'Soy del tipo OCEAN 10001. En una entrevista de un puesto de investigación, parece que van a preguntar “una experiencia de intentar un acercamiento distinto de lo actual”. Dime el modo de expresar, de forma convincente, mi pensamiento original.'),
        T('Perplexity', 'specialist', 'La herramienta de una investigación profunda de una empresa y de un puesto, también en solitario', 'Si analizas a fondo, solo, con Perplexity, la tendencia de la industria y el entorno de la competencia de una empresa a la que postulas, en una entrevista puedes ofrecer un insight agudo.', 'Estoy preparando una entrevista de un puesto de análisis de un dato, de una empresa de IA. Ordéname, para que lo pueda aprovechar en una respuesta de una entrevista, la tendencia reciente de un LLM y un caso de una aplicación práctica.'),
        T('Wysa', 'specialist', 'La red de seguridad emocional que protege un corazón sensible', 'Cuando, al cargar solo el peso de la búsqueda de un empleo, te agotas, si se lo sueltas a Wysa, se te aligera la carga psicológica.', 'Al buscar un empleo, solo, me siento solo y agotado. Parece un burnout; ¿cómo puedo volver a encontrar la energía?')],
    syn: 'Para ti, introvertido, de una creatividad (O) alta y sensible, la IA desempeña dos papeles: maximizar la profundidad de una búsqueda de un empleo que preparas solo y, a la vez, aliviar la inquietud. Si le sumas profundidad con Claude y proteges el temple con Wysa, se convierte en una búsqueda de un empleo sostenible.',
    day: 'A las 9:00, con Wysa, el chequeo emocional de la mañana. A las 10:00, con Perplexity, una investigación de una empresa y de un puesto. A las 12:00, con Claude, la preparación de una carta de presentación o de una entrevista. A las 15:00, un horario de un trabajo de concentración, solo. A las 19:00, la entrega de una postulación. A las 21:00, con Wysa, el cierre del día y un solo plan de mañana.'
  });
  add('10010', 'El de corazón tierno que carga el trabajo en equipo, el santo del campus', 'Claude', ['Suno AI', 'Wysa'], {
    i: 'El día de la presentación de un proyecto de equipo, tú le haces abrir los ojos de golpe al profesor, con una idea fresca que los demás ni imaginaron, pero, en realidad, no les pones la mano ni al orden del material de un PPT ni a la redacción de la bibliografía, y dejas a los compañeros del equipo en ascuas. Eres un soñador rebosante de sensibilidad, y tu ojo de ver el mundo de otro modo es realmente especial. Pero, en cuanto sale la palabra “una lista de chequeo realista”, se te nublan los ojos. Ante una mirada dura de una comunidad de la búsqueda de un empleo, se te hiere el corazón con facilidad, y, en la competencia de una certificación o de un currículum, te falta la motivación. Aun así, esa perspectiva original tuya y una capacidad abundante de expresión son una fortaleza absoluta, en un campo creativo como la planeación de un contenido, el marketing de una marca, la producción de un video. Lo único que te hace falta es “un socio técnico” que convierta la imaginación en una realidad.',
    s: [
      'La capacidad de descubrir una idea original: la capacidad de, en un tema dado, sacar una perspectiva creativa y un insight que los demás no se les ocurriría nunca. En la etapa inicial de una planeación, puedes conducir al equipo en una dirección completamente nueva.',
      'Una capacidad de expresión emocional y de empatía: puedes expresar con refinamiento una emoción compleja y una psicología sutil, así que, en un ensayo, en un copywriting, en un storytelling, conmueves el corazón de otro.',
      'Una sensibilidad visual y un juicio estético: como percibes de forma intuitiva la belleza de un color, de una tipografía, de una composición, ejerces un sentido excepcional, en la planeación de un diseño o en la curaduría de un contenido.'
    ],
    g: [
      'Una falta de una capacidad de ejecución y la trampa de “a medias”: la idea perfecta está, pero, en el orden de un detalle, en cumplir una fecha límite, en un trabajo repetitivo, sueles soltar la mano. Te acaba tocando pedirle perdón, con frecuencia, a un colega.',
      'Una vulnerabilidad del temple y una autocrítica: tomas incluso un feedback negativo pequeño de un modo grave, se te baja la confianza y esto, otra vez, puede convertirte en el círculo vicioso de posponer la ejecución.'
    ],
    t: [T('Claude', 'main', 'El lógico cálido que, protegiendo tu sensibilidad, pule una idea con un alto grado de terminación', 'Claude es tu socio de creación más confiable. Ordena, como una propuesta concreta de planeación, un concepto que se te ocurrió de forma borrosa, y te llena el fundamento lógico que te falta. Por ejemplo, al escribir una carta de presentación de un empleo, es excepcional su capacidad de reinterpretar tu expresión emotiva, manteniéndola y, a la vez, convirtiéndola en un resultado concreto y en una capacidad que desea una empresa. Si por la mañana le cuentas, tal como se te ocurrió, la idea que tienes en la cabeza, Claude la convierte en un mapa mental sistemático, en una propuesta de composición de una presentación, en un copywriting. Ejemplo: si preguntas “la campaña que pensé… eh, está conectada de algún modo con la soledad de una relación humana; ¿cómo la fundo en un producto?”, Claude te presenta, como una estrategia terminada, desde el análisis de la capa objetivo hasta la dirección creativa.', 'Tengo esta experiencia que viví en la época de la universidad: [una experiencia personal explicada de forma emotiva]. ¿Me la puedes volver a escribir, de forma adecuada a una carta de presentación del equipo de marketing de Samsung Electronics? De un modo que mantenga mi emoción y, a la vez, se conecte con una capacidad concreta que necesita la empresa (un análisis de un dato, la fijación de un objetivo, la comprensión de una marca).'),
        T('Suno AI', 'specialist', 'La herramienta de creación que expresa tu emoción en una música y la sublima como un contenido de una marca', 'Suno AI es la herramienta que más hace brillar tu creatividad. Puedes generar tú mismo una música de fondo que hace falta en un proyecto de una marca o en un video de un portafolio, un sound logo que lleva la sensibilidad de una campaña, o una música que expresa tu estado emocional. Por ejemplo, si introduces “una música de fondo de un anuncio de una tarjeta de crédito, que lleva la soledad y la esperanza de un joven”, nace tu propia música original, sin un problema actual de un derecho de autor. Si la insertas en un video de un portafolio de un empleo, se convierte en un resultado de un alto grado de terminación, que mueve incluso la emoción de un jurado. En especial, para ti, que apuntas a un puesto de un creador de un contenido o del marketing de una marca, se convierte en un arma potente que demuestra “una originalidad que no depende de una canción ya hecha”.', 'Petición de producción de una música de fondo, para un video de onboarding de una app financiera a medida de un joven. Tono: cálido, pero contemporáneo; tempo: una rapidez media; emoción: una sensación en la que se mezclan la ilusión de un comienzo nuevo y una inquietud pequeña. Instrumento: piano + un synth + un drum minimalista. Duración: 30 segundos.'),
        T('Wysa', 'specialist', 'Tu estabilizador emocional, que trata el estrés de un empleo y un agotamiento de la emoción', 'Wysa es un chatbot de salud mental, basado en IA, y es una herramienta que de verdad le hace falta a un buscador de empleo emotivo y de un temple sensible, como tú. Cuando te hieres con el feedback de una carta de presentación, cuando se te baja la confianza por un rechazo de una entrevista, o cuando, simplemente, caíste en el reproche de “¿por qué yo no puedo como los demás?”, si conversas con Wysa, puedes tratar la sensibilidad, a través de una técnica profesional de psicología (una terapia cognitivo-conductual, un mindfulness, etc.). Por ejemplo, si, después de una entrevista de una empresa a la que no entraste, dices “parece que soy alguien a quien le falta algo”, Wysa objetiva este pensamiento negativo y te presenta una perspectiva nueva. En tu recorrido de un empleo, la salud mental se convierte, de inmediato, en una capacidad de ejecución, así que esta herramienta, más que una consulta psicológica simple, es “una infraestructura indispensable del éxito de un empleo”.', 'Estos días, cada vez que escribo una carta de presentación, me entra la culpa de “¿esto soy yo de verdad? Parece que estoy mintiendo”. No distingo si mi emoción es auténtica, o si, simplemente, no tengo autoestima. ¿Tú qué piensas?')],
    syn: 'Tu perfil OCEAN (una apertura del 95%, una amabilidad del 92%) es la combinación perfecta de “un contenido creativo y una empatía emocional”. Si se encuentran la estructuración lógica de Claude + la expresión musical de Suno AI + la estabilización emocional de Wysa, te transformas de un simple “artista que sueña” a “un creador que lo convierte en realidad”. En especial, en el campo del marketing, de la publicidad, de la planeación de un contenido, la combinación de “una idea emotiva + una estrategia lógica + una obra original” se convierte en el elemento más potente de diferenciación, y puedes armar un portafolio único, en un mercado de buscadores de empleo de mucha competencia. El grado de terminación de un video de una campaña de un anuncio que tú armes (con la música de fondo, incluso, producida con Suno) queda en un nivel que no se puede comparar con el de un buscador de empleo general.',
    day: 'Tu día es la búsqueda del equilibrio entre la sensibilidad y la capacidad de ejecución. A las 9:00 de la mañana, antes de levantarte de la cama, haces, a la ligera, con Wysa, “el chequeo de la emoción de hoy”. Solo con reconocer “hoy el estado de la confianza está bajo”, ya te preparas para empezar el día de forma proactiva. A las 10:00, te sientas en el escritorio y le cuentas a Claude lo que hay que hacer hoy. Si dices, con sinceridad, “quiero escribir un informe de marketing, pero se me hace difícil empezar”, Claude te ayuda a empezar con suavidad, del modo de “primero, se nos ocurren 3 ideas centrales”. De las 11:00 a las 13:00, tu horario de creación. Es el rato de concretar, con libertad, una idea, junto con Claude. A las 14:00, después del almuerzo, cuando aparece la fatiga, haces 10 minutos de mindfulness, con Wysa. A las 15:00, si te hace falta una música de fondo para un video de un portafolio, enciendes Suno AI. Si introduces “una música de fondo de un video de un personaje joven, en el que conviven la soledad y la esperanza”, en menos de 30 minutos sale una música terminada. A las 18:00, junto con Claude, ordenas el resultado que creaste hoy y, cuando te entra un ánimo de culpa, recibes “un feedback objetivo”. A las 21:00, cierras el día, haciendo, con Wysa, “el orden de la emoción”, para mañana. Así, mientras las herramientas de IA hacen circular tu sensibilidad, tu lógica y tu ejecución, dejas de ser “alguien que solo sueña” y te conviertes en “alguien que crea un sueño”.'
  });
  add('10011', 'Quien siente a fondo la emoción de otro, el buscador de empleo creativo, cálido y sensible', 'Claude', ['Wysa', 'Notion AI'], {
    i: 'Tú, un buscador de empleo introvertido, creativo y cálido, pero sensible, tienes una capacidad distinta de sentir a fondo la emoción de otro y de empatizar. Ejerces una fortaleza en un trabajo creativo o en un puesto de ayudar a la gente, pero el ambiente competitivo de la búsqueda de un empleo te puede provocar un agotamiento emocional. El núcleo es reinterpretar tu propia sensibilidad como una fortaleza.',
    s: [
      'Con una capacidad profunda de empatía y una creatividad, tienes una fortaleza diferenciada, en un puesto centrado en la gente: UX, una consulta, el trabajo social, la educación.',
      'Con una capacidad delicada de observación, en una carta de presentación metes un insight de un detalle que otro postulante deja pasar.',
      'Tienes la capacidad de transmitir la autenticidad, con una respuesta callada, pero profunda, de una entrevista.'
    ],
    g: [
      'Reconoce la tendencia de encogerte en exceso, ante la noticia del empleo de otro, y hace falta la disposición de confiar en tu propia línea de tiempo.',
      'Si sistematizas, con la IA, un patrón de la búsqueda de un empleo de moverte según la emoción, sin un plan, sube la sostenibilidad.',
      'Practica, con constancia, expresar, con confianza, tu propia fortaleza, en el asiento de una entrevista.'
    ],
    t: [T('Claude', 'main', 'El socio óptimo que expresa, en un lenguaje, una sensibilidad delicada', 'Si le cuentas a Claude, con sinceridad, tu fortaleza y tu experiencia, tu profundidad se convierte en un lenguaje convincente de una carta de presentación.', 'Soy del tipo OCEAN 10011. Entender el corazón de la gente es mi fortaleza; dime cómo convendría expresarlo, en una carta de presentación para un puesto de un investigador de UX.'),
        T('Wysa', 'specialist', 'El socio de cuidado de la emoción, que protege un corazón sensible', 'Cuando, en medio de la búsqueda de un empleo, llega un agotamiento emocional, si se lo sueltas a Wysa, recuperas con rapidez la energía psicológica y puedes volver a salir.', 'Llevo 6 meses buscando un empleo y, como sigo recibiendo un rechazo, se me ha caído demasiado la autoestima. Quiero recuperar el corazón. ¿Cómo lo hago?'),
        T('Notion AI', 'specialist', 'Una gestión sistemática de la búsqueda de un empleo, que no se deja sacudir por la emoción', 'También en un día en el que el ánimo no es bueno, si cumples, con Notion AI, una rutina fijada de la búsqueda de un empleo, puedes moverte con constancia, sin dejarte dominar por la emoción.', 'Ármame una página de Notion que analice un puesto y una empresa que encajen bien con mi fortaleza: la capacidad de empatía, la creatividad y la minuciosidad.')],
    syn: 'Tú, con una creatividad (O) y una amabilidad (A) altas, y sensible, usa la IA, a la vez, en dos vías: un respaldo emocional y una expresión creativa. La sensibilidad no es un punto débil: es una fortaleza que, en un puesto centrado en la gente, nadie puede reemplazar.',
    day: 'A las 8:00, con Wysa, el chequeo del ánimo de hoy. A las 9:00, con Claude, la redacción de una carta de presentación o la preparación de una entrevista. A las 13:00, el descanso del almuerzo y un paseo ligero. A las 14:00, con Notion AI, el orden del estado de avance de la búsqueda de un empleo de hoy. A las 20:00, con Claude, el análisis de una empresa a la que postular mañana. A las 22:00, con Wysa, el cierre del día.'
  });
  add('10100', 'Quien muestra al auténtico yo, el buscador de empleo creativo, extrovertido y sereno', 'ChatGPT', ['Gamma', 'Claude'], {
    i: 'Tú, creativo, extrovertido y emocionalmente estable, eres el tipo que, también en medio de la búsqueda de un empleo, mantiene una energía libre. Prefieres el modo de mostrar al auténtico yo, más que de empaquetarte a ti mismo para encajar en la cultura de una empresa, y precisamente eso, al contrario, se convierte en una fortaleza, en una startup que contrata a la medida de la cultura, o en un puesto creativo.',
    s: [
      'Con la creatividad y una energía extrovertida, dejas una impresión de forma natural, en una entrevista, y recibes una buena evaluación, en la evaluación de la adecuación a la cultura de una empresa.',
      'Gracias a un temperamento estable, incluso ante un rechazo, no te hieres de un modo grave y te mudas con rapidez a la oportunidad siguiente.',
      'Con la capacidad de mostrar un yo auténtico, brillas en una empresa que da más peso a una experiencia y a una pasión que a un currículum formal.'
    ],
    g: [
      'En una búsqueda de un empleo en la que se exige una forma y un sistema, como una contratación pública de una gran empresa, hace falta una estrategia que complemente la capacidad de planear.',
      'Si introduces, junto con la IA, un proceso minucioso de revisión que suba el grado de terminación de una carta de presentación, sube la tasa de paso del expediente.',
      'Si acumulas, más a fondo, una expertise del puesto, te conviertes en un postulante en el que tu creatividad brilla aún más.'
    ],
    t: [T('ChatGPT', 'main', 'El socio que convierte un estilo libre de la búsqueda de un empleo en una estrategia', 'Junto con ChatGPT, explora con libertad tu propia historia de la búsqueda de un empleo y encuentra la dirección más auténtica.', 'Soy del tipo OCEAN 10100. Me gusta más la libertad que una regla, y soy creativo; recomiéndame 3 puestos de una empresa que encajen con esta tendencia.'),
        T('Gamma', 'specialist', 'La herramienta que expresa, de forma visual, un portafolio creativo', 'Si armas con rapidez, con Gamma, un portafolio o un material de una entrevista de presentación, tu creatividad se transmite como un impacto visual.', 'Ármame, con Gamma, un portafolio para un puesto de planeación de un contenido, de una startup. De un modo que pueda llevar una propuesta de planeación de SNS que llevé y un resultado.'),
        T('Claude', 'specialist', 'El socio minucioso de revisión, que sube el grado de terminación de una carta de presentación', 'Si le envías a Claude un borrador de una carta de presentación que escribiste con libertad y le pides que revise el flujo lógico y la expresión, el grado de terminación sube de un modo considerable.', 'Este es el borrador de mi carta de presentación de Kakao. Revísalo, desde la perspectiva del modelo de talento de la empresa, “una colaboración y un desafío”, y mejóramelo en la parte débil.')],
    syn: 'Tú, con una creatividad (O) y una extraversión (E) altas, y estable, úsala en la dirección de expresar aún mejor, con la IA, tu propia autenticidad. Para ti, que das más peso a la esencia que a una forma, la IA es el editor que pule, con refinamiento, una idea cruda.',
    day: 'A las 9:00, con ChatGPT, exploras la dirección de una postulación de hoy. A las 11:00, escribes una carta de presentación, con libertad. A las 14:00, con Claude, una revisión del grado de terminación. A las 16:00, con Gamma, una actualización de un portafolio. A las 20:00, la entrega de una postulación. A las 22:00, exploras una empresa a la que postular mañana.'
  });
  add('10101', 'El alquimista de una tarea, el guerrero de 1 minuto antes de la fecha límite', 'ChatGPT', ['Perplexity AI', 'Beautiful.ai'], {
    i: 'El lunes de la semana pasada, tú, de las 9:00 de la mañana a las 18:00, entregaste una carta de presentación a 12 empresas. Cuando los compañeros decían “solo el análisis de una empresa me llevó 3 días”, tú ya estabas recibiendo el feedback de una entrevista. Tu capacidad de ejecución superpotente y tu positividad (E 92%, O 90%) son un arma oculta del mercado de la búsqueda de un empleo. Tú, que lees el mercado con rapidez y no dejas pasar una oportunidad, ya estás poniendo en práctica, de forma inconsciente, el acercamiento científico de “primero postulo, recibo un feedback y lo mejoro”. Pero, como la minuciosidad (C 35%) es baja, a veces cometes un error relámpago: te equivocas el nombre de una empresa, en un encabezado, o dejas pasar una fecha límite. A los ojos de un colega, tú te ves como “ese amigo de un temple de acero, que siempre sonríe”. En la práctica, la capacidad de, incluso al recibir un correo de un rechazo de un expediente, en 1 segundo, volver el corazón hacia “la oportunidad siguiente”, es el activo más valioso, en la selva de la búsqueda de un empleo. Tu capacidad de acción sin freno es una tendencia que, en un entorno de ventas, de marketing, de una startup, se va a convertir en una leyenda.',
    s: [
      'Una capacidad de ejecución como un relámpago: tú, que, en el instante en que lo piensas, lo pasas a una acción, cuando otros buscadores de empleo están dándole vueltas, ya estás recibiendo un feedback. La velocidad de reacción al mercado, de no dejar pasar una oportunidad, es el arma más grande del éxito de un empleo.',
      'Un temple positivo, como de acero: un rechazo de un expediente, un no de una entrevista, también, en solo 1 segundo, los conviertes en una oportunidad de aprendizaje. Esta fuerza de espíritu indomable es la capacidad de supervivencia que te deja vivo, hasta el final, en medio de cientos de rechazos del proceso de la búsqueda de un empleo.',
      'Un sentido natural del timing: captas, con sensibilidad, un anuncio de contratación del mercado y te mueves más rápido que los demás. Esto crea una ventaja estratégica, con la que puedes obtener una oportunidad de una entrevista mejor que la de un buscador de empleo competidor.'
    ],
    g: [
      'El refuerzo de la capacidad de una revisión de un detalle: hace falta el hábito de, antes de la entrega final, verificar, de forma obligatoria, con una lista de chequeo, un asunto básico, como el nombre de una empresa, el nombre de un puesto, una fecha límite, de una carta de presentación. Una postulación perfecta es la que crea una buena evaluación.',
      'Añadir una profundidad estratégica: una producción abundante también está bien, pero, a veces, hay que aprender que una sola carta de presentación realmente excepcional, de analizar a fondo una empresa, es más efectiva que tres cartas de presentación comunes.'
    ],
    t: [T('ChatGPT', 'main', 'El dios de una producción abundante: produce, a la velocidad de la luz, un borrador de una carta de presentación.', 'Es el centro de tu rutina del día. En el instante en que lees un anuncio de contratación, le introduces a ChatGPT el nombre de una empresa, un puesto, una palabra clave central, y, en 30 segundos, recibes un borrador de una carta de presentación. Luego, en 5 minutos, le añades tu experiencia y lo entregas. Por ejemplo, si introduces “el anuncio de contratación del equipo de marketing de Samsung enfatizó ‘una experiencia de una campaña global’. Ármame, en 3 versiones de un borrador de una carta de presentación, un proyecto de equipo de un festival universitario mío, encajándolo en este marco. Cada una, con un tono distinto”, puedes recibir, de inmediato, 3 versiones. Con este modo, puedes procesar, sin problema, 50 postulaciones al mes.', 'Contratación pública del equipo de marketing de (sa) OO. Anuncio: “una experiencia de marketing digital de 3 años o más, una capacidad de análisis de un resultado de una campaña de una red social”. Mi trayectoria: “en un club universitario, llevé Instagram 1 año y subí 5.000 seguidores”. Con esto de base, escríbeme, cada una, en 200 caracteres, la pregunta 1 de una carta de presentación (una experiencia) y la pregunta 2 (una capacidad). En un tono apasionado, pero profesional.'),
        T('Perplexity AI', 'specialist', 'Reúne, en 10 segundos, una información de una empresa, con un dato más reciente.', 'Antes de escribir una carta de presentación, lo que te hace falta es la información más reciente de esa empresa. Perplexity es una IA basada en una búsqueda y te lo cuenta, combinando, en tiempo real, “la dirección de una contratación de Samsung de 2024 + un mensaje del CEO + una noticia reciente de un negocio”. Si tú preguntas “resúmeme, en 50 caracteres, la noticia principal de los 3 meses recientes de la empresa OO y la línea de una contratación”, puedes recibir una información más apretada que un artículo de un periódico. Si se la pegas a ChatGPT, la confiabilidad de una carta de presentación sube de golpe.', 'Contratación pública de 2024 del equipo de logística de (sa) Coupang. ¿Me puedes ordenar la noticia de Coupang de los 3 meses recientes, el mensaje más reciente de su fundador, Kim Beom-seok (Bom Kim), y la dirección de un negocio de este año? En un nivel que yo pueda usar en una carta de presentación.'),
        T('Beautiful.ai', 'specialist', 'En 3 segundos, armas, como un profesional, un material de una presentación.', 'Cuando vas a una entrevista, llega el momento en que tienes que explicar un portafolio o un resultado de un proyecto. Beautiful.ai, si le introduces un texto o una imagen tuya, te arma de forma automática una diapositiva de un nivel de un experto. Por ejemplo, si introduces, en Beautiful.ai, el resultado de una campaña de marketing que creaste en la época de la universidad, en 20 segundos sale una presentación de un diseño que deja admirado a un entrevistador. Tu temible capacidad de ejecución, al encontrarse con Beautiful.ai, se transforma en “un resultado con estilo”.', 'Un proyecto del equipo de comercio electrónico de un festival universitario mío: una plataforma en línea de compraventa de segunda mano, del barrio universitario; 3 meses de duración; 4 miembros del equipo; resultado: en el primer mes, 200 personas de entrada, un volumen de transacción de 5 millones de wones. Ármame esto, como una presentación de una entrevista. En un tono contemporáneo y limpio, unas 5 diapositivas en total.')],
    syn: 'Tu competitividad inigualable es “la armonía de una velocidad + una profundidad”. Armas con rapidez una carta de presentación, con ChatGPT, pero le añades una información más reciente, con Perplexity, y, después de una entrevista, preparas de inmediato, con Beautiful.ai, un material de un seguimiento. Se arma la fórmula de 50 postulaciones al mes → 10 entrevistas al mes → 3 aprobaciones finales al mes. Cuando otro buscador de empleo se prepara “una empresa, de forma perfecta”, tú te preparas “50 empresas, con un 80”, y, de ellas, alguien te elige, de forma obligatoria. Esta es tu propia fórmula estadística de una victoria, fuerte ante un rechazo.',
    day: 'Tu día empieza a las 8:00 de la mañana, en un café. Los primeros 10 minutos, checas un anuncio de contratación con una fecha límite de ese día. Abres Perplexity y, en 3 minutos, buscas “la noticia más reciente de 5 empresas con una fecha límite de hoy”. Copias esa información, se la introduces a ChatGPT y le pides “ármame un borrador de una carta de presentación, adecuado a cada una de estas 5 empresas”. 5 minutos después, en tu pantalla ya flotan 5 borradores. De las 9:00 de la mañana a las 13:00, lees estos borradores y les añades tu experiencia. 10 minutos por cada carta de presentación, 50 minutos en total. De las 13:00 a las 14:00, mientras almuerzas, recorres la lista de chequeo, antes de una entrega (el nombre de una empresa, el nombre de un puesto, una fecha límite: estos 3, de forma obligatoria). A las 14:00, 5 postulaciones terminadas. En este punto, otros buscadores de empleo siguen dándole vueltas a la primera carta de presentación. De las 14:00 a las 17:00, te preparas, acerca de una empresa, de las que postulaste la semana pasada, a la que se le fijó una cita de una entrevista. Abres Beautiful.ai y conviertes tu portafolio en una presentación. La idea de una startup que creaste, un proyecto de marketing que cursaste, una experiencia de una pasantía, en 5 minutos, se transforman en un material que deja admirado a un entrevistador. De las 17:00 a las 18:00, lees LinkedIn o el blog de una empresa y ordenas una pregunta esperada de una entrevista. Después de “salir del trabajo”, de las 19:00 a las 20:00, es tu fortaleza. Cuando otros buscadores de empleo, agotados, se derrumban, tú, con holgura, escaneas de antemano 5 anuncios a los que postular mañana. Le introduces a ChatGPT “¿me puedes ordenar el requisito central de los anuncios con una fecha límite de mañana?” y armas una estrategia, para la mañana de mañana. El núcleo de esta rutina es que tu “capacidad de ejecución de una velocidad extrema” y “la capacidad de automatización” de una herramienta de IA encajan a la perfección. Tú nunca te estás moviendo “con ahínco”: te estás moviendo “con inteligencia”.'
  });
  add('10110', 'Quien reúne a la gente de forma natural, el buscador de empleo creativo, extrovertido y cálido', 'ChatGPT', ['Notion AI', 'Otter.ai'], {
    i: 'Tú, creativo, extrovertido, cálido y estable, eres, incluso entre los buscadores de empleo, el tipo de la energía más brillante. Donde sea, reúnes a la gente de forma natural y, en una sesión informativa de una empresa o en un grupo de estudio de la búsqueda de un empleo, desempeñas un papel proactivo. La capacidad de planear es débil, pero tienes mucha suerte con la gente, así que sueles obtener, de forma natural, una información y una oportunidad.',
    s: [
      'Con una extraversión y una amabilidad altas, brillas en una comunidad de la búsqueda de un empleo o en un networking, y obtienes, de forma natural, una información útil.',
      'Con una ocurrencia creativa, tienes la capacidad de diferenciación de crear una historia original de una carta de presentación y un portafolio.',
      'Con un temperamento estable, incluso ante un fracaso, en medio de la búsqueda de un empleo, te sacudes el polvo enseguida y muestras una resiliencia positiva de volver a intentarlo.'
    ],
    g: [
      'La energía y una relación son abundantes, pero, si te mueves sin un plan sistemático, puedes dejar pasar una fecha límite. Usa, de forma obligatoria, una herramienta de gestión de una agenda.',
      'Hace falta el esfuerzo de añadir profundidad, a la preparación de una carta de presentación o de una entrevista. Más que una relación amplia, la comprensión profunda de un puesto es la que crea una aprobación.',
      'Más que postular, de forma dispersa, a varias empresas, es efectiva una estrategia de estrechar una empresa prioritaria y de atacar, con concentración.'
    ],
    t: [T('ChatGPT', 'main', 'El socio que despliega, con rapidez, una historia creativa de una carta de presentación', 'Con un brainstorming, junto con ChatGPT, despliega con rapidez una idea de una carta de presentación y, de ellas, elige la historia más atractiva.', 'Soy un buscador de empleo del tipo OCEAN 10110. Conecta una experiencia de presidente de un club, un premio de un concurso, una experiencia de un trabajo de media jornada, y ármame una historia de postulación a un puesto de ventas.'),
        T('Notion AI', 'specialist', 'El hub de gestión que convierte una energía desbordante en una búsqueda sistemática de un empleo', 'Si ordenas, con Notion AI, el estado, por empresa a la que postulaste, y la acción siguiente, aunque prepares a la vez varias empresas, no te confundes.', 'Ahora estoy postulando, a la vez, a 5 empresas. Ármame una plantilla de Notion que gestione, por empresa, el estado de la entrega de un expediente, una cita de una entrevista, lo que hay que preparar.'),
        T('Otter.ai', 'specialist', 'Registra, de forma automática, el contenido de una sesión informativa de una empresa y de un grupo de estudio', 'Si transcribes de forma automática, con Otter.ai, el contenido de una sesión informativa de una empresa o de un grupo de estudio de la búsqueda de un empleo, tu fortaleza de reunir una información queda como un registro.', 'Hoy registré, con Otter.ai, el contenido de una sesión informativa de Hyundai Motor. Sácame, de este contenido, 5 puntos que yo pueda aprovechar en una entrevista.')],
    syn: 'Tú, con una creatividad (O), una extraversión (E) y una amabilidad (A) altas, y estable, la estrategia óptima es maximizar el activo de una relación, de la búsqueda de un empleo, y, a la vez, complementar, con la IA, la profundidad y un sistema. Si refinas, con la IA, una información obtenida de la gente, se completa un sistema potente de la búsqueda de un empleo.',
    day: 'A las 8:00, con Notion AI, el chequeo del estado de una postulación de hoy. A las 10:00, con ChatGPT, el despliegue de una idea de una carta de presentación. A las 13:00, la participación en una sesión informativa de una empresa o en un grupo de estudio (un registro con Otter.ai). A las 17:00, con ChatGPT, la aplicación, a una carta de presentación, de una información reunida hoy. A las 21:00, la fijación del objetivo de una postulación de mañana.'
  });
  add('10111', 'Quien, en una montaña rusa de la energía, vuelve a levantarse: el buscador de empleo creativo, extrovertido y sensible', 'ChatGPT', ['Wysa', 'Notion AI'], {
    i: 'Tú, creativo, extrovertido y cálido, pero de una inquietud alta, en medio de la búsqueda de un empleo experimentas una montaña rusa, en la que la energía se desborda y, de pronto, te derrumbas. Tienes el encanto de atraer a la gente de forma natural y, en una entrevista, irradias bien un encanto humano, pero un no te golpea en exceso. El núcleo es la gestión de la emoción y el mantenimiento sostenido de una motivación.',
    s: [
      'Con una ocurrencia creativa y una sociabilidad excepcional, tienes una presencia natural, que deja una impresión, en un evento de un networking o en una sesión informativa de una empresa.',
      'Con una amabilidad alta, en una entrevista formas con rapidez un rapport con un entrevistador y das una confianza humana.',
      'Como no le temes a una idea nueva, a través de un concurso o de una experiencia de un proyecto, creas un currículum diferenciado.'
    ],
    g: [
      'Cuando sube la inquietud, si dejas armada una rutina de soltársela a la IA o a un amigo y de recuperarte con rapidez, nace una resistencia de la búsqueda de un empleo.',
      'Más que dispersar la energía, en direcciones diversas, hace falta una estrategia de estrechar una empresa y un puesto objetivo.',
      'Si corres, sin un plan, solo con una pasión, puedes dejar pasar una fecha límite de una postulación o un expediente importante. Hace falta una gestión sistemática de una agenda.'
    ],
    t: [T('ChatGPT', 'main', 'El socio de un desarrollo rápido de una idea y de la puesta en una estrategia de una carta de presentación', 'Derrámale a ChatGPT la idea y la experiencia que tienes en la cabeza y ordénelas, con rapidez, como una historia de una carta de presentación.', 'Soy un buscador de empleo del tipo OCEAN 10111. Estoy postulando a un puesto de planeación de una startup; escríbeme una apertura de una carta de presentación en la que se revele mi fortaleza, “una creatividad y una capacidad de empatía”.'),
        T('Wysa', 'specialist', 'El socio de una recuperación de la emoción, que disuelve con rapidez una inquietud', 'Cuando llega un no, o una duda de ti mismo, si se lo sueltas a Wysa, la emoción se ordena con rapidez y nace la energía de volver a salir.', 'Hoy me rechazaron, en una segunda entrevista. El corazón me duele demasiado, pero quiero volver a levantarme. Ayúdame a ordenar, ahora, mi emoción y a seguir adelante.'),
        T('Notion AI', 'specialist', 'La herramienta de gestión que asienta una energía desbordante, como una búsqueda de un empleo con un sistema', 'Si sistematizas, con Notion AI, una energía de la búsqueda de un empleo que fluye en direcciones diversas, puedes moverte de forma estratégica, sin dejar pasar lo importante.', 'Estoy llevando, a la vez, la preparación de un concurso, una carta de presentación de una gran empresa, una entrevista de una startup. Ármame un tablero de Notion de la búsqueda de un empleo, con el que yo pueda gestionar esto de un vistazo.')],
    syn: 'Tú, con una creatividad (O), una extraversión (E) y una amabilidad (A) altas, eres más efectivo cuando usas la IA con comodidad, como si conversaras con una persona. Si estabilizas la emoción, con Wysa, y desarrollas con rapidez una idea, con ChatGPT, la inquietud se convierte en una energía creativa.',
    day: 'A las 8:00, con Wysa, el chequeo del ánimo de la mañana. A las 9:00, con ChatGPT, la puesta en una estrategia de una carta de presentación de una empresa a la que postular hoy. A las 11:00, la redacción y la entrega de un expediente. A las 14:00, con Notion AI, el chequeo de una agenda. A las 17:00, un networking o una reunión de una información. A las 21:00, con Wysa, el orden de la emoción del día.'
  });
  add('11000', 'Quien se prepara a fondo, solo: el buscador de empleo creativo, diligente y callado', 'Claude', ['Perplexity', 'Notion AI'], {
    i: 'Tú, un buscador de empleo creativo y diligente, pero callado, eres el tipo que se prepara del modo de ahondar a fondo, por tu cuenta. Reescribes, solo, decenas de veces, una carta de presentación, y también el análisis de una empresa lo haces a fondo, pero, en realidad, eres torpe en un networking o en el intercambio de una información. Hace falta una estrategia de revelar, hacia afuera, una capacidad profunda de preparación.',
    s: [
      'El grado de terminación de una carta de presentación y de un portafolio, en los que se combinan la creatividad y la diligencia, es excepcional, así que la tasa de aprobación de un expediente es alta.',
      'Con una investigación profunda de una empresa y de un puesto, en una entrevista das una respuesta concreta y aguda.',
      'Como estás emocionalmente estable, también en un proceso largo de la búsqueda de un empleo, no pierdes tu propio ritmo.'
    ],
    g: [
      'Si te preparas solo, puedes dejar pasar una tendencia más reciente de la industria o la estrategia de otro postulante. Prueba subir el aprovechamiento de un chat abierto o de una comunidad.',
      'Hace falta el entrenamiento de expresarte, con confianza, en una entrevista. Sube, de forma consciente, la práctica de hablar.',
      'Si acumulas, como un currículum, una experiencia de un trabajo de equipo o de una colaboración, después de pasar un expediente, en una entrevista se convierte aún más en una fortaleza.'
    ],
    t: [T('Claude', 'main', 'El socio óptimo que expresa, en un lenguaje, una preparación profunda', 'Explícale a Claude el contenido que preparaste y recibe un feedback, desde la posición de un entrevistador, de cómo se va a oír. Te ayuda a que tu profundidad se transmita también en una palabra.', 'Soy un buscador de empleo del tipo OCEAN 11000. Tengo que escribir la pregunta “una experiencia de una colaboración”, de una carta de presentación de un puesto de desarrollo, de una empresa de TI. Dime el modo de reinterpretar, desde la perspectiva de una colaboración, una experiencia de haber estudiado solo.'),
        T('Perplexity', 'specialist', 'El socio de una investigación a fondo de una empresa y de la industria', 'Si captas con rapidez, con Perplexity, una tendencia reciente de una empresa a la que postulas, una estrategia de un negocio, un análisis de un competidor, el tiempo de la preparación de una entrevista se reduce de un modo considerable.', 'Estoy preparando una entrevista de un puesto de un semiconductor, de Samsung Electronics. Ordéname, para que lo pueda aprovechar en una respuesta de una entrevista, el asunto reciente de una memoria HBM y la situación de la competencia.'),
        T('Notion AI', 'specialist', 'Gestiona, de forma sistemática, una preparación a fondo de la búsqueda de un empleo', 'Si ordenas, con Notion AI, una nota de un análisis de una empresa, la gestión de una versión de una carta de presentación, un Q&A de una entrevista, tu preparación diligente se acumula de forma sistemática.', 'Ármame el marco de una nota de un análisis de una empresa, para una postulación a un puesto de planeación de UX, de Kakao. Incluyendo las secciones del estado de un negocio, del modelo de talento, de una pregunta esperada, de un borrador de mi respuesta.')],
    syn: 'Para ti, introvertido, de una creatividad (O) y una diligencia (C) altas, la IA es la herramienta que sube, de un modo dramático, la calidad de una búsqueda de un empleo que preparas solo. Si aprovechas, de forma activa, una conversación con la IA, como una práctica de hablar, de una entrevista, se convierte en el atajo de superar una introversión.',
    day: 'A las 8:00, con Perplexity, el análisis de una empresa que vas a investigar hoy. A las 10:00, con Claude, el pulido de una carta de presentación o la práctica de un Q&A de una entrevista. A las 14:00, con Notion AI, el orden del contenido de una preparación de hoy. A las 17:00, la exploración y la postulación a una empresa nueva. A las 21:00, con Claude, el feedback de una respuesta que practicaste hoy. A las 22:30, a dormir.'
  });
  add('11001', 'El que, en silencio, suelta hechos sin filtro, el juez de Everytime', 'Perplexity AI', ['Elicit', 'ChatGPT + Notion'], {
    i: 'Tú, que estabas preparando el material de una presentación de un trabajo en equipo, en las afirmaciones de los miembros del grupo, exiges de inmediato una fuente. Una sola pregunta, “¿eso es cierto?”, suele retrasar 30 minutos a toda la reunión. Pero la tarea que entregas es, siempre, perfecta. Desde la cita de un paper hasta una estadística, no hay un hueco. Tu fortaleza brilla, como el oro, en el ámbito académico y en el campo de un puesto. Tú, que, a través de un razonamiento profundo, atraviesas la esencia de un problema y te armas de un criterio estricto, en una organización te conviertes en “el verificador en el que se puede confiar”. Solo que los colegas, aunque quisieran acercarse un poco más a ti, sienten una distancia, por “la holgura” de una relación humana. Lo que te hace falta es una habilidad de comunicación, de envolver tu propia frialdad, con el empaque de “una consideración”. La combinación con la IA te va a hacer evolucionar, de “una máquina de un fact-checking”, a “un experto convincente”.',
    s: [
      'Una capacidad de una crítica lógica: puedes captar de inmediato un hueco de una afirmación y presentar una refutación basada en un fundamento, así que, en una tarea académica y en una entrevista de un empleo, recibes una evaluación alta, con una respuesta diferenciada.',
      'Una verificación a fondo de una información: con el hábito de no aceptar nunca una información de un “se dice que”, y de confirmar una fuente, subes al extremo la confiabilidad de un proyecto de equipo y de un informe, y cortas un error de raíz.',
      'Una capacidad de ejecución perfecta: gracias a un perfeccionismo que no tolera ni un error del 0,1%, todo resultado que entregas mantiene la calidad más alta, y esto se conecta, de forma directa, con una calificación y con un portafolio de la búsqueda de un empleo.'
    ],
    g: [
      'Una conciencia excesiva de una crítica: el hábito de dudar y de verificarlo todo, a veces, obstaculiza “la velocidad” de una colaboración y, al ser reconocido, por un colega, como “alguien difícil”, puedes quedar al margen, en un proyecto de equipo.',
      'Una falta de una empatía emocional: tu modo de comunicación, de perseguir solo una lógica, le hace sentir, a alguien que pide un consejo, que “eres frío”, y se convierte en una barrera de la formación de una relación humana.'
    ],
    t: [T('Perplexity AI', 'main', 'Un fact-checking, en tiempo real: toda fuente, explícita', 'Es la IA que satisface, a la perfección, tu pulcritud intelectual. Cuando verificas de inmediato una afirmación que salió en un trabajo en equipo, o el contenido principal de un paper, Perplexity, junto con una búsqueda en la web, en tiempo real, te presenta una fuente precisa. Por ejemplo, si un miembro del grupo afirma “una tecnología reciente de IA subió, hasta un 95%, la precisión de un diagnóstico médico”, si preguntas “búscame, junto con una fuente, un caso de haber alcanzado un 95% de una precisión de un diagnóstico médico, de IA, reciente”, puedes confirmar incluso un paper concreto de una investigación y la editorial. Al escribir una tesis de un grado, puedes verificar, en tiempo real, una estadística o una afirmación principal, así que completas un informe perfecto, sin un error.', 'Tema de un paper: “el empeoramiento de la salud mental de un estudiante universitario de Corea, después de una pandemia”. En relación con este tema, búscame, junto con una fuente, 5 o más estadísticas o resultados de una investigación, confiables, publicados a partir de 2023. Con prioridad, un material publicado por un organismo del gobierno o por una revista académica.'),
        T('Elicit', 'specialist', 'El orden automático de un paper: un dato académico, de un vistazo', 'Es una IA especializada en la búsqueda y en el resumen de un paper académico. Cuando tú escribes un informe, sobre un tema, Elicit busca, de una vez, decenas de papers de ese tema y te ordena, en un formato de una tabla, el contenido central de cada uno. Por ejemplo, cuando investigas “un factor de una decisión de una carrera, de un estudiante universitario de Corea”, si le dices a Elicit “busca un paper relacionado con un factor de una decisión de una carrera, de un estudiante universitario de Corea”, puedes comparar, de un vistazo, el autor, el año de publicación, el resultado principal. Es posible un orden sistemático de un dato, suficiente para satisfacer tu perfeccionismo.', 'Tema de una búsqueda: “AI in recruitment” / rango de un tiempo: a partir de 2022 / información que deseo: el título de un paper, el autor, el año de publicación, el resultado principal (el grado de una mejora de la eficiencia de una contratación), el tamaño de una muestra.'),
        T('ChatGPT + Notion', 'specialist', 'Convierte una idea, en una estructura sistemática', 'Lo usas cuando tienes que “transmitir”, de forma convincente, un contenido que ordenaste de forma lógica. Si le introduces a ChatGPT tu afirmación central y un fundamento, te lo recompone, como una historia que un colega o un profesor puede entender con facilidad. Por ejemplo, en una presentación de un equipo, en lugar de una explicación fría de “este dato demuestra OO”, lo puedes convertir, en una expresión convincente, de “el sentido que muestra este dato es…”. Se vuelve posible una comunicación que lleva, a la vez, una lógica y una emoción.', 'Lo siguiente es el primer párrafo de mi carta de presentación. ¿Me lo puedes volver a escribir, de un modo que mantenga la lógica y, a la vez, llegue más cálido, al corazón? [pega el primer párrafo de tu carta de presentación]')],
    syn: 'Tu “capacidad de una verificación de un hecho” + “una fuente explícita” de Perplexity es una combinación que, en el ámbito académico, brilla como el oro. Más aún, si, con Elicit, haces una revisión sistemática de un paper y, con ChatGPT, lo expresas de forma convincente, te puedes transformar en “un talento lógico y, a la vez, con una capacidad de empatía”. En especial, en la etapa de la búsqueda de un empleo, puedes dar una respuesta verificada a la perfección, a una pregunta de una entrevista de tipo essay, así que te diferencias, de un modo aplastante, de otro postulante. Además, en un proyecto de equipo, se consolida tu estatus, como “el encargado de un análisis, en el que se puede confiar”, así que, tanto en un examen de una especialidad universitaria como, después de un empleo, en una evaluación de una capacidad de un puesto, recibes una calificación alta.',
    day: 'Tu día empieza con “una verificación”. A las 8:00 de la mañana, en cuanto te sientas en tu asiento de la biblioteca, enciendes Perplexity, en el smartphone, y verificas 3 afirmaciones del profesor, que oíste ayer, en una clase. Confirmas, una por una, “¿ese fundamento es cierto, de verdad?”, y guardas, como una captura de pantalla, una fuente en la que se puede confiar. A las 10:00 de la mañana, antes de entrar a la sala de una reunión de un trabajo en equipo, le pides a ChatGPT, a la ligera, un resumen del material que compartieron los miembros del grupo, y captas el núcleo. En medio de una reunión, en lugar de tu pregunta “¿esto es cierto?”, pruebas cambiarla, a un feedback productivo, de “confirmé el fundamento de esta afirmación, y…”. En el horario del almuerzo, con una fecha límite, por la tarde, de un informe de 3 horas, enciendes Elicit, buscas y ordenas, de forma automática, 20 papers relacionados, y completas la lista de un material de referencia. Comparando solo la parte de la conclusión de los papers, seleccionas 5 casos más fuertes, que respalden tu afirmación. A las 15:00, le pides a ChatGPT que revise la estructura lógica del borrador de un informe que has ido escribiendo. “¿Este flujo es válido, de forma lógica? ¿Desde la posición de un lector, es convincente?” A las 17:00, completas el informe final y, una vez más, con Perplexity, reconfirmas una estadística principal y una fuente. Justo antes de la entrega, a las 18:00, tu informe perfecto ya está entregado, 2 horas antes que el de los miembros del grupo. A las 20:00, después de “salir del trabajo”, de cara a una entrevista de un empleo, de este sábado, le introduces a ChatGPT 5 preguntas esperadas y le pides que vuelva a escribir la respuesta que tú redactaste, de un modo “preciso y, a la vez, cálido”. “Si respondo así, ¿cómo me va a pensar un entrevistador?” Es el instante en el que tu frialdad, por fin, se convierte en “una sensación de confianza”.'
  });
  add('11010', 'La muñeca de las preocupaciones, rebosante de sensibilidad: el buscador de empleo romántico', 'Claude', ['Sleep Cycle', 'Wysa'], {
    i: 'Tú, que llevas dos horas detenido, delante de la pregunta 3 de una carta de presentación: de hecho, no es que no tengas contenido que escribir. Es que hay tanto, que no sabes por dónde empezar. Como tu sensibilidad es abundante, le das un sentido profundo a cada experiencia, y el ánimo de querer expresarlo, en una frase perfecta, es, al contrario, lo que te está bloqueando. Tu temple de cristal, que, con un solo correo de un rechazo, pierde entero el día de ese día: de hecho, esa sensibilidad es, precisamente, el talento que te va a hacer brillar, en un oficio creativo. Más que una postulación perfecta, una postulación a tu modo se clava con más fuerza. El trabajo de traducir tu interior profundo, a un lenguaje que el mundo pueda leer, lo hace, junto contigo, la IA.',
    s: [
      'Una apertura y una amabilidad altas se combinan, y la capacidad de interiorizar a fondo una experiencia diversa y de fundirla, en un ensayo de un empleo o en un portafolio, como una historia conmovedora: el postulante del que un entrevistador dice “a esta persona la recuerdo” eres, precisamente, tú.',
      'Un plan de la preparación de un empleo, armado con una diligencia alta, es más concreto y a más largo plazo que el de otro buscador de empleo, y una capacidad de autocontrol, de gestionar de forma sistemática, desde la preparación de una certificación hasta el refuerzo de una capacidad de un puesto, brilla, de forma obligatoria, en una guerra larga.',
      'Una sensibilidad delicada se expresa, en una entrevista de un puesto, como una “inteligencia de una empatía”, de leer, de forma inmediata, un cambio de una expresión y una reacción de un entrevistador, y de ajustar, con flexibilidad, la dirección de una respuesta, así que muestras una fortaleza, en una comunicación no verbal.'
    ],
    g: [
      'Por un neuroticismo alto, un aviso de un rechazo o un feedback negativo te influyen, durante un tiempo excesivo, y se te vuelve lenta la velocidad de pasar a la etapa siguiente: hace falta armar, con una herramienta de IA, una rutina de una recuperación de la emoción, y la práctica de girar, con rapidez, la mirada, hacia “la empresa siguiente”.',
      'Hay una tendencia, por una extraversión baja, de rehuir un asiento de un networking o la participación en una comunidad de la industria; si consideras cuánto importan, en un empleo, una información y una conexión, ayuda una exposición gradual, de empezar, desde una reunión pequeña, en línea.'
    ],
    t: [T('Claude', 'main', 'De una sensibilidad, a una lógica: de tu historia, a una frase convincente', 'Cuando escribas una carta de presentación, suéltale a Claude la experiencia, cruda, tal cual. Si la introduces, como si le contaras “el instante más duro de la época de la universidad y cómo lo aguanté entonces”, Claude convierte esa emoción y esa historia de un crecimiento, en una frase lógica que la conecta con una capacidad de un puesto. Lo mismo, en la preparación de una entrevista. Si le pides “analízame 10 preguntas que parece que van a salir, en una entrevista de esta empresa, y una pregunta que a mí se me hace difícil de responder”, puedes complementar, de antemano, tu punto débil.', 'Este es el borrador de la pregunta 3 de mi carta de presentación: [pega el borrador]. Mantén la expresión de una emoción y, a la vez, púlelo, con un lenguaje más concreto, de una relación con un puesto, y centrado en un resultado. En 300 caracteres o menos.'),
        T('Sleep Cycle', 'specialist', 'También en medio del estrés de la búsqueda de un empleo, mantén la condición, con un sueño profundo', 'La influencia que, en medio de la preparación de un empleo, un sueño irregular ejerce, en la concentración y en la regulación de una emoción, es más grande de lo que se piensa. Sleep Cycle analiza un patrón de un sueño y te ayuda a despertar, descansado, haciendo sonar una alarma, en la etapa más superficial de un sueño. En un día en el que, por el estrés, se te hace difícil dormirte, aprovecha una música de inducción de un sueño, de la app, y, al confirmar, al día siguiente, la puntuación de la condición, capta la franja óptima de un tiempo, para la redacción de una carta de presentación o para la preparación de una entrevista.', 'Cuando, la víspera de una entrevista, por la tensión, se te hace difícil dormirte: en la app Sleep Cycle, fija una rutina de una inducción de un sueño → una alarma de despertar → un chequeo de la condición de la mañana.'),
        T('Wysa', 'specialist', 'La gestión del temple, ante un rechazo: un respaldo emocional, de IA', 'Cuando, en medio de la preparación de un empleo, se te hace difícil cargar solo el estrés, que se repite, de un rechazo y de una espera, Wysa te escucha, las 24 horas. Cuando quieres soltar una emoción, pero no quieres cargarle un peso a alguien de alrededor, cuéntale a Wysa la emoción de hoy. Con un acercamiento basado en una TCC (una terapia cognitivo-conductual), te ayuda a practicar recomponer un pensamiento negativo. Si dices “hoy recibí el tercer aviso de un rechazo”, te reconoce la emoción y te propone un método concreto, con el que puedes avanzar hacia la etapa siguiente.', 'En la app Wysa: una sesión de un orden de la emoción, que empieza con “hoy, otra vez, me rechazaron, en la etapa de un expediente. Ya no sé qué tengo que hacer”.')],
    syn: 'Tu tendencia OCEAN (una sensibilidad profunda + una diligencia alta + una capacidad cálida de empatía) es, en el proceso de la búsqueda de un empleo, el arma más potente, de diferenciarte, como “un postulante auténtico”. Este sistema triangular, de armar, con Claude, tu historia, como una frase lógica → mantener, con Sleep Cycle, una condición física → asegurar, con Wysa, una estabilidad emocional, te arma una rutina sostenible, que hace falta para terminar la maratón larga de la búsqueda de un empleo. Lo que te hace falta, a ti, de una sensibilidad abundante, no es más currículum: es el modo de transmitir, de forma convincente, una historia a tu modo.',
    day: 'A las 8:00 de la mañana, te despiertas, descansado, con una alarma de Sleep Cycle, y confirmas la puntuación de la condición. Un día bueno, empiezas, de inmediato, un trabajo de una carta de presentación, con Claude; un día de una condición baja, lo empiezas, con una investigación ligera de una empresa. Por la mañana, le pegas a Claude el anuncio de contratación de una empresa a la que vas a postular hoy y extraes una palabra clave, a medida, de una carta de presentación. Después del almuerzo, con Wysa, haces un check-in de la emoción de hoy y te tomas un rato intermedio de un reset, para que no se te acumule el estrés. Por la tarde, con Claude, repites 3 veces un Q&A de una entrevista simulada y pules una respuesta; por la noche, ordenas las empresas a las que postulaste hoy y planeas la agenda de mañana. Antes de dormirte, enciendes la función de una inducción de un sueño, de Sleep Cycle, y cierras, reconociendo el esfuerzo de este día.'
  });
  add('11011', 'El que, en Everytime, suelta hechos sin filtro, el outsider racional', 'Perplexity AI', ['GitHub Copilot', 'Notion AI'], {
    i: 'En el horario de un seminario del laboratorio, cuando el profesor se trabó, en la interpretación de un dato, tú, en silencio, levantas la mano y apuntas al núcleo, con precisión. Hablas poco, pero esa sola palabra cambia la dirección de un paper. Tú, cuando te sumerges en una investigación profunda y en un aprendizaje, estás en tu mejor forma, pero, en cuanto te subes al escenario de una sesión informativa de un empleo, se te cierra la garganta. Los colegas piensan, de ti, “siendo tan inteligente, ¿por qué no presentas?”, y el profesor, al ver, con satisfacción, tu GitHub, escribe una carta de recomendación, para una empresa. El perfeccionismo y una prudencia son tu arma, pero, a veces, eso mismo te agarra el tobillo de un desarrollo. Aun así, las empresas que buscan a un experto sólido, como tú, ya están haciendo fila. El problema es que ellas saben cuánto te cuesta conversar, con esas empresas.',
    s: [
      'Con una capacidad profunda de una investigación académica y de un análisis de una literatura, sacas un insight, de un nivel que un colega no puede, y tienes una capacidad excepcional de un aprendizaje, de interiorizar, en tu propio lenguaje, un concepto complejo.',
      'Con una capacidad excepcional de ejecución, por una diligencia alta, y el mantenimiento de una calidad consistente de un resultado, gestionas con precisión una fecha límite de un proyecto y una agenda académica, y te reconocen como un miembro del equipo, en el que se puede confiar.',
      'Como la estabilidad emocional es alta, incluso ante una frustración de un proceso académico, como el rechazo de un paper, un bug de un código, el fracaso de un experimento, no te dejas sacudir y muestras la imagen de un investigador, de un temple, que se concentra en la resolución de un problema.'
    ],
    g: [
      'Por un punto débil de un networking y de una comunicación, no das a conocer, de forma adecuada, tu propia capacidad y un resultado, así que hay el riesgo, en un empleo, de una subevaluación, y el límite de no revelar una presencia, ante un encargado de una contratación.',
      'Una incomodidad, en una presentación pública y en una relación interpersonal improvisada, te hace dudar, ante una oportunidad de un liderazgo o ante un papel de un mentoring, y se puede retrasar, al inicio de una trayectoria, la obtención de una visibilidad y de una diversidad de una experiencia.'
    ],
    t: [T('Perplexity AI', 'main', 'Ante una pregunta académica, un argumento preciso: una búsqueda a la velocidad de la luz', 'Cuando, al leer un paper, te trabas, con “este concepto, ¿cuál es, de verdad, la investigación más reciente?”, si le preguntas a Perplexity, te ordena, junto con una cita, un paper más reciente y un material especializado. Una respuesta limpia, sin una charla, encaja justo con tu estilo. Por ejemplo, si preguntas “¿cómo ha evolucionado, recientemente, un modelo transformer? ¿Me lo puedes explicar, con el criterio de una revista académica, un límite principal y una dirección de una mejora?”, te ordena, de un modo fácil de entender, un paper y un concepto relacionados. A través de esto, tú aseguras una comprensión profunda, no un aprendizaje superficial, y, en una presentación o en una tarea, puedes presentar un fundamento, de un nivel que te distingue, con claridad, de otro estudiante.', '¿Me puedes ordenar, de forma comparada, los acercamientos académicos más recientes, a un método de resolver el problema de una alucinación (hallucination) de una IA generativa, a partir de 2024? Incluyendo la ventaja y la desventaja de cada método, y un caso de una aplicación práctica.'),
        T('GitHub Copilot', 'specialist', 'El dedo que te reduce un 80% la repetición de la redacción de un código', 'Cuando haces un análisis de un dato o una tarea de un código, si, en el tiempo de buscar, cada vez, una gramática y un ejemplo, usas Copilot, en el instante en que escribes la intención, como un comentario, el código se completa. Ejemplo: si, en un comentario, escribes “# leer un archivo csv, con pandas, y rellenar un valor null, con la mediana”, Copilot te propone un código preciso. El césped de tu GitHub se pone más verde, y nace la holgura de, en una sola tarea, implementar más funciones. Como la IA te resuelve un desperdicio de un tiempo de un código, por un perfeccionismo, tú te puedes concentrar, solo, en el diseño de una lógica y en la optimización de un algoritmo.', '# armar una función que lea, con un procesamiento en paralelo, varios archivos csv, los fusione, de forma eficiente, en la memoria, y guarde un resumen estadístico, por cada archivo'),
        T('Notion AI', 'specialist', 'El ordenador inteligente de una nota de una investigación y de una gestión de un aprendizaje', 'Si ordenas y resumes, de forma automática, con Notion AI, tu nota compleja de una investigación y un material de un aprendizaje, después de que pase un tiempo, puedes encontrar, de una vez, el contenido que te hace falta. Después de introducir, en Notion, una nota de una clase, un memo de la lectura de un paper, un registro de un proyecto, si le preguntas a la IA “¿me puedes ordenar, en 1 línea cada una, las 5 centrales de esta sección?”, te estructura tu pensamiento. Ejemplo: si, después de un seminario, ordenas, con Notion AI, una nota de 20 minutos, en 5 minutos se arma un resumen y un action item. A través de esto, tú te puedes concentrar en más aprendizaje y, en una entrevista de un empleo o en la redacción de una carta de presentación, puedes mostrar, de forma sistemática, tu propia historia de un crecimiento.', '¿Me puedes leer la nota de una investigación, del último mes, dividirla, por un tema que se repite, en una categoría, y resumirme, en una unidad de un %, el estado de avance de cada categoría?')],
    syn: 'Tu diligencia alta (C 95%) y tu curiosidad intelectual (O 95%), cuando se encuentran con una herramienta de IA, se convierten en una competitividad inigualable, de asegurar, a la vez, “la profundidad de un investigador” y, a la vez, “una velocidad de una ejecución”. Con Perplexity, no dejas pasar una tendencia académica más reciente; con GitHub Copilot, reduces un tiempo de un código y experimentas más proyectos; con Notion AI, conviertes, en un activo, todo registro de un aprendizaje. Como resultado, te conviertes en “un graduado de un número alto de una cita de un paper”, “un desarrollador de una contribución alta, a un open source”, “un buscador de empleo de un portafolio sólido”, y te reevalúan, de “un experto recluso, de un enigma”, a “un experto cuya capacidad ya está demostrada”.',
    day: 'A las 8:00 de la mañana, al entrar al laboratorio, con Notion AI, ordenas, como un resumen de 3 líneas, la nota de una investigación de ayer. Las 5 cosas que hay que hacer hoy se ordenan, por una prioridad. A las 8:30, empiezas a leer un paper; antes de leerlo, le preguntas a Perplexity “los 3 conceptos centrales de este paper”. 5 minutos de una comprensión de un contexto suben un 40% la eficiencia de 1 hora de lectura que sigue. A las 10:00, retomas un código de un preprocesamiento de un dato, que estabas escribiendo ayer. Si es junto con GitHub Copilot, es un asunto que, en 30 minutos, se termina. Si escribes, con claridad, solo la intención, como un comentario, Copilot te propone un código preciso de pandas. A las 12:00, antes del almuerzo, haces un commit del código, en GitHub. Hoy, también, se añade un césped más, verde. A las 14:00, asistes a un seminario. Hablas poco, pero una sola pregunta deja sorprendido al profesor. A las 16:00, introduces, en Notion, la nota de un seminario, y le pides a la IA “¿me puedes ordenar la conclusión de este debate y la etapa siguiente?”. En 5 minutos, se completa un resumen estructurado. A las 17:00, empiezas la preparación de un empleo. Le haces leer, a Notion AI, un borrador de una carta de presentación, y recibes un feedback, de “¿estas frases revelan, lo suficiente, mi expertise?”. A las 18:00, le preguntas a Perplexity el título y el abstract de 3 papers que vas a leer mañana. Capta, en qué orden los vas a leer, y cuál es el eslabón de conexión de cada paper, y sales del laboratorio. A las 20:00, también cuando descansas, en casa, tu GitHub trabaja. Si es junto con Copilot, también una o dos líneas de un proyecto personal, todos los días, son posibles. Tú hablas poco, pero tu registro habla.'
  });
  add('11100', 'El de primer año que desarma a un compañero con un hecho, el pequeño Sócrates', 'Perplexity AI', ['Grammarly', 'NotebookLM'], {
    i: 'Tú, que, de un tirón, de madrugada, desarmaste y volviste a armar, tres veces, el material de una presentación de un paper: los miembros del equipo se admiran, de “un alto grado de terminación”, pero, por dentro, piensan “¿se vuelve a empezar, otra vez, el infierno?”. Tú no eres un perfeccionista simple. Una afirmación ilógica, un análisis sin un fundamento, un material insuficiente: todo esto se te siente como un “bug” que toca tu honestidad intelectual, y caes, de forma automática, en un modo de corrección. La combinación de una apertura alta (94%) y de una diligencia (92%) te convierte en “alguien que sube el estándar de su propio campo”. Como hay una extraversión (85%), presentas, sin miedo, ese criterio alto, y una amabilidad baja (12%) pone la prioridad, en “una gestión de una calidad, más que una gestión de una emoción”. En el campo de un empleo, quieren a alguien como tú. Solo que aprender la frontera de “con esto, basta” va a ser el secreto del crecimiento de tu carrera.',
    s: [
      'Como, en una verificación de un argumento y en una gestión de la calidad de un material, no transiges nunca, todo resultado que entregas se evalúa, de un modo profesional. Si, en una tarea de un grupo, te conviertes en el encargado de una revisión final, la confiabilidad del equipo sube de un modo notable.',
      'El deseo de adaptarte, con rapidez, a un concepto o a una teoría nueva, y de explorarla a fondo, es fuerte, así que, en un camino de un posgrado o de un puesto de investigación, obtienes una competitividad distinta.',
      'Con una extraversión alta, puedes expresar, con claridad, tu propio criterio alto y un insight, así que, en una presentación, en una entrevista, en una reunión de un equipo, desempeñas un papel proactivo y de una influencia.'
    ],
    g: [
      'Una inversión excesiva de un tiempo, por la búsqueda de una perfección, y la acumulación de un estrés, pueden llevar a un burnout. Hace falta la práctica de distinguir, de forma práctica, la frontera de “lo suficientemente bueno” y “lo perfecto”.',
      'Con una amabilidad baja y una expresión directa, los miembros del equipo pueden sentir que los están criticando, y una relación se puede enfriar. Practica, de forma consciente, el modo de transmitir, en un tono constructivo y de una colaboración, el mismo señalamiento.'
    ],
    t: [T('Perplexity AI', 'main', 'Una verificación profunda, la obtención inmediata de un argumento', 'Es la IA que va a satisfacer, de un modo legítimo, tu obsesión de “¿el fundamento es preciso?”. Mientras confirmas, en tiempo real, una investigación de un material de referencia de un paper, una verificación de una cifra estadística, una interpretación más reciente de una teoría, subes la confiabilidad de un material. Es potente, cuando verificas con rapidez la fuente de una afirmación que presentó un miembro del equipo, en una tarea de un grupo, o cuando encuentras un fundamento adicional, que le hace falta a tu afirmación. Por ejemplo, si preguntas “muéstrame, junto con una estadística reciente, de cuántos años es, con precisión, el período medio de la obtención de un grado, de un estudiante de un posgrado, en el país”, puedes recibir una respuesta, junto con una fuente en la que se puede confiar, y la puedes citar, de inmediato, en un informe.', 'Se dijo que la estrategia de marketing de nuestro equipo se basa en una investigación de la psicología de una compra, de la generación Z; ¿me puedes verificar, junto con una estadística más reciente, de 2024, de una tendencia de un consumo, de la generación Z, si esta estrategia, en la práctica, tiene un fundamento?'),
        T('Grammarly', 'specialist', 'Una expresión perfecta, una comunicación convincente', 'Tu criterio alto llega, no solo a “el contenido”, también a “la expresión”. Grammarly, más que una revisión simple de una gramática, te presenta incluso un ajuste del tono, una claridad, una capacidad de convencer. Si la aprovechas, en todo texto, como la redacción de un informe, un correo, una carta de presentación, tu contenido excepcional se transmite, aún más refinado y profesional. Por ejemplo, cuando envías, por correo, un feedback de un equipo, si Grammarly te propone “esta expresión se puede oír, de un modo crítico”, puedes volver a escribir, de un modo más colaborativo, el mismo sentido, y reduces una fricción de una relación.', '¿Me puedes volver a escribir este feedback, en un tono un poco más constructivo y de una colaboración? Del mismo contenido, pero de un modo que la otra persona lo pueda aceptar, sin la sensación de que la están criticando.'),
        T('NotebookLM', 'specialist', 'Recompone un material complejo, como un conocimiento sistemático', 'Si subes, a NotebookLM, un paper, un material de una clase, un artículo, que reuniste, se producen, de forma automática, una guía de un aprendizaje, un resumen, la generación de una pregunta. Esto te gira, hacia “una comprensión profunda”, tu deseo alto de un perfeccionismo. Por ejemplo, si subes 10 papers, relacionados con el tema de una tesis de graduación, puedes captar, de un vistazo, la conexión entre los conceptos centrales, la diferencia de un punto de un debate, el límite de cada investigación, y ver, de forma objetiva, cuán original es tu investigación.', '¿Me puedes ordenar, en una tabla, la diferencia de una metodología de una investigación que presenta cada uno, al sintetizar estos 5 papers? ¿Cuál es el método más adecuado, para nuestro proyecto?')],
    syn: 'Tu apertura alta y tu diligencia, cuando se encuentran con la IA, se convierten en “un sistema automático de una verificación”. Si aseguras un fundamento, con Perplexity AI, le añades profundidad, con NotebookLM, y pules una expresión, con Grammarly, todo resultado que entregas tiene, a la vez, “una confiabilidad académica + una expresión profesional”. En una entrevista de un ingreso a un posgrado, en una entrevista de una contratación, en la primera evaluación de un puesto, te van a reconocer como “alguien que conoce un criterio”, “alguien que, cualquier asunto, lo hace a fondo”. En especial, en un puesto en el que es importante una toma de una decisión, basada en un dato (una consultoría, una investigación, una planeación de una estrategia, un campo académico), tu capacidad de un aprovechamiento de la IA se convierte en una fortaleza que no se puede comparar, con la de un colega.',
    day: 'A las 8:30 a. m., llegas al trabajo (o llegas a la biblioteca). Mientras tomas un café, le lanzas a Perplexity “el ítem de una duda” de hoy. En 5 minutos, se termina la verificación de si es cierta, de verdad, la estadística de un material que ayer presentó un miembro del equipo, y de cuál es la versión más reciente del argumento que tú ibas a usar. Anotas “hay un fundamento” o “hace falta una corrección”. A las 9:15 a. m., antes de una clase de la mañana, reordenas, con NotebookLM, el material de una clase de la semana pasada. Si pegas, en un lugar visible, el resumen y la pregunta central, generados de forma automática, en la clase de hoy, la palabra del profesor se oye, de un modo mucho más claro. A las 11:00 a. m., la preparación de una reunión de una tarea de un grupo. Lees el borrador de los miembros del equipo y armas la lista de una pregunta, de “en esta parte, ¿cuál es la fuente?”. Cuando vas a dar un feedback, por correo, lo pasas por Grammarly y lo ajustas, a un tono “directo, pero constructivo”. A las 13:00, después del almuerzo, haces pasar, por Grammarly, las frases centrales del informe que tú mismo vas a escribir. El proceso de juzgar, por tu cuenta, si aceptas o rechazas una propuesta de una corrección de una expresión, cultiva tu capacidad de contar una historia. A las 15:00, el trabajo de concentración de la tarde. Cuando estás escribiendo una tesis de graduación, o una tarea central, en especial, en el instante en que te entra “¿esta afirmación, de verdad, es de una confiabilidad?”, la verificas, de inmediato, con Perplexity, y, al añadir, a NotebookLM, un material nuevo, reconfirmas “la consistencia de toda la lógica”. Esta repetición te convierte en “un investigador minucioso”. A las 18:00, el orden, antes de salir. Anotas, a la ligera, 3 “errores lógicos del equipo”, que descubriste hoy, y 2 “puntos de un refuerzo de mi argumento”. Armas el plan de, mañana por la mañana, tratar, primero, estas cosas. Por la noche, felicítate. Porque, si no hubiera existido tu criterio alto, el grado de terminación del equipo habría sido la mitad del de ahora.'
  });
  add('11101', 'El ambicioso rumbo al éxito, el aspirante a un futuro CEO', 'Perplexity AI', ['Elicit', 'NotebookLM'], {
    i: 'El día de la presentación de un proyecto de equipo, tú ya habías llegado, incluso, con una estrategia de una entrada al mercado, 3 meses después, preparada. Cuando los colegas se concentran en la entrega de una tarea, tú ya estás verificando el ítem del concurso siguiente. Tu fortaleza es clara. La capacidad de, una vez fijado un objetivo, encontrar la ruta más corta para alcanzarlo, un temple de convertir un fracaso, en un dato de un aprendizaje, y una capacidad de ejecución, de un empuje. Pero, si miras alrededor, se ve la imagen de que los colegas, poco a poco, van siendo perseguidos, por tu velocidad. Se le suma, incluso, una tendencia alta de un neuroticismo, y hay la tendencia de, al perseguir una perfección, tomar, de un modo grande, también un error pequeño. Si una herramienta de IA le añade tu capacidad fría de un análisis, tú, más allá de un ambicioso simple, te vas a poder desarrollar, como un líder, con una capacidad de empatía.',
    s: [
      'La velocidad de una ejecución y un empuje, para el logro de un objetivo, son excepcionales. Minimizas el tiempo de llegar, desde una etapa de una concepción, hasta un resultado práctico, y, en un concurso o en un proyecto, creas, con rapidez, un resultado.',
      'La capacidad de redefinir un fracaso es excepcional. Con una metacognición de interpretar un rechazo de un empleo, o el fracaso de una startup, como “la acumulación de un dato”, una resiliencia psicológica es excepcional, y diseñas una victoria a largo plazo.',
      'Reaccionas, con sensibilidad, a una oportunidad nueva y a una tendencia. Con una apertura alta, captas, con rapidez, una idea innovadora y, al aprovecharla de forma estratégica, te adelantas, en una competencia.'
    ],
    g: [
      'Por un centrarte en un resultado, puedes pasar por alto lo valioso de un proceso y la emoción de un colega. Si despiertas a la importancia de construir una confianza, dentro de un equipo, y de formar una relación a largo plazo, la calidad de un liderazgo sube un escalón.',
      'Por una tendencia alta de un neuroticismo, al perseguir una perfección, puedes caer en un burnout. Junto con un autocuidado, fijar el criterio de “lo suficientemente bueno” es la llave de un éxito a largo plazo.'
    ],
    t: [T('Perplexity AI', 'main', 'Con una tendencia del mercado, en tiempo real, enciéndele fuego a tu ambición', 'Tú, todas las mañanas, checas una noticia nueva de una startup y un cambio del mercado. Perplexity AI, más que una búsqueda simple, es tu equipo personal de un análisis del mercado, que te analiza, de forma integral, una información, en tiempo real. Cuando verificas la viabilidad, en el mercado, de una idea de un emprendimiento, puedes obtener, de inmediato, una respuesta, a una pregunta profunda, como “¿el tamaño, en el mercado global, de este ítem? ¿Quién es un competidor? ¿Una estrategia de una diferenciación?”. Ejemplo: “ordéname los 3 modelos de un negocio más candentes, del mercado de una educación de IA, de 2024, y el tamaño del mercado de cada uno, un caso de un éxito”. Si lo haces así, a tu ambición se le mete “una evidencia” concreta y “una cifra”, y, en un pitching de un concurso o en una reunión con un inversor, puedes desplegar una afirmación mucho más convincente.', '¿Me puedes analizar, de forma comparada, las 3 razones por las que más fracasan, en 2024, los emprendedores iniciales de un fintech, y un método de una resolución, por un caso de un éxito? Con base en una noticia práctica.'),
        T('Elicit', 'specialist', 'Con un fundamento, basado en un paper, refuerza tu idea', 'Cuando ingresas a un posgrado, o cuando haces una propuesta nueva, dentro de una organización, hay un momento en el que te hace falta, no una opinión simple, “una evidencia, con una base académica”. Elicit, al analizar, con IA, una base de un dato de un paper académico, te encuentra, en unos segundos, las investigaciones que encajan con tu hipótesis. Por ejemplo, si vas a armar una plataforma de una educación de un liderazgo, puedes buscar, con base en un paper, “el efecto que un aprendizaje personalizado, basado en IA, ejerce, en el desarrollo de un liderazgo”, y respaldar, de forma académica, tu hipótesis de un negocio. Ejemplo: “¿me puedes ordenar 5 papers más recientes, que muestren la diferencia de un efecto, de un aprendizaje personalizado, de IA, vs. una educación tradicional? Incluyendo también una estadística”. Si lo haces así, tu propuesta se arma, no de “un sentido común”, de “una evidencia”.', '¿Me puedes buscar 3 papers más recientes, de una ciencia de la administración, que traten la condición en la que, en un entorno de un trabajo remoto, se refuerzan la creatividad de un equipo y una innovación, y resumirme, en 2 líneas cada uno, el hallazgo central de cada paper?'),
        T('NotebookLM', 'specialist', 'Transforma tu material de un emprendimiento, en una clase de IA', 'Tú tienes mucho material. Un material de un pitching de un concurso, un informe de una investigación del mercado, un documento de un análisis de un competidor. NotebookLM, si subes todo este material, la IA lo analiza y te ayuda a que tú mismo despiertes al núcleo. Además, incluso te arma “un aprendizaje en audio”, basado en un material, así que, también de camino al trabajo, puedes interiorizar una información que reuniste. Ejemplo: si metes, en NotebookLM, “5 informes de un análisis del mercado”, que escribiste, en los 3 meses recientes, la IA, de forma automática, te ordena “cuál es el insight que dejaste pasar, y qué investigación, de la etapa siguiente, tienes que hacer”. Ejemplo: “¿me puedes proponer las 3 tendencias que, en común, aparecen, en los materiales de un análisis del mercado que subí, y, con esto de base, la acción siguiente que hay que hacer?”. Tu ciclo de un análisis se acelera.', '¿Me puedes encontrar un patrón común, en A. un informe del mercado de un fintech, B. un caso de una plataforma de una educación de IA, C. un material de un análisis de un comportamiento de un consumidor, de 2024, que subí, y presentarme 3 oportunidades nuevas de un negocio, que combinen estos 3 campos?')],
    syn: 'Tu tendencia 11101, cuando se encuentra con la IA, crea una competitividad inigualable, de “una capacidad fría de un análisis + la maximización de una capacidad de ejecución”. Si lees el mercado, con Perplexity, verificas, de forma académica, una hipótesis, con Elicit, e integras, con NotebookLM, todo insight, tú, no un simple hombre de una idea, te conviertes en “un estratega, basado en una evidencia”. En un concurso, un primer premio; en una entrevista de un empleo, te reconocen, con “un mindset de un CEO”; cuando ejecutas un emprendimiento, se hace realidad tu imagen, de recibir una inversión, con una tasa alta de un éxito. En especial, si complementas, con un dato objetivo, de la IA, una tendencia alta de un neuroticismo, el hábito de reprocharte, por un perfeccionismo, se convierte, de forma positiva, en “la reunión de un feedback, para la etapa siguiente”.',
    day: 'A las 8:00 de la mañana, en un café, con Perplexity AI, buscas “una noticia del mercado de un fintech y de una educación, desde ayer hasta esta mañana”. Captar, en 5 minutos, el pulso del mercado, es el comienzo de tu rutina del día. A las 9:00 de la mañana, subes, a NotebookLM, “3 informes de un análisis de un competidor”, que escribiste ayer, y, mientras oyes un audio de “un insight que dejaste pasar”, que armó la IA, te duchas. A las 10:00, entras a una sala de una reunión y le presentas, al equipo, una estrategia nueva: el fundamento es claro. En el horario del almuerzo, de cara a una reunión con un inversor, buscas, con Elicit, “el efecto de un aprendizaje personalizado, basado en IA”, encuentras 5 papers más recientes y se los añades a una presentación. A las 14:00, mientras lees los papers que te encontró Elicit, dices “ah, este ángulo no lo había visto”, y tu hipótesis se vuelve más refinada. A las 16:00, para verificar un ítem nuevo de un emprendimiento, le preguntas a Perplexity “el tamaño, en el mercado global, de este ítem, y el estado de un competidor”. En 30 minutos, a tu ambición se le mete una cifra concreta. A las 18:00, después de salir, oyes, una vez más, en el smartphone, “las 3 centrales de hoy”, que ordenó NotebookLM, y ordenas el action item de mañana. Así, tu día se mueve, no por “una intuición”, por “una evidencia”, y la ambición se sigue acercando, a una realidad.'
  });
  add('11110', 'Quien, en cualquier equipo, se adapta con rapidez: el postulante de un alto grado de terminación, sereno', 'Claude', ['Gamma', 'Notion AI'], {
    i: 'Tú, con una creatividad, una diligencia, una sociabilidad y una amabilidad, todas altas, y emocionalmente estable, incluso entre los buscadores de empleo, eres un postulante de un alto grado de terminación. En cualquier equipo en el que entres, te adaptas con rapidez y sacas un resultado, y eres el tipo que, tanto una carta de presentación como una entrevista, las hace bien, de forma natural. Solo que ten cuidado de, al perseguir, en exceso, una perfección, no dejar pasar el timing de una postulación.',
    s: [
      'Una creatividad y una diligencia altas se combinan, y, en una carta de presentación, armas una historia original y, a la vez, sistemática.',
      'Con una sociabilidad y una amabilidad excepcionales, en una entrevista de un grupo o en una entrevista de un equipo, ejerces una presencia y, a la vez, respetas a otro.',
      'Como hay una estabilidad emocional, también en un período largo de la búsqueda de un empleo, no pierdes el ritmo y sigues, con constancia, una actividad de una postulación.'
    ],
    g: [
      'Hay la tendencia de posponer una entrega, por una carta de presentación perfecta. Prueba introducir el principio de “después de una terminación de un 80, la entrega; el resto, lo mejoro, en la postulación siguiente”.',
      'Más que una estrategia de postular, de un modo uniforme, a empresas diversas, puede hacer falta una selección y una concentración, de estrechar una empresa y un puesto objetivo, claros.',
      'Si nace el hábito de compararte, con la noticia del empleo de otro, el temple se sacude. Confía en tu propia línea de tiempo.'
    ],
    t: [T('Claude', 'main', 'El socio de un storytelling, de un alto grado de terminación, de una carta de presentación', 'Cuéntale a Claude una empresa y un puesto a los que postulas y, juntos, elijan, de tu experiencia, cuál encaja más. Te ayuda, desde la elección de una fortaleza hasta una expresión.', 'En una carta de presentación de un puesto de marketing, quiero escribir “una experiencia de una resolución creativa de un problema”; ordéname, con el método STAR, una experiencia de una planeación de un club universitario.'),
        T('Gamma', 'specialist', 'Completa, con rapidez, un portafolio y un material de una entrevista de una presentación', 'Si, para una empresa a la que le hace falta una entrevista de una presentación, o la entrega de un portafolio, completas una diapositiva, con Gamma, tu creatividad se transmite bien, de forma visual.', 'Ármame una diapositiva de una presentación de 5 minutos, para una entrevista de una presentación, de un marketer de primer ingreso. Con el tema de “una tendencia de un marketing digital y un modo de mi contribución”.'),
        T('Notion AI', 'specialist', 'Gestiona, de forma sistemática, todo el proceso de la búsqueda de un empleo', 'Si sistematizas, con Notion AI, una versión de una carta de presentación, por empresa, una cita de una entrevista, el estado de una aprobación o de un rechazo, tu diligencia se ejerce, sin un desperdicio.', 'Ármame una tabla de Notion, con la que, de un vistazo, se puedan ver la pregunta de una carta de presentación, una fecha límite, un material necesario, de 5 empresas a las que voy a postular, esta semana.')],
    syn: 'Tú, con casi todas las tendencias altas, y estable, tienes que usar la IA, como una herramienta de una aceleración, que te hace “más rápido, de un grado de terminación aún más alto”. Tu capacidad ya es suficiente, así que concéntrate, a través de la IA, en subir la velocidad y en confirmar la confianza.',
    day: 'A las 8:30, con Notion AI, el chequeo del estado de una postulación de hoy. A las 10:00, con Claude, el pulido de una carta de presentación. A las 14:00, una investigación de una empresa y la entrega de un expediente. A las 17:00, con Gamma, la preparación de una presentación o de un portafolio. A las 21:00, la preparación de una entrevista. A las 22:30, después de fijar un solo objetivo de mañana, a dormir.'
  });
  add('11111', 'Quien lo reúne todo y, aun así, duda de si basta: el buscador de empleo completo y sensible', 'Claude', ['Notion AI', 'Wysa'], {
    i: 'Tú, al que le desbordan todas las capacidades y, en la misma medida, también la inquietud es alta, eres el tipo que, en el campo de batalla de la búsqueda de un empleo, se va agotando, al intentar tenerlo todo, de forma perfecta. El currículum también es bueno, y el carácter también es bueno, pero una duda de ti mismo, de “¿con esto, basta?”, te agarra el tobillo. Si, junto con la IA, empiezas una autoevaluación objetiva, te puedes liberar, de una inquietud innecesaria.',
    s: [
      'Como la creatividad, la diligencia, la sociabilidad y la amabilidad son, todas, altas, tienes una capacidad para todo, de reaccionar, con flexibilidad, en cualquier etapa de la búsqueda de un empleo.',
      'En un proyecto de equipo o en una entrevista de un grupo, ejerces un liderazgo equilibrado, de conducir el ambiente y, a la vez, de considerar a otro.',
      'Absorbes, con rapidez, una información nueva, la conectas con tu propia experiencia y, en una carta de presentación o en una entrevista, armas una historia convincente.'
    ],
    g: [
      'La ambición de tenerlo todo, de forma perfecta, al contrario, obstaculiza una selección y una concentración. Hace falta una estrategia de concentrarte, en “una sola fortaleza central, tuya”.',
      'Por una sensibilidad alta, un solo aviso de un rechazo te puede herir, en exceso. Prueba redefinir la búsqueda de un empleo, como un proceso de la acumulación de una experiencia.',
      'Si reduces el hábito de compararte, con el currículum de los demás, y te concentras en construir tu propia narración, se convierte en una diferenciación.'
    ],
    t: [T('Claude', 'main', 'El socio que pule, del modo más convincente, una historia de una carta de presentación', 'Suéltale a Claude, con sinceridad, tu propia experiencia y, juntos, armen una historia de una fortaleza. Te ordena tu capacidad diversa, como una sola narración consistente.', 'Soy un buscador de empleo del tipo OCEAN 11111. Quiero escribir, en una carta de presentación, “una experiencia de haber resuelto un conflicto”; ordéname, con la técnica STAR, mi experiencia.'),
        T('Notion AI', 'specialist', 'El hub que gestiona, de forma sistemática, todo el proceso de la búsqueda de un empleo', 'Si gestionas, de un vistazo, con Notion AI, la lista de una empresa a la que postulas, el estado de la entrega de un expediente, una cita de una entrevista, puedes buscar un empleo, de forma estratégica, sin dejar pasar nada.', 'Ármame una plantilla de Notion, de una gestión de la búsqueda de un empleo. Incluyendo el nombre de una empresa, un puesto al que postulo, una fecha límite de un expediente, si hubo una aprobación o un rechazo, una casilla de un memo.'),
        T('Wysa', 'specialist', 'La IA de un cuidado del temple, que consuela el estrés y la inquietud, de la búsqueda de un empleo', 'Cuando recibes un aviso de un rechazo, o cuando sube la inquietud, si le sueltas a Wysa una emoción, puedes aliviar, con rapidez, un golpe psicológico.', 'Hoy me rechazaron, en una entrevista final. Me cuesta demasiado, pero quiero volver a tomar el corazón y encontrar la fuerza de, a partir de mañana, seguir la búsqueda de un empleo.')],
    syn: 'Tú, de todas las tendencias altas, despliegas el verdadero valor, cuando aprovechas la IA, no con un propósito único, como el coach de toda una estrategia de la búsqueda de un empleo. Si pules una narración, con Claude, gestionas una estrategia, con Notion AI, y proteges el temple, con Wysa, es posible una búsqueda de un empleo sostenible.',
    day: 'A las 8:00, con Wysa, el chequeo del ánimo de la mañana. A las 9:00, con Notion AI, la confirmación de una empresa a la que postular hoy. A las 10:00, con Claude, el pulido de una pregunta de una carta de presentación. A las 14:00, una investigación de una empresa y la entrega de una postulación. A las 20:00, la preparación de una entrevista, o una redacción adicional de una carta de presentación. A las 22:00, con Wysa, el orden de la emoción del día.'
  });
})();

